const SUBTITLES_FR_CH1 = [
{ start: 1.000, end: 12.120, text: 'Bienvenue dans le programme BRIDGE -<font color="#FFFF00"> Bridging Research and Inclusive Digital Education</font>' },
  { start: 12.130, end: 19.630, text: 'Nous allons maintenant aborder la conférence jour qui concerne la question' },
  { start: 19.631, end: 23.830, text: 'de l\'intégration de personnes avec un <font color="#FFFF00">handicap</font>' },
  { start: 24.220, end: 27.170, text: 'On en tout cas, ayant des blocages lors de l\'enseignement.' },
  { start: 27.350, end: 31.570, text: 'Il y aura une connotation "<font color="#FFFF00">Handicap</font>" importante dans cette présentation.' },
  { start: 32.155, end: 36.750, text: 'Mais cela concerne essentiellement "L\'<font color="#FFFF00">Enseignement Inclusif</font>"' },
  { start: 37.295, end: 40.530, text: 'Nous allons commencer par un premier chapitre qui est des constats,' },
  { start: 40.531, end: 45.630, text: 'la volumétrie, qui sont des personnes concernées par cette conférence ?' },
  { start: 63.885, end: 66.527, text: 'Ceci est un regard de la volumétrie concernant' },
  { start: 66.577, end: 69.160, text: 'les étudiantes et les étudiants <font color="#FFFF00">handicapés</font>.' },
  { start: 70.019, end: 73.571, text: 'En fait, cela représente, pour simplifier' },
  { start: 73.572, end: 77.020, text: '3% de la population étudiante qu\'on a en France.' },
  { start: 77.720, end: 84.740, text: 'Donc c\'est autour de reconnu, aujourd\'hui, on est autour de 60 000 étudiants.' },
  { start: 85.139, end: 89.080, text: 'Ces chiffres sont trompeurs et, en particulier, ils ne sont pas révélateurs' },
  { start: 89.081, end: 92.180, text: 'de l\'intégralité des <font color="#FFFF00">handicaps</font> que l\'on peut rencontrer.' },
  { start: 92.720, end: 97.540, text: 'En tout cas, révélateur de la population que nous avons dans la classe.' },
  { start: 98.740, end: 106.540, text: 'On est fait sur ces 3%, 70% sont des <font color="#FFFF00">handicaps invisibles</font>,' },
  { start: 106.949, end: 110.640, text: 'en tout cas, il est très difficile de détecter à la première vue,' },
  { start: 111.039, end: 116.040, text: 'parce qu\'elles peuvent concerner des <font color="#FFFF00">troubles psychiques</font>, des maladies qui' },
  { start: 116.040, end: 121.700, text: 'sont invalidantes, des <font color="#FFFF00">troubles cognitifs</font>, le <font color="#FFFF00">DYS</font> étant le trouble le plus connu,' },
  { start: 122.680, end: 127.960, text: 'ou des formes d\'<font color="#FFFF00">autisme</font>, qui sont tout à fait aptes à suivre un enseignement.' },
  { start: 128.900, end: 131.940, text: 'Donc de l\'<font color="#FFFF00">autisme</font> de base. Ici, c\'est autour de 5%.' },
  { start: 134.810, end: 137.864, text: 'Les <font color="#FFFF00">handicaps invisibles</font> concernent aussi' },
  { start: 137.865, end: 141.800, text: 'des <font color="#FFFF00">troubles de la parole</font>, qui sont autour de 22%.' },
  { start: 141.801, end: 149.680, text: 'Les <font color="#FFFF00">troubles cognitifs</font> (droite et en bas), sont autour de 6%.' },
  { start: 150.255, end: 156.020, text: 'Par contre, 1 étudiant <font color="#FFFF00">handicapé</font> sur 3 des troubles' },
  { start: 156.021, end: 160.700, text: '<font color="#FFFF00">Visibles</font>, qui sont les <font color="#FFFF00">troubles moteurs</font>, les <font color="#FFFF00">troubles visuels</font> (troubles de vue...' },
  { start: 160.701, end: 165.740, text: 'voire totalement aveugle), et des <font color="#FFFF00">problèmes auditifs</font>, voire totalement sourd.' },
  { start: 165.984, end: 170.780, text: 'Ici, la majorité des troubles visibles qu\'on peut voir, ont des <font color="#FFFF00">handicaps</font>' },
  { start: 170.781, end: 174.680, text: 'du <font color="#FFFF00">trouble moteur</font> (autour de 10%).' },
  { start: 176.280, end: 179.141, text: 'Comme vous pouvez voir et dit,' },
  { start: 179.142, end: 181.660, text: '2/3 ne sont pas visibles, 1/3 sont visibles.' },
  { start: 182.380, end: 188.420, text: 'Si on regarde la répartition de ces étudiants en difficulté,' },
  { start: 188.421, end: 195.300, text: 'dans l\'ES, on voit qu\'ils sont essentiellement concentrés sur les' },
  { start: 195.301, end: 199.527, text: 'universités, qui "captent" ou accueillent en tout cas' },
  { start: 199.528, end: 203.880, text: 'au moins 8 étudiants <font color="#FFFF00">handicapés</font> sur 10.' },
  { start: 204.560, end: 209.620, text: 'Ensuite, on voit que le deuxième niveau est les établissements privés' },
  { start: 209.621, end: 214.140, text: 'd\'intérêt général, qu\'on appelle, en général, les "EESPIG" les' },
  { start: 214.141, end: 219.040, text: 'Établissement Enseignement Supérieur Privé d\'Intérêt Général qui,' },
  { start: 219.041, end: 223.340, text: 'aujourd\'hui, ces chiffres sont plus élevés car autour de 8 à 10%.' },
  { start: 223.440, end: 229.260, text: 'Les chiffres que je vous présente ici dans le carré à droite, à gauche, et,' },
  { start: 229.435, end: 232.420, text: 'en fait, sont anciens, de 2024' },
  { start: 234.000, end: 240.120, text: 'Concernant, les classes prépa et les lycées de l\'éducation nationale,' },
  { start: 240.554, end: 244.680, text: 'on est autour de 4 à 5 % des <font color="#FFFF00">handicapés</font>.' },
  { start: 245.040, end: 247.803, text: 'Et ensuite, sur les autres écoles publiques, ils' },
  { start: 247.804, end: 251.640, text: 'sont hors de l\'université, on est autour de 3 à 4 %.' },
  { start: 252.340, end: 258.279, text: 'Donc, pour simplifier, nous voyons, qu\'une petite partie de l\'<font color="#FFFF00">handicap</font>' },
  { start: 258.380, end: 263.300, text: 'et en tout cas, on en voit que 1% des <font color="#FFFF00">handicapés</font>.' },
  { start: 264.085, end: 268.840, text: 'Ce qui est remarquable, (ce que j\'ai noté au milieu de l\'encadré à droite)' },
  { start: 268.841, end: 272.520, text: 'c\'est si on regarde les domaines des sciences,' },
  { start: 273.120, end: 277.280, text: 'et bien, il y a eu que 29 %, 1/3 pour faire simple, des' },
  { start: 277.281, end: 279.480, text: '<font color="#FFFF00">handicapés</font> qui vont dans les domaines scientifiques.' },
  { start: 280.740, end: 286.500, text: 'Il est donc tout à fait légitime, qu\'un enseignant, un prof,' },
  { start: 287.125, end: 288.125, text: 'vous dit' },
  { start: 288.185, end: 290.860, text: '"Excuse-moi, mais je n\'ai pas d\'<font color="#FFFF00">handicapé</font> dans ma classe".' },
  { start: 291.600, end: 294.840, text: 'Soit il n\'y en a effectivement pas parce que la population est assez faible ..' },
  { start: 295.480, end: 301.140, text: 'ou soit, s\'il y en a, il ne le sera pas visible si on ne le lui dit pas !' },
  { start: 305.460, end: 309.440, text: 'Alors, ces chiffres sont en opposition avec le sentiment que l\'on peut' },
  { start: 309.441, end: 313.400, text: 'avoir lorsqu\'on regarde la population des étudiantes et des étudiants,' },
  { start: 313.540, end: 314.620, text: 'nous avons dans les salles.' },
  { start: 315.420, end: 321.000, text: 'Et en particulier sur la question des <font color="#FFFF00">DYS</font>, qui sont ...' },
  { start: 321.195, end: 325.140, text: 'les problèmes, les <font color="#FFFF00">handicaps</font>, liés à un <font color="#FFFF00">trouble cognitif</font> durable.' },
  { start: 326.000, end: 333.040, text: 'Je rappelle le <font color="#FFFF00">DYS</font> est "médical", et n\'a pas de relation avec la catégorie' },
  { start: 333.041, end: 336.132, text: 'sociale professionnelle, des parents ou de l\'étudiant,' },
  { start: 336.133, end: 338.860, text: 'donc il est totalement indépendant du milieu social (CSP).' },
  { start: 339.645, end: 341.777, text: 'et aussi de l\'origine linguistique, le <font color="#FFFF00">DYS</font> arrive ...' },
  { start: 341.778, end: 344.660, text: 'dans toutes les populations autour du globe.' },
  { start: 346.025, end: 350.800, text: 'Sur la population, j\'affichais des chiffres autour de 7%,' },
  { start: 351.410, end: 352.864, text: 'c\'est à peu près ce que nous avons.' },
  { start: 352.865, end: 357.820, text: 'Et si on regarde des formes les plus sévères du <font color="#FFFF00">DYS</font>, c\'est autour de 3 à 5%.' },
  { start: 359.360, end: 363.140, text: 'La reconnaissance du <font color="#FFFF00">DYS</font> se fait d\'une façon très claire' },
  { start: 363.640, end: 369.680, text: 'C\'est la différence - c\'est le gap, qu\'on peut constater entre le comportement' },
  { start: 369.855, end: 375.520, text: 'à l\'oral et relationnel d\'un étudiant, qui comprend totalement le cours oral,' },
  { start: 375.870, end: 380.880, text: 'qui a un vocabulaire riche, qui a une excellente compréhension des concepts,' },
  { start: 381.305, end: 385.480, text: 'et même s\'ils sont complexes, il peut avoir quelques situations,' },
  { start: 386.140, end: 387.399, text: 'quelques inversions de temps en temps.' },
  { start: 387.400, end: 389.360, text: 'mais cela reste mineur.' },
  { start: 389.575, end: 392.931, text: 'Par contre, lorsqu\'on passe sur de l\'écrit et en particulier' },
  { start: 392.932, end: 396.420, text: 'lorsqu\'il doit comprendre un énoncé ou doit l\'écrire...' },
  { start: 396.920, end: 403.220, text: 'Et bien, on a l\'<font color="#FFFF00">handicap</font> qui se révèle avec des fautes d\'orthographe' },
  { start: 403.221, end: 407.320, text: 'mais c\'est un effet induit, un biais de la <font color="#FFFF00">dyslexie</font>' },
  { start: 407.445, end: 410.320, text: 'mais il y a des fusions, des lenteurs, des inversions de mots.' },
  { start: 411.830, end: 415.740, text: 'Et qui rend les sources difficiles pour eux en tout cas, il y a une vraie' },
  { start: 415.741, end: 418.940, text: 'fatigue cognitive liée à cette difficulté de l\'écrit.' },
  { start: 419.460, end: 425.080, text: 'Donc, c\'est le gap, entre ce qu\'on voit du personnage et son rendu écrit,' },
  { start: 425.360, end: 430.760, text: 'qui est une caractéristique du <font color="#FFFF00">DYS</font>. Cette caractéristique a une solution,' },
  { start: 431.585, end: 434.820, text: '"médicale" même si le terme n\'est pas approprié.' },
  { start: 435.455, end: 438.045, text: 'La première chose, et c\'est vrai que c\'était efficace,' },
  { start: 438.046, end: 440.300, text: 'il faut éviter tout ce qui est fatigue' },
  { start: 440.450, end: 444.040, text: 'les "<font color="#FFFF00">Fatigues Cognitives</font>", en clair, c\'est de ne plus de temps.' },
  { start: 444.820, end: 447.799, text: 'Et puis certains bilans orthophoniques en particulier' },
  { start: 447.800, end: 450.800, text: 'sont assez efficaces pour corriger ce genre de choses.' },
  { start: 452.260, end: 455.290, text: 'Et puis, nous avons une population d\'étudiantes et d\'étudiants' },
  { start: 455.291, end: 458.200, text: 'qui sembleraient avoir le même problème, en particulier à l\'écrit' },
  { start: 459.870, end: 463.000, text: 'Mais quand on regarde, l\'oral est aussi un problème.' },
  { start: 463.785, end: 466.720, text: 'C\'est en fait un déficit d\'apprentissage de la langue.' },
  { start: 467.020, end: 469.896, text: 'Et comparativement, aux <font color="#FFFF00">DYS</font> que nous avons vu' },
  { start: 469.897, end: 472.320, text: 'ici sur le tableau et la colonne de gauche.' },
  { start: 473.020, end: 475.720, text: 'Ici, ce sont des solutions durables.' },
  { start: 476.450, end: 481.320, text: 'C\'est-à-dire que le problème va disparaître, avec le temps, en faisant des' },
  { start: 481.545, end: 487.100, text: 'pratiques, une disposition régulière à la langue, à la culture,' },
  { start: 487.101, end: 490.840, text: 'mais aussi extrêmement diversifiées sous la forme.' },
  { start: 491.825, end: 494.405, text: 'Et on peut, citer par exemple, des cours de <font color="#FFFF00">FLE</font> qui' },
  { start: 494.406, end: 498.140, text: 'existent dans tous les établissements aujourd\'hui, qui aident beaucoup' },
  { start: 498.141, end: 502.040, text: 'C\'est un soutien logistique, il faut mettre en place, et qui permet une' },
  { start: 502.041, end: 505.920, text: 'progression rapide et définitive, et ce n\'est pas du tout "médical".' },
  { start: 506.840, end: 511.860, text: 'Par contre, il est vrai que la population concernée est importante au' },
  { start: 511.861, end: 516.500, text: 'on estime aujourd\'hui, que les formes d\'"<font color="#FFFF00">illettrisme</font>", c\'est-à-dire une incapacité à' },
  { start: 516.501, end: 522.919, text: 'écrire, ou à comprendre un texte, est autour de 7% de la population 8-65 ans' },
  { start: 522.920, end: 527.340, text: 'ce sont les chiffres nationaux, et si on regarde les étudiants,' },
  { start: 527.520, end: 532.140, text: 'donc un indicateur, ce sont les primo-entrants après le BAC' },
  { start: 532.989, end: 535.720, text: 'on arrive à une population de 10 à 15%.' },
  { start: 536.419, end: 540.820, text: 'Ici on a une vraie difficulté, puisque ces étudiants ont un vocabulaire' },
  { start: 540.845, end: 545.560, text: 'limité à l\'oral et à l\'écrit, et ils ont aussi des difficultés de' },
  { start: 547.504, end: 554.380, text: 'compréhension, mais ce n\'est pas du <font color="#FFFF00">DYS</font>. Le <font color="#FFFF00">DYS</font> va avoir un soutien "légal",' },
  { start: 554.500, end: 561.060, text: 'pour aider, en tout cas retirer la barrière de l\'<font color="#FFFF00">handicap</font>,' },
  { start: 561.209, end: 564.980, text: 'tandis que dans l\'autre cas il n\'y a pas de disposition légale.' },
  { start: 572.809, end: 576.940, text: 'On peut étendre cette réflexion, que nous venons d\'avoir entre les' },
  { start: 577.039, end: 581.200, text: '<font color="#FFFF00">DYS</font> et des personnes qui ont des problèmes d\'acquisition de la langue Française' },
  { start: 581.729, end: 587.820, text: 'à d\'autres types d\'<font color="#FFFF00">handicaps</font> ou en tout cas, si ce n\'est pas un' },
  { start: 587.821, end: 591.840, text: '<font color="#FFFF00">handicap</font>, ce sont clairement des obstacles à l\'apprentissage.' },
  { start: 594.099, end: 597.380, text: 'Je le représente sous la forme d\'oignon, avec des couches successives.' },
  { start: 598.380, end: 601.820, text: 'Le cœur, nous on n\'a pas parlé, ce sont des <font color="#FFFF00">handicaps</font> qui seront connus,' },
  { start: 601.900, end: 607.120, text: 'avec un 1/3 pour le visible, 2/3 pour le non visible,' },
  { start: 607.260, end: 608.139, text: 'mais déclaré.' },
  { start: 608.140, end: 612.380, text: 'Et le chiffre que je vous ai indiqué tout à l\'heure autour des 60, 70 mille,' },
  { start: 612.554, end: 615.920, text: '64 000 ici, est assez clair.' },
  { start: 616.380, end: 621.060, text: 'Mais derrière, il y a encore des <font color="#FFFF00">handicaps invisibles</font> qui ne sont pas déclarés.' },
  { start: 622.339, end: 627.380, text: 'Donc, on retrouve l\'<font color="#FFFF00">Autisme</font> Des maladies chroniques à vie' },
  { start: 627.555, end: 630.580, text: 'qui peuvent se retrouver dans la question de <font color="#FFFF00">handicap</font>, les <font color="#FFFF00">DYS</font>, etc.' },
  { start: 634.600, end: 640.880, text: 'Mais derrière tout ça, il peut y avoir des états de santé qui mettent l\'étudiant' },
  { start: 640.881, end: 643.800, text: 'situation difficile pour son apprentissage.' },
  { start: 644.549, end: 649.900, text: 'C\'est la douleur ou des <font color="#FFFF00">maladies invalidantes</font>, les cancers' },
  { start: 650.100, end: 654.860, text: 'on a des étudiants qui sont sous traitement, qui sont fatigués, qui ont des problèmes' },
  { start: 654.861, end: 658.321, text: 'de sommeil, et cela peut être aussi, il' },
  { start: 658.322, end: 661.500, text: 'faut donner du temps pour qu\'ils puissent se changer.' },
  { start: 662.099, end: 666.520, text: 'des problèmes d\'incontinence liés à une intervention chirurgicale, par exemple' },
  { start: 666.720, end: 671.418, text: 'ou s\'il faut s\'injecter un traitement,' },
  { start: 671.419, end: 675.520, text: 'on oublie souvent le cas des diabétiques.' },
  { start: 675.944, end: 681.580, text: 'En tout cas, on a une population d\'étudiants en santé précaire,' },
  { start: 681.800, end: 688.900, text: 'soit d\'une façon ponctuelle soit chronique et de courte durée' },
  { start: 688.901, end: 692.660, text: 'soit sur toute la durée de l\'enseignement.' },
  { start: 694.015, end: 696.696, text: 'Au-delà de la santé, il est bon aussi' },
  { start: 696.697, end: 699.120, text: 'd\'intégrer les questions liées à la psychologie.' },
  { start: 700.319, end: 705.720, text: 'On le connaît depuis l\'arrivée du COVID, il y a d\'autres problèmes - des obstacles,' },
  { start: 706.029, end: 711.200, text: 'à l\'enseignement, qui sont le stress et l\'anxiété, les angoisses, les situations de' },
  { start: 711.201, end: 717.600, text: 'détresse et surtout ce qu\'il ne faut pas ignorer pour les étudiants qui ont' },
  { start: 717.601, end: 722.100, text: 'quitter leurs parents pour une autre région, des questions liées à l\'isolement.' },
  { start: 724.149, end: 730.100, text: 'On peut considérer aujourd\'hui cela concerne 1 étudiant sur 3.' },
  { start: 731.185, end: 736.260, text: 'Et enfin le dernier, à ne pas négliger parce qu\'il représente beaucoup' },
  { start: 736.261, end: 740.000, text: 'd\'étudiants, c\'est des incidents ponctuels ...' },
  { start: 740.001, end: 744.860, text: 'ou durables dans la vie personnelle de l\'étudiant.' },
  { start: 745.939, end: 750.860, text: 'Par exemple, le deuil lorsque l\'un des parents ou un proche de' },
  { start: 750.861, end: 755.020, text: 'la famille décède, l\'étudiant perd sa capacité à apprendre.' },
  { start: 756.060, end: 761.107, text: 'On peut citer aussi les étudiants qui sont des parents' },
  { start: 761.108, end: 765.220, text: 'on verra que c\'est la même volumétrie que les <font color="#FFFF00">handicapés</font>.' },
  { start: 765.980, end: 771.180, text: 'Les étudiants qui sont en <font color="#FFFF00">précarité</font> numérique, financière ou de logement,' },
  { start: 771.181, end: 776.380, text: 'c\'est-à-dire qu\'ils ne peuvent pas loger dans l\'endroit où ils ont leur formation.' },
  { start: 778.295, end: 783.040, text: 'Et cela conduit à des durées de transport considérables pour pouvoir venir' },
  { start: 783.041, end: 787.780, text: 'ou au fait, qu\'il va se trouver un travail, afin de payer leurs études,' },
  { start: 788.180, end: 792.200, text: 'et donc ils sont des salariés-étudiants.' },
  { start: 792.819, end: 795.637, text: 'Le statut qui est propre à cela et qui est le statut' },
  { start: 795.638, end: 799.580, text: 'de l\'"Apprenti" ne s\'applique pas pour eux.' },
  { start: 799.680, end: 803.760, text: 'Sur les questions de précarité, on a le cas des étudiants' },
  { start: 803.934, end: 807.960, text: 'qui ne s\'alimentent pas d\'une façon correcte ou quotidiennement.' },
  { start: 808.740, end: 814.240, text: 'Il faut intégrer ce genre d\'obstacles à l\'apprentissage qui sont aussi ...' },
  { start: 814.969, end: 819.274, text: 'peu visibles, voire invisibles pour certains,' },
  { start: 819.275, end: 823.980, text: 'on ne le saura pas si l\'étudiante ou l\'étudiant ne nous informe pas.' },
  { start: 824.600, end: 828.680, text: 'Et cela représente 1 étudiante sur 5 en moyenne.' },
  { start: 828.954, end: 834.660, text: 'Et ça peut changer selon les catégories socio-professionnelles de l\'étudiant.' },
  { start: 838.570, end: 844.670, text: 'Essayons de fixer les grands volumes, la volumétrie de ces différents cas.' },
  { start: 844.950, end: 849.990, text: 'j\'en ai choisi 6, 5 plus l\'<font color="#FFFF00">handicap</font> qui est le sujet d\'intérêt aujourd\'hui' },
  { start: 849.991, end: 855.810, text: 'qui sont autour de la Parentalité, de la Santé' },
  { start: 855.959, end: 862.710, text: 'des problèmes de santé hors <font color="#FFFF00">Handicap</font>, une catégorie que je suis avec attention' },
  { start: 862.711, end: 866.190, text: 'qui est la question des étudiants qui sont des <font color="#FFFF00">Aidants</font>,' },
  { start: 866.395, end: 871.950, text: 'pour les membres de la famille ou autre la <font color="#FFFF00">Précarité</font>, qui est à la fois...' },
  { start: 871.951, end: 876.450, text: '... financière ou autre, et puis le cas particulier des étudiants avec un contrat' },
  { start: 876.451, end: 880.470, text: 'de travail, et qui ont donc le statut d\'Etudiants-Salariés' },
  { start: 881.829, end: 886.090, text: 'La première catégorie qui est totalement à gauche, est' },
  { start: 886.091, end: 891.330, text: 'les Etudiants Parents, qui ont des enfants, qui doivent avoir un' },
  { start: 891.331, end: 895.790, text: 'équilibre entre leur vie de parent pour s\'occuper de leurs enfants ...' },
  { start: 896.025, end: 897.025, text: '... et leurs études.' },
  { start: 897.395, end: 900.810, text: 'On chiffre aujourd\'hui que ...' },
  { start: 900.811, end: 902.774, text: 'c\'est à peu près le même volume que de' },
  { start: 902.775, end: 905.330, text: '<font color="#FFFF00">Handicap</font>, c\'est à dire autour de 2%.' },
  { start: 906.619, end: 912.370, text: 'L\'<font color="#FFFF00">Handicap</font>, le 2ème cas, nous en avons parlé, "visible" aujourd\'hui c\'est à dire' },
  { start: 913.504, end: 921.030, text: 'référencé autour de 2,2% avec 64-68 000 étudiants concernés, et 1/3 visible' },
  { start: 921.129, end: 923.750, text: 'et 2/3 non visible mais déclarés' },
  { start: 925.419, end: 930.290, text: 'Les questions de santé "récurrentes" qui peuvent être des cancers, des diabètes' },
  { start: 930.291, end: 936.310, text: 'qui peuvent être des maladies diverses attrapées au moment de la scolarité' },
  { start: 936.359, end: 940.750, text: 'cela concerne quand même 9% des étudiants, donc il faut faire' },
  { start: 940.775, end: 946.950, text: 'attention à ces étudiants qui n\'affichent pas forcément qu\'ils ont un problème' },
  { start: 947.149, end: 952.210, text: 'de santé, mais qu\'il va falloir prendre en considération dans notre étude.' },
  { start: 954.299, end: 960.490, text: 'Les <font color="#FFFF00">Aidants</font>, étudiants de la 4ème catégorie, qu\'on trouve souvent' },
  { start: 960.589, end: 965.350, text: 'dans les CSP de base, on trouve particulièrement dans le domaine' },
  { start: 965.351, end: 968.063, text: 'des agriculteurs, ce sont des étudiants qui consacrent' },
  { start: 968.163, end: 972.990, text: 'une grande partie de leur temps à aider un proche.' },
  { start: 973.239, end: 978.310, text: 'Un parent, mais ça peut être aussi un frère, enfant <font color="#FFFF00">handicapé</font>, etc' },
  { start: 982.801, end: 985.250, text: 'pendant des années, on ne le voyait pas.' },
  { start: 985.390, end: 990.150, text: 'Il est autour de 13-15% dans nos établissements.' },
  { start: 992.509, end: 997.370, text: 'Le numéro 5, la précarité financière, fait l\'objet de beaucoup de débats,' },
  { start: 997.510, end: 1000.310, text: 'et est souvent portée par les syndicats des étudiants.' },
  { start: 1000.659, end: 1008.190, text: 'Des difficultés à boucler le budget, et doit faire appel à' },
  { start: 1008.191, end: 1011.936, text: 'besoin d\'aide financière, mais aussi alimentaire comme la banque' },
  { start: 1011.937, end: 1014.510, text: 'alimentaire que vous pouvez avoir dans vos établissements.' },
  { start: 1015.009, end: 1018.310, text: 'Cela représente 1 étudiant sur 3 aujourd\'hui' },
  { start: 1019.045, end: 1023.870, text: 'Et enfin le dernier, qui est un statut particulier, que le statut de Salarié,' },
  { start: 1023.989, end: 1027.670, text: 'c\'est à dire avec un vrai Contrat de Travail, pas quelqu\'un' },
  { start: 1027.671, end: 1029.985, text: 'fait des petits emplois de temps en temps, et à' },
  { start: 1029.986, end: 1033.810, text: 'des conditions pour établir que c\'est un Etudiant-Salarié.' },
  { start: 1033.909, end: 1040.230, text: 'On dit souvent que c\'est à peu près 10-15%, pour l\'apprentissage' },
  { start: 1040.231, end: 1043.770, text: 'c\'est un statut reconnu dans l\'enseignement (<font color="#FFFF00">FISA</font>).' },
  { start: 1044.750, end: 1050.290, text: 'Et il y a à peu près 10% d\'étudiants qui sont des salariés non plein temps' },
  { start: 1050.489, end: 1052.990, text: 'mais qui travaillent de façon régulière' },
  { start: 1052.991, end: 1055.970, text: 'plus de 60H par mois' },
  { start: 1056.590, end: 1062.150, text: 'et enfin, 10 % d\'étudiants qui travaillent d\'une façon ponctuelle.' },
  { start: 1062.324, end: 1063.790, text: 'Pendant les congés, pendant les weekends,' },
  { start: 1068.610, end: 1069.610, text: 'et les grandes vacances.' },
  { start: 1076.490, end: 1084.230, text: 'Il existe des dispositions pour aider ces étudiants et étudiantes qui ont' },
  { start: 1084.304, end: 1088.110, text: 'un <font color="#FFFF00">handicap</font>, même si celui-ci n\'est pas officiellement nommé handicap,' },
  { start: 1088.230, end: 1092.087, text: 'en tout cas, un obstacle pour leur apprentissage, donc j\'ai' },
  { start: 1092.088, end: 1095.190, text: 'repris ces 6 cas que je viens de présenter' },
  { start: 1096.299, end: 1100.750, text: 'Etudiant-Parent, étudiant <font color="#FFFF00">Handicap</font>, étudiants qui ont un problème de santé,' },
  { start: 1101.790, end: 1107.390, text: 'Etudiant-<font color="#FFFF00">Aidant</font>, l\'étudiant en précarité financière ou autre.' },
  { start: 1107.730, end: 1113.270, text: 'Et enfin, Etudiant-Salarié. Et j\'ai regardé ce qui existe' },
  { start: 1113.294, end: 1117.650, text: 'aujourd\'hui au niveau légal, mise à disposition de ces étudiants.' },
  { start: 1118.049, end: 1122.710, text: 'Avec 3 cas que je vais décrire en détail qui sont les cas "Prioritaires"' },
  { start: 1122.910, end: 1130.210, text: 'qui est un <font color="#FFFF00">Régime Spécial d\'Etudes</font>, (<font color="#FFFF00">RSE</font>), ou à défaut ...' },
  { start: 1130.211, end: 1134.330, text: 'des conditions aménagées pour l\'organisation du travail.' },
  { start: 1136.339, end: 1142.530, text: 'Ensuite, je vais regarder si les <font color="#FFFF00">Examens Aménagés</font> ont été pour' },
  { start: 1142.531, end: 1147.810, text: 'ces personnes, et enfin, est-ce qu\'il y a un <font color="#FFFF00">Contrat de Formation</font>' },
  { start: 1149.090, end: 1153.668, text: 'ou plan spécifique, pour aider ces étudiants' },
  { start: 1153.669, end: 1159.570, text: 'à passer à travers ces obstacles de formation.' },
  { start: 1160.419, end: 1165.270, text: 'J\'ai rajouté deux cases que je ne vais pas détailler, qui sont ce qui est...' },
  { start: 1165.271, end: 1170.290, text: 'Aides Financières et les Accès Prioritaires pour le logement, qui peuvent' },
  { start: 1170.589, end: 1173.990, text: 's\'appliquer pour ces étudiants.' },
  { start: 1174.299, end: 1178.510, text: 'Sachant par exemple, le repas du CROUS à 1€ est aujourd\'hui appliqué à tous.' },
  { start: 1179.949, end: 1183.990, text: 'Commençons par l\'Etudiant-Parent et son régime spécial.' },
  { start: 1184.449, end: 1190.570, text: 'Il y a effectivement des droits pour ces étudiants : avoir des horaires adaptés' },
  { start: 1190.571, end: 1196.270, text: 'en tout cas des choix prioritaires pour l\'organisation de son temps,' },
  { start: 1196.271, end: 1199.730, text: 'de façon à concilier, sa vie de famille et ses cours.' },
  { start: 1200.170, end: 1202.570, text: 'C\'est la loi de la "Petite Enfance" qui l\'emporte dans ce cas.' },
  { start: 1202.749, end: 1205.250, text: 'Il faut pouvoir s\'occuper de son enfant.' },
  { start: 1206.529, end: 1213.370, text: 'Si on regarde le parent, il a aussi l\'aménagement d\'Examen possible' },
  { start: 1213.419, end: 1218.990, text: 'avec des décalages d\'épreuves ou des rattrapages dédiés lorsque...' },
  { start: 1219.304, end: 1221.855, text: 'cela est nécessaire, mais en général,' },
  { start: 1221.856, end: 1224.810, text: 'ces étudiants sont bien organisés pour cela.' },
  { start: 1225.490, end: 1228.610, text: 'Par contre il n\'y a pas de reconnaissance de leur statut par un ...' },
  { start: 1228.611, end: 1231.930, text: 'Plan de Formation ou un <font color="#FFFF00">Contrat de Formation</font> spécifique.' },
  { start: 1234.429, end: 1238.330, text: 'Le cas de l\'étudiant <font color="#FFFF00">Handicapé</font>, la 2ème colonne, est beaucoup plus connu' },
  { start: 1239.170, end: 1245.710, text: 'Il a effectivement un (<font color="#FFFF00">RSE</font>) <font color="#FFFF00">Régime Spécial d\'Etudes</font> qui concerne un aménagement' },
  { start: 1245.884, end: 1251.890, text: 'précis de son emploi du temps, organisé par la commission ou par le <font color="#FFFF00">responsable handicap</font>.' },
  { start: 1253.070, end: 1258.450, text: 'Et il dispose aussi d\'une <font color="#FFFF00">dispense d\'assiduité</font> si cela est nécessaire.' },
  { start: 1260.890, end: 1266.010, text: 'Pour les examens ou les contrôles, il peut disposer, en fonction de sa' },
  { start: 1266.159, end: 1268.650, text: 'situation et des recommandations de la commission' },
  { start: 1269.979, end: 1273.990, text: 'd\'un <font color="#FFFF00">Tiers Temps</font>, d\'une <font color="#FFFF00">Aide Humaine</font>, de <font color="#FFFF00">sujets adaptés</font>. Attention un' },
  { start: 1273.991, end: 1277.949, text: '<font color="#FFFF00">sujet adapté</font>, étant pour l\'aider dans le cadre' },
  { start: 1277.950, end: 1280.770, text: 'de son <font color="#FFFF00">handicap</font>, cela n\'est pas de le rendre plus facile.' },
  { start: 1281.369, end: 1287.230, text: 'C\'est d\'éviter que l\'<font color="#FFFF00">Handicap</font> s\'oppose à la compréhension de l\'examen.' },
  { start: 1287.850, end: 1290.610, text: 'Et dans certains cas, il peut y avoir aussi un isoloir ...' },
  { start: 1291.429, end: 1293.010, text: '... ou une salle isolée.' },
  { start: 1293.224, end: 1297.790, text: 'Tout cela est régi par un <font color="#FFFF00">Contrat de Formation</font> qui est un <font color="#FFFF00">Contrat Personnalisé</font>' },
  { start: 1298.089, end: 1304.710, text: 'qui a été élaboré par la Commission ou par le service ou par le référent' },
  { start: 1304.711, end: 1306.950, text: '<font color="#FFFF00">Handicap</font> et qui s\'impose à l\'établissement.' },
  { start: 1309.539, end: 1313.333, text: 'Pour le 3ème cas, 3ème colonne dans le cadre d\'une étudiante' },
  { start: 1313.334, end: 1317.090, text: 'ou d\'un étudiant avec un problème de santé.' },
  { start: 1318.529, end: 1320.543, text: 'il dispose aussi d\'un (<font color="#FFFF00">RSE</font>) <font color="#FFFF00">Régime Spécial d\'Etudes</font> au moment où il a des problèmes' },
  { start: 1320.544, end: 1323.970, text: 'de santé avec des dispenses ...' },
  { start: 1323.970, end: 1330.630, text: 'ponctuelles (pour l\'handicapé c\'était tout le temps)' },
  { start: 1330.631, end: 1332.530, text: 'd\'assiduité ...' },
  { start: 1332.990, end: 1339.130, text: 'si c\'est justifié : il faut avoir un rendez-vous,' },
  { start: 1339.131, end: 1342.650, text: 'des soins médicaux, cela ne peut pas être une façon générale.' },
  { start: 1342.749, end: 1345.810, text: 'Ici, ça doit être justifié.' },
  { start: 1346.119, end: 1349.790, text: 'Pour ce qui concerne les examens, on a à peu près de la même chose que l\'handicap' },
  { start: 1349.850, end: 1354.110, text: 'avec des <font color="#FFFF00">Temps Supplémentaires</font>, des <font color="#FFFF00">Tiers Temps</font> comme dans le cas' },
  { start: 1354.111, end: 1356.725, text: 'l\'étudiante <font color="#FFFF00">Handicapée</font> avec une décision du' },
  { start: 1356.726, end: 1359.270, text: 'référent ou en tout cas d\'un responsable Pédagogique.' },
  { start: 1361.339, end: 1364.590, text: 'Pour le <font color="#FFFF00">Contrat de Formation</font> c\'est local, c\'est avec l\'université.' },
  { start: 1365.190, end: 1371.450, text: 'Il n\'y a pas d\'exigence particulière, c\'est un Protocole d\'accord Santé.' },
  { start: 1371.724, end: 1373.870, text: 'entre l\'Etudiante et l\'Université.' },
  { start: 1376.050, end: 1382.230, text: 'Dans le cadre de l\'<font color="#FFFF00">Aidant</font>, la 4ème colonne, ils peuvent s\'exposer dans un groupe' },
  { start: 1382.231, end: 1384.570, text: 'ou choisir un groupe spécial de cours ...' },
  { start: 1384.571, end: 1387.630, text: 'de façon à aménager leur Emploi du Temps.' },
  { start: 1388.050, end: 1393.770, text: 'c\'est pour aider et pour avoir le temps de jouer leur rôle d\'<font color="#FFFF00">Aidant</font>.' },
  { start: 1394.350, end: 1396.999, text: 'Il peut aussi y avoir une Autorisation' },
  { start: 1397.000, end: 1399.790, text: 'Spéciale d\'Absence ou dans le cas d\'examen.' },
  { start: 1400.439, end: 1405.770, text: 'Il faut vraiment avoir une bonne réponse, une justification pour disposer' },
  { start: 1405.919, end: 1407.910, text: 'd\'Autorisation d\'Absence.' },
  { start: 1408.904, end: 1413.610, text: 'Bien entendu, s\'ils ont une Autorisation, ils ont un rattrapage personnalisé.' },
  { start: 1415.050, end: 1420.190, text: 'Il n\'y a pas à ce jour de <font color="#FFFF00">Contrat de Formation</font> pour les étudiants <font color="#FFFF00">Aidants</font>' },
  { start: 1420.191, end: 1423.990, text: 'qui représentent, comme je l\'ai dit, 12 à 15% de la population aujourd\'hui.' },
  { start: 1426.629, end: 1432.130, text: 'Aucune disposition n\'a été prévue pour la colonne #5, qui est le cas de la' },
  { start: 1432.131, end: 1436.490, text: '<font color="#FFFF00">Précarité</font>, que ce soit une Précarité Financière, Numérique, etc.' },
  { start: 1445.119, end: 1451.150, text: 'Le dernier, c\'est l\'Etudiant-Salarié, j\'entends par Etudiant-Salarié ...' },
  { start: 1451.274, end: 1454.210, text: 'un étudiant qui a un <font color="#FFFF00">Contrat de Travail</font> avec une entreprise.' },
  { start: 1454.869, end: 1461.030, text: 'Cela peut être un CDD, un CDI, ou tout autre Contrat de Projet.' },
  { start: 1461.031, end: 1465.590, text: 'Donc, dans l\'enseignement, on parle parfois de CDD, CD2I, etc.' },
  { start: 1467.374, end: 1470.815, text: 'Cela ne concerne pas des Contrats qui sont assez volumineux' },
  { start: 1470.816, end: 1473.230, text: 'cela n\'est pas un petit travail d\'une heure par semaine.' },
  { start: 1473.710, end: 1479.110, text: 'On parle ici d\'ajustement lorsque le volume de travail du <font color="#FFFF00">Contrat de Travail</font>' },
  { start: 1479.559, end: 1485.770, text: 'et de l\'ordre de 60 heures par mois ou 120 H par trimestre' },
  { start: 1486.044, end: 1488.833, text: 'Donc, c\'est la situation la plus favorable (60H/m ou 120H/T)' },
  { start: 1488.834, end: 1490.970, text: 'pour l\'étudiant qui est à prendre en considération.' },
  { start: 1491.515, end: 1496.550, text: 'Et dans ce cas-là, si l\'étudiant a un Contrat de Travail de 60 H/mois,' },
  { start: 1496.950, end: 1498.190, text: 'ou de 120 H/Trimestre' },
  { start: 1499.204, end: 1502.731, text: 'L\'Emploi du Temps doit être ajusté, de façon obligatoire' },
  { start: 1502.781, end: 1504.890, text: 'le Travail l\'emporte sur l\'Enseignement' },
  { start: 1507.559, end: 1512.350, text: 'Si cela concerne les examens ou les contrôles des connaissances,' },
  { start: 1512.899, end: 1516.390, text: 'il peut y avoir des dispenses dans certains contrôles continus' },
  { start: 1517.590, end: 1521.170, text: 'Et puis, bien entendu, des épreuves aménagées, par exemple en distanciel,' },
  { start: 1521.329, end: 1522.730, text: 'si cela est nécessaire.' },
  { start: 1525.280, end: 1530.210, text: 'Pour ce qui concerne le statut d\'Etudiant-Salarié, il existe un contrat' },
  { start: 1530.434, end: 1534.210, text: 'spécifique, <font color="#FFFF00">FISA</font> (Formation Initiale sous Statut Apprenti), c\'est le <font color="#FFFF00">Contrat d\'Apprentissage</font>' },
  { start: 1534.419, end: 1536.350, text: 'Les autres ne sont pas concernés ...' },
  { start: 1536.590, end: 1542.910, text: 'c\'est à dire les CDD, les CDI ne sont pas concernés dans un Plan' },
  { start: 1542.911, end: 1547.110, text: 'ou par un <font color="#FFFF00">Contrat de Formation</font> Spécifique, cela ne concerne que l\'Apprentissage,' },
  { start: 1547.369, end: 1549.290, text: 'en France et personne d\'autre.' },
  { start: 1551.740, end: 1557.880, text: 'Aides Financières ... Accès Prioritaires ..., je vous laisse lire ce qui existe.' },
  { start: 1557.880, end: 1563.822, text: 'Il existe beaucoup de dispositions qu\'il faut connaître et pour' },
  { start: 1563.823, end: 1567.060, text: 'aider les étudiants lorsqu\'ils en ont besoin.' },
  { start: 1572.109, end: 1578.650, text: 'On va s\'intéresser au cas de l\'étudiant <font color="#FFFF00">Handicapé</font> parce que derrière l\'handicap' },
  { start: 1578.885, end: 1582.050, text: 'en tout cas l\'aménagement, il y a un protocole strict.' },
  { start: 1582.294, end: 1586.790, text: 'Il faut appliquer, en tout cas, pour éviter les contentieux juridiques qui arrivent de' },
  { start: 1586.791, end: 1589.750, text: 'plus en plus et en particulier dans les Ecoles Privées.' },
  { start: 1589.870, end: 1590.962, text: 'Dans les écoles publiques ont un peu moins ...' },
  { start: 1590.963, end: 1593.590, text: 'mais dans les écoles privées, on les voit apparaitre' },
  { start: 1594.729, end: 1600.170, text: 'Cette organisation est décrite dans les Lois et les Codes de l\'Education,' },
  { start: 1600.550, end: 1603.771, text: 'elle prévoit une chaîne de décisions qui' },
  { start: 1603.772, end: 1606.890, text: 'part de l\'étudiant qui doit se déclarer.' },
  { start: 1607.274, end: 1611.870, text: ', on ne peut rien faire sans la déclaration de l\'étudiant, et la mise en application,' },
  { start: 1612.230, end: 1613.230, text: 'par l\'enseignant.' },
  { start: 1614.150, end: 1618.050, text: 'Il n\'y a pas d\'application directe, c\'est strictement refusé.' },
  { start: 1618.104, end: 1620.135, text: 'Un étudiant qui va voir un enseignant, et qui dit' },
  { start: 1620.215, end: 1621.950, text: '"bah voilà, j\'ai tel problème ...' },
  { start: 1622.299, end: 1626.350, text: 'merci d\'adapter mon contrôle !" ...C\'est souvent au moment des contrôles que cela se fait' },
  { start: 1628.169, end: 1634.250, text: 'Cela n\'est pas possible. L\'enseignant n\'est pas en mesure' },
  { start: 1634.251, end: 1637.986, text: 'de juger, ce n\'est pas un médecin, il n\'est pas formé' },
  { start: 1637.987, end: 1640.370, text: 'précisément pour connaître un <font color="#FFFF00">handicap</font>.' },
  { start: 1640.774, end: 1642.510, text: 'Il n\'a pas à le faire.' },
  { start: 1643.249, end: 1646.430, text: 'Et s\'il le fait, il peut y avoir un contentieux avec un autre étudiant,' },
  { start: 1647.414, end: 1651.250, text: 'parce qu\'il peut dire, <i>"Lui, il a été favorisé et pas moi, parce que</i>' },
  { start: 1651.251, end: 1653.965, text: '<i>il a dit, telle chose, et moi, je suis défavorisé</i>' },
  { start: 1653.966, end: 1656.170, text: '<i>parce que je n\'ai pas eu un <font color="#FFFF00">Tiers Temps</font>"</i>, etc.' },
  { start: 1656.909, end: 1662.150, text: 'Il faut vraiment être sérieux et refuser ce genre de démarche en tout cas !' },
  { start: 1662.151, end: 1668.450, text: 'l\'enseignant n\'a pas à adapter son cours à la demande de l\'étudiant.' },
  { start: 1669.230, end: 1675.950, text: 'L\'étudiant doit signaler la situation à un Service, à un Département ou un Référent' },
  { start: 1676.099, end: 1680.670, text: '<font color="#FFFF00">Handicap</font> (qui est obligatoire dans les écoles), qui va étudier la situation.' },
  { start: 1681.979, end: 1686.970, text: 'S\'il a besoin d\'aide, il peut solliciter le médecin désigné par la ...' },
  { start: 1686.971, end: 1693.650, text: '<font color="#FFFF00">Commission des Droits et de l\'Autonomie des Personnes Handicapées (CDAPH)</font>' },
  { start: 1694.349, end: 1697.730, text: 'qui se trouve au niveau de la maison départementale des personnes <font color="#FFFF00">Handicapées</font>' },
  { start: 1697.731, end: 1701.910, text: 'et qui va l\'aider à faire un diagnostic de la situation.' },
  { start: 1703.559, end: 1710.610, text: 'Une fois que le lien entre l\'étudiant et le référent a été fait et' },
  { start: 1710.859, end: 1716.010, text: 'qu\'il effectivement constate un <font color="#FFFF00">handicap</font>, et non pas un' },
  { start: 1716.011, end: 1721.570, text: 'défaut linguistique, ou un problème de maîtrise de la langue française,' },
  { start: 1722.390, end: 1728.510, text: 'il va commencer à faire un bilan qui évalue tous les besoins selon' },
  { start: 1728.511, end: 1733.190, text: 'la loi, qui sont l\'Organisation, le Déroulement des cours' },
  { start: 1733.264, end: 1736.459, text: 'et l\'Accompagnement. Il n\'y a pas, a priori, au niveau de' },
  { start: 1736.460, end: 1740.210, text: 'la loi, un chapitre particulier sur le contrôle.' },
  { start: 1741.759, end: 1746.077, text: 'Sur ces 3 chapitres Organisation-Déroulement-' },
  { start: 1746.078, end: 1748.770, text: 'Accompagnement, pas besoin d\'un avis médical.' },
  { start: 1749.350, end: 1754.970, text: 'Ici, c\'est le responsable Pédagogique, ou le référent <font color="#FFFF00">Handicap</font> qui sont les' },
  { start: 1754.971, end: 1759.210, text: 'Maître d\'œuvre de ce plan d\'Accompagnement.' },
  { start: 1760.259, end: 1763.510, text: 'Par contre, dans certains cas, et s\'il n\'a jamais fait.' },
  { start: 1763.970, end: 1767.274, text: 'Il faut savoir que l\'<font color="#FFFF00">aménagement des examens</font>' },
  { start: 1767.275, end: 1770.670, text: 'peut demander un avis <u>obligatoire d\'un médecin.</u>' },
  { start: 1778.111, end: 1782.210, text: 'par exemple, ou dans d\'autres problèmes <font color="#FFFF00">handicap invisible</font>, c\'est connu,' },
  { start: 1783.330, end: 1787.830, text: 'Mais c\'est un médecin qui va le déclarer, qui va le demander.' },
  { start: 1787.831, end: 1789.870, text: 'En tout cas, il faut un avis médical.' },
  { start: 1790.184, end: 1792.830, text: 'Il ne peut pas être donné sans cette façon.' },
  { start: 1794.250, end: 1799.270, text: 'Une fois que l\'évaluation des besoins a été réalisée, il s\'applique à l\'établissement' },
  { start: 1799.271, end: 1803.750, text: 'et il revient à l\'établissement, (qui a l\'autorité hiérarchique)' },
  { start: 1803.751, end: 1808.710, text: 'de faire appliquer à tous et, en particulier aux enseignants, qui vont' },
  { start: 1808.711, end: 1815.110, text: 'avoir la personne, l\'étudiant ou l\'étudiante, dans leur cours, pendant la' },
  { start: 1815.334, end: 1818.790, text: 'formation, ou pendant le contrôle des connaissances.' },
  { start: 1824.939, end: 1828.260, text: 'J\'ai dit que l\'enseignant n\'est pas en mesure d\'évaluer ...' },
  { start: 1828.300, end: 1834.160, text: '... le besoin et, en tout cas, avoir un avis médical sur la personne.' },
  { start: 1835.280, end: 1837.460, text: 'C\'est vrai mais cela n\'empêche pas la formation.' },
  { start: 1837.634, end: 1839.818, text: 'Non seulement cela ne l\'empêche pas, mais je' },
  { start: 1839.819, end: 1843.400, text: 'précise que cette formation est <u>Obligatoire.</u>' },
  { start: 1843.699, end: 1848.340, text: 'Cela veut dire qu\'elle rentre dans le champ des <u>Formations Obligatoires</u> que doit' },
  { start: 1848.341, end: 1853.400, text: 'donner un employeur à l\'employé comme par exemple les Formations Sécurités.' },
  { start: 1855.064, end: 1859.700, text: 'Donc cette formation est obligatoire, elle a été introduite dès le départ dans ...' },
  { start: 1859.701, end: 1863.140, text: '... la loi de 2005 et elle était ensuite confirmée dans les' },
  { start: 1863.141, end: 1867.300, text: 'différentes lois et la dernière du 15 novembre 2014.' },
  { start: 1867.849, end: 1871.280, text: 'Qu\'on appelle la loi de l\'"Ecole de la Confiance" qui est un peu plus large,' },
  { start: 1871.614, end: 1873.300, text: 'qui est beaucoup plus <font color="#FFFF00">inclusive</font>.' },
  { start: 1874.135, end: 1878.180, text: 'Elle dit que les enseignants, mais aussi tous les personnels d\'encadrement ...' },
  { start: 1878.354, end: 1883.260, text: 'technique, service, etc et d\'accueil doivent avoir, au cours de leur formation,' },
  { start: 1883.260, end: 1888.500, text: 'si c\'est une formation initiale, par exemple les enseignants, mais aussi au' },
  { start: 1888.501, end: 1891.240, text: 'cours de l\'exécution de leur travail' },
  { start: 1891.475, end: 1892.475, text: 'de la <font color="#FFFF00">Formation Continue</font>' },
  { start: 1892.774, end: 1896.660, text: 'une formation spécifique qui concerne l\'accueil/éducation des élèves et des' },
  { start: 1896.661, end: 1901.200, text: 'étudiants, en situation de <font color="#FFFF00">handicap</font> et je ne sais pas pourquoi cette phrase ...' },
  { start: 1901.420, end: 1902.420, text: 'mais elle est là.' },
  { start: 1902.780, end: 1906.560, text: '"<i>En particulier, ou notamment ceux qui présentent un trouble</i>' },
  { start: 1906.561, end: 1910.240, text: 'du comportement ou <i>du <font color="#FFFF00">trouble du neuro-développement</font>.</i>' },
  { start: 1911.669, end: 1914.980, text: 'Petite phrase au passage, dans le cas de l\'Apprentissage,' },
  { start: 1915.894, end: 1920.100, text: 'et je pense aux BTS qui sont souvent au laboratoire ou dans la pratique,' },
  { start: 1921.180, end: 1924.400, text: 'l\'<font color="#FFFF00">inclusion</font> ne concerne pas uniquement l\'<font color="#FFFF00">accessibilité</font> des salles ...' },
  { start: 1924.974, end: 1927.580, text: '... de cours, mais elle concerne l\'ensemble du laboratoire,' },
  { start: 1927.620, end: 1929.540, text: 'le rythme de l\'alternance, l\'entreprise.' },
  { start: 1930.980, end: 1938.400, text: 'Et il faut être précis, en particulier sur les pratiques de sécurité et de santé.' },
  { start: 1944.344, end: 1947.840, text: 'En conséquence, et pour clore ce chapitre sur le' },
  { start: 1947.841, end: 1952.000, text: 'constat, je vous présente une liste non exhaustive.' },
  { start: 1952.460, end: 1957.860, text: 'de formation qu\'on peut appliquer.' },
  { start: 1958.160, end: 1963.440, text: 'donc des formations obligatoires, qu\'on peut appliquer pour l\'ensemble du' },
  { start: 1963.441, end: 1967.300, text: 'personnel, encadrement, accueil, et puis d\'accompagnement.' },
  { start: 1968.674, end: 1973.318, text: 'Le premier est très connu, c\'est la Formation "<font color="#FFFF00">Cap Ecole Inclusive</font>"' },
  { start: 1973.319, end: 1976.460, text: 'qui a été développée depuis plusieurs années.' },
  { start: 1976.554, end: 1981.400, text: 'non seulement il y a de la formation mais aussi, des ressources pédagogiques' },
  { start: 1981.401, end: 1984.516, text: 'c\'est toute une plateforme qui a été développée' },
  { start: 1984.517, end: 1987.340, text: 'autour des éléments de "Confiance".' },
  { start: 1988.990, end: 1993.760, text: 'Donc, c\'est plus que l\'<font color="#FFFF00">Handicap</font> mais c\'est l\'<font color="#FFFF00">Inclusivité</font>' },
  { start: 1994.320, end: 1995.700, text: 'de façon générale.' },
  { start: 1997.859, end: 2002.260, text: 'Pour les "Paralysés de France", c\'est une association.' },
  { start: 2003.259, end: 2008.380, text: 'Il y a aussi une formation qui concerne la question d\'<font color="#FFFF00">accessibilité</font>, l\'<font color="#FFFF00">inclusion</font>,' },
  { start: 2008.585, end: 2013.580, text: 'c\'est surtout des <font color="#FFFF00">handicapés moteurs</font> qui sont concernés par cette association.' },
  { start: 2014.154, end: 2016.440, text: 'Ils interviennent sur place, ils peuvent intervenir.' },
  { start: 2016.519, end: 2021.480, text: 'dans votre établissement et auprès de l\'administration générale.' },
  { start: 2023.769, end: 2030.140, text: 'Le 3ème est un MOOC, tout à fait original, réalisé par l\'AFPA' },
  { start: 2030.141, end: 2034.100, text: 'qui s\'appelle "<font color="#FFFF00">Handicap</font>, des clés d\'actions vers l\'emploi"' },
  { start: 2034.734, end: 2039.740, text: 'Il est, d\'une façon générale, bien structuré, le sujet de l\'<font color="#FFFF00">handicap</font>' },
  { start: 2040.699, end: 2044.100, text: 'pour l\'<font color="#FFFF00">inclusion</font>, dans la formation et dans l\'emploi.' },
  { start: 2044.101, end: 2050.060, text: 'Donc, très large, c\'est une formation à distance reconnue et qu\'il y a eu' },
  { start: 2050.385, end: 2055.300, text: 'la récompense de l\'"Open Educaton Night 2023"' },
  { start: 2055.380, end: 2056.388, text: 'Il n\'y a pas d\'orthographe' },
  { start: 2056.389, end: 2060.239, text: 'C\'est bien EduCaton qu\'il faut lire ici' },
  { start: 2060.739, end: 2064.300, text: 'A défaut, si vous ne savez pas laquelle choisir, vous pouvez faire celle-ci' },
  { start: 2064.301, end: 2068.159, text: 'et notifier que les personnes ont suivi ce MOOC.' },
  { start: 2071.110, end: 2077.159, text: 'Le 4ème, ce sont les plateformes ou toutes les formations proposées par l\'Union' },
  { start: 2077.360, end: 2082.159, text: 'Nationale de Familles et des Amis de <font color="#FFFF00">Personnes Malades et/ou Handicapées Psychiques</font>' },
  { start: 2083.280, end: 2089.290, text: 'Cela n\'est pas orienté pour les handicapés, c\'est pour les professionnels.' },
  { start: 2092.290, end: 2096.590, text: 'Si on fait un focus sur les <font color="#FFFF00">DYS</font>, il y a la Fédération Française des <font color="#FFFF00">DYS</font>,' },
  { start: 2096.770, end: 2100.920, text: 'qui a des formations, dans les 6 domaines' },
  { start: 2100.921, end: 2104.370, text: 'des <font color="#FFFF00">troubles cognitifs</font> des <font color="#FFFF00">DYS</font> pour l\'enseignement' },
  { start: 2104.495, end: 2110.090, text: 'supérieur et pour le domaine professionnel, très bien.' },
  { start: 2110.370, end: 2113.170, text: 'Un peu cher à mon goût, mais de grande qualité.' },
  { start: 2114.230, end: 2120.410, text: 'Enfin n\'oublions pas qu\'on peut se former à d\'autres problématiques, à d\'autres' },
  { start: 2120.411, end: 2124.610, text: 'langues, et en particulier à la <font color="#FFFF00">langue des signes française</font>.' },
  { start: 2125.740, end: 2128.930, text: 'il y a des associations et une plateforme de formation en ligne' },
  { start: 2129.750, end: 2137.250, text: 'qui s\'appelle "Signes de Sens", qui permet l\'apprentissage du langage des' },
  { start: 2137.251, end: 2139.909, text: 'signes, pardon, pour l\'<font color="#FFFF00">inclusion</font> des malentendants en tout cas des personnes qui ont des problèmes d\'écoute.' },

  { start: 2139.910, end: 2144.000, text: 'Merci pour votre attention. Allez au chapitre 2.' },

];

const SUBTITLES_EN_CH1 = [
{ start: 1.000, end: 12.120, text: 'Welcome to the BRIDGE programme -<font color="#FFFF00"> Bridging Research and Inclusive Digital Education</font>' },
  { start: 12.130, end: 19.630, text: 'We are now going to address today\'s conference, which concerns the topic' },
  { start: 19.631, end: 23.830, text: 'of the integration of people with a <font color="#FFFF00">disability</font>' },
  { start: 24.220, end: 27.170, text: 'or in any case, having blockages during teaching.' },
  { start: 27.350, end: 31.570, text: 'There will be a strong "<font color="#FFFF00">Disability</font>" connotation in this presentation.' },
  { start: 32.155, end: 36.750, text: 'But this is essentially about "<font color="#FFFF00">Inclusive Teaching</font>"' },
  { start: 37.295, end: 40.530, text: 'We\'re going to start with a first chapter on observations,' },
  { start: 40.531, end: 45.630, text: 'the volume, who are the people concerned by this conference?' },
  { start: 63.885, end: 66.527, text: 'This is a look at the volume concerning' },
  { start: 66.577, end: 69.160, text: '<font color="#FFFF00">disabled</font> students.' },
  { start: 70.019, end: 73.571, text: 'In fact, to simplify, this represents' },
  { start: 73.572, end: 77.020, text: '3% of the student population in France.' },
  { start: 77.720, end: 84.740, text: 'So it\'s around, today, we\'re around 60,000 students.' },
  { start: 85.139, end: 89.080, text: 'These figures are misleading and, in particular, they are not representative' },
  { start: 89.081, end: 92.180, text: 'of the full range of <font color="#FFFF00">disabilities</font> one may encounter.' },
  { start: 92.720, end: 97.540, text: 'In any case, representative of the population we have in class.' },
  { start: 98.740, end: 106.540, text: 'Of this 3%, 70% are <font color="#FFFF00">invisible disabilities</font>,' },
  { start: 106.949, end: 110.640, text: 'in any case, they are very hard to detect at first glance,' },
  { start: 111.039, end: 116.040, text: 'because they can involve <font color="#FFFF00">psychological disorders</font>, disabling' },
  { start: 116.040, end: 121.700, text: 'illnesses, <font color="#FFFF00">cognitive disorders</font>, <font color="#FFFF00">learning disabilities (DYS)</font> being the best known,' },
  { start: 122.680, end: 127.960, text: 'or forms of <font color="#FFFF00">autism</font>, which are entirely able to follow teaching.' },
  { start: 128.900, end: 131.940, text: 'So, basic <font color="#FFFF00">autism</font>. Here, it\'s around 5%.' },
  { start: 134.810, end: 137.864, text: '<font color="#FFFF00">Invisible disabilities</font> also involve' },
  { start: 137.865, end: 141.800, text: '<font color="#FFFF00">speech disorders</font>, which are around 22%.' },
  { start: 141.801, end: 149.680, text: '<font color="#FFFF00">Cognitive disorders</font> (right and bottom) are around 6%.' },
  { start: 150.255, end: 156.020, text: 'On the other hand, 1 in 3 <font color="#FFFF00">disabled</font> students has' },
  { start: 156.021, end: 160.700, text: '<font color="#FFFF00">visible</font> disabilities, which are <font color="#FFFF00">motor disorders</font>, <font color="#FFFF00">visual disorders</font> (vision problems...' },
  { start: 160.701, end: 165.740, text: 'up to total blindness), and <font color="#FFFF00">hearing problems</font>, up to total deafness.' },
  { start: 165.984, end: 170.780, text: 'Here, most visible disabilities involve' },
  { start: 170.781, end: 174.680, text: '<font color="#FFFF00">motor disorders</font> (around 10%).' },
  { start: 176.280, end: 179.141, text: 'As you can see,' },
  { start: 179.142, end: 181.660, text: '2/3 are not visible, 1/3 are visible.' },
  { start: 182.380, end: 188.420, text: 'If we look at the distribution of these struggling students,' },
  { start: 188.421, end: 195.300, text: 'in higher education, we see they are mostly concentrated in' },
  { start: 195.301, end: 199.527, text: 'universities, which "capture" or welcome, in any case,' },
  { start: 199.528, end: 203.880, text: 'at least 8 out of 10 <font color="#FFFF00">disabled</font> students.' },
  { start: 204.560, end: 209.620, text: 'Next, we see that the second level is private institutions' },
  { start: 209.621, end: 214.140, text: 'of general interest, commonly called "EESPIG", the' },
  { start: 214.141, end: 219.040, text: 'Private Higher Education Institution of General Interest, which,' },
  { start: 219.041, end: 223.340, text: 'today, these figures are higher, around 8 to 10%.' },
  { start: 223.440, end: 229.260, text: 'The figures I\'m showing you here, on the right, on the left, and,' },
  { start: 229.435, end: 232.420, text: 'in fact, are old, from 2024' },
  { start: 234.000, end: 240.120, text: 'Regarding prep classes and national-education high schools,' },
  { start: 240.554, end: 244.680, text: 'we\'re around 4 to 5% of <font color="#FFFF00">disabled</font> students.' },
  { start: 245.040, end: 247.803, text: 'And then, in the other public schools,' },
  { start: 247.804, end: 251.640, text: 'outside university, we\'re around 3 to 4%.' },
  { start: 252.340, end: 258.279, text: 'So, to simplify, we see that a small part of <font color="#FFFF00">disability</font>' },
  { start: 258.380, end: 263.300, text: 'and in any case, we only see 1% of <font color="#FFFF00">disabled</font> people.' },
  { start: 264.085, end: 268.840, text: 'What\'s remarkable, (what I noted in the middle of the box on the right)' },
  { start: 268.841, end: 272.520, text: 'is that if you look at the science fields,' },
  { start: 273.120, end: 277.280, text: 'well, there\'s only 29%, roughly a third, of' },
  { start: 277.281, end: 279.480, text: '<font color="#FFFF00">disabled</font> people who go into scientific fields.' },
  { start: 280.740, end: 286.500, text: 'So it\'s entirely legitimate for a teacher, a professor,' },
  { start: 287.125, end: 288.125, text: 'to tell you' },
  { start: 288.185, end: 290.860, text: '"Sorry, but I don\'t have any <font color="#FFFF00">disabled</font> students in my class".' },
  { start: 291.600, end: 294.840, text: 'Either there really aren\'t any because the population is quite small ..' },
  { start: 295.480, end: 301.140, text: 'or there are, but it won\'t be visible if you aren\'t told!' },
  { start: 305.460, end: 309.440, text: 'So, these figures conflict with the impression one may have' },
  { start: 309.441, end: 313.400, text: 'when looking at the population of students' },
  { start: 313.540, end: 314.620, text: 'we have in our classrooms.' },
  { start: 315.420, end: 321.000, text: 'And in particular on the question of <font color="#FFFF00">learning disabilities (DYS)</font>, which are ...' },
  { start: 321.195, end: 325.140, text: 'the issues, the <font color="#FFFF00">disabilities</font>, linked to a lasting <font color="#FFFF00">cognitive disorder</font>.' },
  { start: 326.000, end: 333.040, text: 'I\'ll remind you, <font color="#FFFF00">DYS</font> is "medical", and has no relation to the' },
  { start: 333.041, end: 336.132, text: 'parents\' social or professional category, or the student\'s,' },
  { start: 336.133, end: 338.860, text: 'so it is completely independent of social background (SES).' },
  { start: 339.645, end: 341.777, text: 'and also of linguistic origin, <font color="#FFFF00">DYS</font> occurs ...' },
  { start: 341.778, end: 344.660, text: 'in every population around the globe.' },
  { start: 346.025, end: 350.800, text: 'For the population, I was showing figures around 7%,' },
  { start: 351.410, end: 352.864, text: 'that\'s roughly what we have.' },
  { start: 352.865, end: 357.820, text: 'And if we look at the most severe forms of <font color="#FFFF00">DYS</font>, it\'s around 3 to 5%.' },
  { start: 359.360, end: 363.140, text: '<font color="#FFFF00">DYS</font> is recognized in a very clear way' },
  { start: 363.640, end: 369.680, text: 'It\'s the difference - it\'s the gap - that can be seen between the behaviour' },
  { start: 369.855, end: 375.520, text: 'in speech and in relationships of a student who fully understands the oral lesson,' },
  { start: 375.870, end: 380.880, text: 'who has a rich vocabulary, who has an excellent grasp of the concepts,' },
  { start: 381.305, end: 385.480, text: 'even when they\'re complex, may have a few situations,' },
  { start: 386.140, end: 387.399, text: 'a few reversals now and then.' },
  { start: 387.400, end: 389.360, text: 'but that remains minor.' },
  { start: 389.575, end: 392.931, text: 'However, when it comes to writing and in particular' },
  { start: 392.932, end: 396.420, text: 'when they have to understand a statement or write it...' },
  { start: 396.920, end: 403.220, text: 'Well, the <font color="#FFFF00">disability</font> shows up with spelling mistakes' },
  { start: 403.221, end: 407.320, text: 'but that\'s an induced effect, a side effect of <font color="#FFFF00">dyslexia</font>' },
  { start: 407.445, end: 410.320, text: 'but there are also blends, slowness, word reversals.' },
  { start: 411.830, end: 415.740, text: 'And that makes sources difficult for them, in any case there\'s real' },
  { start: 415.741, end: 418.940, text: 'cognitive fatigue linked to this difficulty with writing.' },
  { start: 419.460, end: 425.080, text: 'So, that\'s the gap, between what you see of the person and their written output,' },
  { start: 425.360, end: 430.760, text: 'which is a characteristic of <font color="#FFFF00">DYS</font>. This characteristic has a solution,' },
  { start: 431.585, end: 434.820, text: 'a "medical" one, even if that term isn\'t quite right.' },
  { start: 435.455, end: 438.045, text: 'The first thing, and it\'s true that it was effective,' },
  { start: 438.046, end: 440.300, text: 'is to avoid anything causing fatigue' },
  { start: 440.450, end: 444.040, text: '"<font color="#FFFF00">Cognitive Fatigue</font>", in plain terms, means giving more time.' },
  { start: 444.820, end: 447.799, text: 'And then certain speech-therapy assessments in particular' },
  { start: 447.800, end: 450.800, text: 'are quite effective at correcting this kind of thing.' },
  { start: 452.260, end: 455.290, text: 'And then, we have a population of students' },
  { start: 455.291, end: 458.200, text: 'who would seem to have the same problem, particularly in writing' },
  { start: 459.870, end: 463.000, text: 'But when you look closely, speech is also an issue.' },
  { start: 463.785, end: 466.720, text: 'It\'s actually a language-acquisition deficit.' },
  { start: 467.020, end: 469.896, text: 'And compared to the <font color="#FFFF00">DYS</font> cases we saw' },
  { start: 469.897, end: 472.320, text: 'here on the table and in the left-hand column.' },
  { start: 473.020, end: 475.720, text: 'Here, these are lasting solutions.' },
  { start: 476.450, end: 481.320, text: 'That is, the problem will disappear over time, through' },
  { start: 481.545, end: 487.100, text: 'practice, regular exposure to the language, to the culture,' },
  { start: 487.101, end: 490.840, text: 'but also extremely diverse in form.' },
  { start: 491.825, end: 494.405, text: 'And we can mention, for example, <font color="#FFFF00">FLE</font> (French as a foreign language) courses that' },
  { start: 494.406, end: 498.140, text: 'exist in all institutions today, which help a lot' },
  { start: 498.141, end: 502.040, text: 'It\'s logistical support that needs to be put in place, and it allows for' },
  { start: 502.041, end: 505.920, text: 'fast and lasting progress, and it isn\'t "medical" at all.' },
  { start: 506.840, end: 511.860, text: 'On the other hand, it\'s true that the population concerned is significant,' },
  { start: 511.861, end: 516.500, text: 'and today, it\'s estimated that forms of "<font color="#FFFF00">illiteracy</font>", i.e. an inability to' },
  { start: 516.501, end: 522.919, text: 'write or understand a text, affects around 7% of the 8-65 population' },
  { start: 522.920, end: 527.340, text: 'those are the national figures, and if you look at students,' },
  { start: 527.520, end: 532.140, text: 'so one indicator is first-year entrants after the Baccalaureate,' },
  { start: 532.989, end: 535.720, text: 'you get a population of 10 to 15%.' },
  { start: 536.419, end: 540.820, text: 'Here we have a real difficulty, since these students have' },
  { start: 540.845, end: 545.560, text: 'a limited spoken and written vocabulary, and also' },
  { start: 547.504, end: 554.380, text: 'comprehension difficulties, but this isn\'t <font color="#FFFF00">DYS</font>. <font color="#FFFF00">DYS</font> comes with "legal" support,' },
  { start: 554.500, end: 561.060, text: 'to help, in any case to remove the barrier of <font color="#FFFF00">disability</font>,' },
  { start: 561.209, end: 564.980, text: 'whereas in the other case there is no legal provision.' },
  { start: 572.809, end: 576.940, text: 'We can extend this reasoning that we just applied to' },
  { start: 577.039, end: 581.200, text: '<font color="#FFFF00">DYS</font> and people who have difficulties acquiring the French language,' },
  { start: 581.729, end: 587.820, text: 'to other types of <font color="#FFFF00">disabilities</font>, or in any case, if it isn\'t' },
  { start: 587.821, end: 591.840, text: 'a <font color="#FFFF00">disability</font>, these are clearly obstacles to learning.' },
  { start: 594.099, end: 597.380, text: 'I represent it as an onion shape, with successive layers.' },
  { start: 598.380, end: 601.820, text: 'The core, which we haven\'t discussed, is <font color="#FFFF00">disabilities</font> that will be known,' },
  { start: 601.900, end: 607.120, text: 'with 1/3 visible, 2/3 not visible,' },
  { start: 607.260, end: 608.139, text: 'but declared.' },
  { start: 608.140, end: 612.380, text: 'And the figure I mentioned earlier, around 60, 70 thousand,' },
  { start: 612.554, end: 615.920, text: '64,000 here, is quite clear.' },
  { start: 616.380, end: 621.060, text: 'But behind that, there are still <font color="#FFFF00">invisible disabilities</font> that aren\'t declared.' },
  { start: 622.339, end: 627.380, text: 'So, we find <font color="#FFFF00">Autism</font>, lifelong chronic illnesses,' },
  { start: 627.555, end: 630.580, text: 'which can fall under the question of <font color="#FFFF00">disability</font>, <font color="#FFFF00">learning disabilities (DYS)</font>, etc.' },
  { start: 634.600, end: 640.880, text: 'But behind all that, there can be health conditions that put the student in a' },
  { start: 640.881, end: 643.800, text: 'difficult situation for their learning.' },
  { start: 644.549, end: 649.900, text: 'It\'s pain or <font color="#FFFF00">disabling illnesses</font>, cancers,' },
  { start: 650.100, end: 654.860, text: 'we have students who are undergoing treatment, who are tired, who have' },
  { start: 654.861, end: 658.321, text: 'sleep issues, and that can also mean, they' },
  { start: 658.322, end: 661.500, text: 'need time to be able to change.' },
  { start: 662.099, end: 666.520, text: 'incontinence problems linked to a surgical procedure, for example,' },
  { start: 666.720, end: 671.418, text: 'or having to inject a treatment,' },
  { start: 671.419, end: 675.520, text: 'we often overlook the case of diabetic students.' },
  { start: 675.944, end: 681.580, text: 'In any case, we have a population of students in precarious health,' },
  { start: 681.800, end: 688.900, text: 'either occasionally, or chronically for a short period,' },
  { start: 688.901, end: 692.660, text: 'or over the entire course of study.' },
  { start: 694.015, end: 696.696, text: 'Beyond health, it\'s also worth' },
  { start: 696.697, end: 699.120, text: 'factoring in issues related to psychology.' },
  { start: 700.319, end: 705.720, text: 'We\'ve known since COVID arrived that there are other problems - obstacles,' },
  { start: 706.029, end: 711.200, text: 'to teaching, which are stress and anxiety, anguish, situations of' },
  { start: 711.201, end: 717.600, text: 'distress, and above all what mustn\'t be overlooked for students who have' },
  { start: 717.601, end: 722.100, text: 'left their parents for another region, issues related to isolation.' },
  { start: 724.149, end: 730.100, text: 'Today we can consider that this affects 1 in 3 students.' },
  { start: 731.185, end: 736.260, text: 'And finally the last one, not to be overlooked because it represents a lot' },
  { start: 736.261, end: 740.000, text: 'of students, is one-off incidents ...' },
  { start: 740.001, end: 744.860, text: 'or lasting ones in the student\'s personal life.' },
  { start: 745.939, end: 750.860, text: 'For example, bereavement, when one of the parents or a close' },
  { start: 750.861, end: 755.020, text: 'family member dies, the student loses their ability to learn.' },
  { start: 756.060, end: 761.107, text: 'We can also mention students who are themselves parents,' },
  { start: 761.108, end: 765.220, text: 'we\'ll see that it\'s the same volume as <font color="#FFFF00">disabled</font> students.' },
  { start: 765.980, end: 771.180, text: 'Students who are in digital, financial or housing <font color="#FFFF00">precarity</font>,' },
  { start: 771.181, end: 776.380, text: 'meaning they cannot find housing where they study.' },
  { start: 778.295, end: 783.040, text: 'And this leads to considerable travel times to get there,' },
  { start: 783.041, end: 787.780, text: 'or means they have to find a job to pay for their studies,' },
  { start: 788.180, end: 792.200, text: 'and so they become working students.' },
  { start: 792.819, end: 795.637, text: 'The status specific to that, which is the status' },
  { start: 795.638, end: 799.580, text: 'of "Apprentice", does not apply to them.' },
  { start: 799.680, end: 803.760, text: 'On the question of precarity, there\'s the case of students' },
  { start: 803.934, end: 807.960, text: 'who don\'t eat properly or every day.' },
  { start: 808.740, end: 814.240, text: 'These kinds of obstacles to learning need to be taken into account, and they are ...' },
  { start: 814.969, end: 819.274, text: 'barely visible, or even invisible to some,' },
  { start: 819.275, end: 823.980, text: 'we won\'t know unless the student tells us.' },
  { start: 824.600, end: 828.680, text: 'And that represents, on average, 1 in 5 students.' },
  { start: 828.954, end: 834.660, text: 'And that can vary depending on the student\'s socio-professional category.' },
  { start: 838.570, end: 844.670, text: 'Let\'s try to set out the broad volumes, the scale of these different cases.' },
  { start: 844.950, end: 849.990, text: 'I\'ve chosen 6, 5 plus <font color="#FFFF00">disability</font>, which is today\'s topic of interest,' },
  { start: 849.991, end: 855.810, text: 'around Parenthood, Health,' },
  { start: 855.959, end: 862.710, text: 'health problems other than <font color="#FFFF00">Disability</font>, a category I follow closely,' },
  { start: 862.711, end: 866.190, text: 'the question of students who are <font color="#FFFF00">Carers</font>,' },
  { start: 866.395, end: 871.950, text: 'for family members or others, and <font color="#FFFF00">Precarity</font>, which is at once...' },
  { start: 871.951, end: 876.450, text: '... financial or otherwise, and then the specific case of students with an' },
  { start: 876.451, end: 880.470, text: 'employment contract, who therefore hold the status of Working Students' },
  { start: 881.829, end: 886.090, text: 'The first category, on the far left, is' },
  { start: 886.091, end: 891.330, text: 'Student Parents, who have children, who must have a' },
  { start: 891.331, end: 895.790, text: 'balance between their life as a parent looking after their children ...' },
  { start: 896.025, end: 897.025, text: '... and their studies.' },
  { start: 897.395, end: 900.810, text: 'Today it\'s estimated that ...' },
  { start: 900.811, end: 902.774, text: 'it\'s roughly the same volume as' },
  { start: 902.775, end: 905.330, text: '<font color="#FFFF00">Disability</font>, that is around 2%.' },
  { start: 906.619, end: 912.370, text: '<font color="#FFFF00">Disability</font>, the 2nd case, which we discussed, "visible" today, meaning' },
  { start: 913.504, end: 921.030, text: 'reported at around 2.2%, with 64-68,000 students affected, and 1/3 visible' },
  { start: 921.129, end: 923.750, text: 'and 2/3 not visible but declared' },
  { start: 925.419, end: 930.290, text: '"Recurring" health issues, which can be cancers, diabetes,' },
  { start: 930.291, end: 936.310, text: 'which can be various illnesses caught during schooling,' },
  { start: 936.359, end: 940.750, text: 'that still concerns 9% of students, so we need to pay' },
  { start: 940.775, end: 946.950, text: 'attention to these students who don\'t necessarily show they have a' },
  { start: 947.149, end: 952.210, text: 'health problem, but which will need to be taken into account in our study.' },
  { start: 954.299, end: 960.490, text: '<font color="#FFFF00">Carers</font>, students in the 4th category, often found' },
  { start: 960.589, end: 965.350, text: 'in lower socio-professional backgrounds, especially found in the' },
  { start: 965.351, end: 968.063, text: 'farming sector, are students who devote' },
  { start: 968.163, end: 972.990, text: 'a large part of their time to helping a relative.' },
  { start: 973.239, end: 978.310, text: 'A parent, but it could also be a sibling, a <font color="#FFFF00">disabled</font> child, etc.' },
  { start: 982.801, end: 985.250, text: 'for years, it wasn\'t seen.' },
  { start: 985.390, end: 990.150, text: 'It\'s around 13-15% in our institutions.' },
  { start: 992.509, end: 997.370, text: 'Number 5, financial precarity, is the subject of much debate,' },
  { start: 997.510, end: 1000.310, text: 'and is often championed by student unions.' },
  { start: 1000.659, end: 1008.190, text: 'Difficulties making ends meet, and having to turn to' },
  { start: 1008.191, end: 1011.936, text: 'financial aid, but also food aid, such as the food' },
  { start: 1011.937, end: 1014.510, text: 'bank that you may have in your institutions.' },
  { start: 1015.009, end: 1018.310, text: 'Today this represents 1 in 3 students' },
  { start: 1019.045, end: 1023.870, text: 'And finally the last one, a special status, the status of Employee,' },
  { start: 1023.989, end: 1027.670, text: 'that is, with an actual Employment Contract, not someone' },
  { start: 1027.671, end: 1029.985, text: 'doing odd jobs now and then, and there are' },
  { start: 1029.986, end: 1033.810, text: 'conditions to establish that someone is a Working Student.' },
  { start: 1033.909, end: 1040.230, text: 'It\'s often said that it\'s around 10-15%, for apprenticeships' },
  { start: 1040.231, end: 1043.770, text: 'it\'s a status recognized in education (<font color="#FFFF00">work-study, FISA</font>).' },
  { start: 1044.750, end: 1050.290, text: 'And around 10% of students are employees who aren\'t full-time' },
  { start: 1050.489, end: 1052.990, text: 'but work regularly,' },
  { start: 1052.991, end: 1055.970, text: 'more than 60 hours a month' },
  { start: 1056.590, end: 1062.150, text: 'and finally, 10% of students who work occasionally.' },
  { start: 1062.324, end: 1063.790, text: 'During breaks, during weekends,' },
  { start: 1068.610, end: 1069.610, text: 'and mainly the summer holidays.' },
  { start: 1076.490, end: 1084.230, text: 'There are provisions to help these students' },
  { start: 1084.304, end: 1088.110, text: 'who have a <font color="#FFFF00">disability</font>, even if it isn\'t officially called a disability,' },
  { start: 1088.230, end: 1092.087, text: 'in any case, an obstacle to their learning, so I\'ve' },
  { start: 1092.088, end: 1095.190, text: 'gone back over these 6 cases I\'ve just presented:' },
  { start: 1096.299, end: 1100.750, text: 'Student-Parent, student with a <font color="#FFFF00">Disability</font>, students with a health problem,' },
  { start: 1101.790, end: 1107.390, text: 'Student-<font color="#FFFF00">Carer</font>, the student in financial precarity or otherwise.' },
  { start: 1107.730, end: 1113.270, text: 'And finally, Working Student. And I looked at what exists' },
  { start: 1113.294, end: 1117.650, text: 'today at the legal level, made available to these students.' },
  { start: 1118.049, end: 1122.710, text: 'With 3 cases which I\'ll describe in detail, the "Priority" cases,' },
  { start: 1122.910, end: 1130.210, text: 'which is a <font color="#FFFF00">Special Study Arrangement</font> (<font color="#FFFF00">RSE</font>), or failing that ...' },
  { start: 1130.211, end: 1134.330, text: 'adjusted conditions for organizing work.' },
  { start: 1136.339, end: 1142.530, text: 'Next, I\'ll look at whether <font color="#FFFF00">Adjusted Exams</font> were available for' },
  { start: 1142.531, end: 1147.810, text: 'these people, and finally, whether there\'s a <font color="#FFFF00">Training Agreement</font>' },
  { start: 1149.090, end: 1153.668, text: 'or specific plan, to help these students' },
  { start: 1153.669, end: 1159.570, text: 'get through these training obstacles.' },
  { start: 1160.419, end: 1165.270, text: 'I\'ve added two boxes that I won\'t go into detail on, which are' },
  { start: 1165.271, end: 1170.290, text: 'Financial Aid and Priority Access to housing, which can' },
  { start: 1170.589, end: 1173.990, text: 'apply to these students.' },
  { start: 1174.299, end: 1178.510, text: 'For instance, the €1 CROUS meal today applies to everyone.' },
  { start: 1179.949, end: 1183.990, text: 'Let\'s start with the Student-Parent and their special arrangement.' },
  { start: 1184.449, end: 1190.570, text: 'There are indeed rights for these students: adapted schedules,' },
  { start: 1190.571, end: 1196.270, text: 'in any case priority choices for organizing their time,' },
  { start: 1196.271, end: 1199.730, text: 'so as to reconcile their family life and their studies.' },
  { start: 1200.170, end: 1202.570, text: 'It\'s the "Early Childhood" law that prevails in this case.' },
  { start: 1202.749, end: 1205.250, text: 'You have to be able to take care of your child.' },
  { start: 1206.529, end: 1213.370, text: 'If we look at the parent, they also have possible Exam adjustments' },
  { start: 1213.419, end: 1218.990, text: 'with shifted exam dates or dedicated retakes when' },
  { start: 1219.304, end: 1221.855, text: 'necessary, but generally,' },
  { start: 1221.856, end: 1224.810, text: 'these students are well organized for that.' },
  { start: 1225.490, end: 1228.610, text: 'On the other hand, there\'s no recognition of their status through a ...' },
  { start: 1228.611, end: 1231.930, text: 'Training Plan or a specific <font color="#FFFF00">Training Agreement</font>.' },
  { start: 1234.429, end: 1238.330, text: 'The case of the <font color="#FFFF00">Disabled</font> student, the 2nd column, is much better known' },
  { start: 1239.170, end: 1245.710, text: 'They do have an (<font color="#FFFF00">RSE</font>) <font color="#FFFF00">Special Study Arrangement</font>, which involves an adjustment' },
  { start: 1245.884, end: 1251.890, text: 'of their schedule, organized by the committee or the <font color="#FFFF00">disability officer</font>.' },
  { start: 1253.070, end: 1258.450, text: 'And they also have an <font color="#FFFF00">attendance exemption</font> if necessary.' },
  { start: 1260.890, end: 1266.010, text: 'For exams or assessments, depending on their' },
  { start: 1266.159, end: 1268.650, text: 'situation and the committee\'s recommendations, they may have access to' },
  { start: 1269.979, end: 1273.990, text: '<font color="#FFFF00">Extra Time</font>, <font color="#FFFF00">Human Assistance</font>, <font color="#FFFF00">adapted materials</font>. Careful, an' },
  { start: 1273.991, end: 1277.949, text: '<font color="#FFFF00">adapted subject</font> is meant to help them in the context' },
  { start: 1277.950, end: 1280.770, text: 'of their <font color="#FFFF00">disability</font>, it isn\'t meant to make it easier.' },
  { start: 1281.369, end: 1287.230, text: 'It\'s about preventing the <font color="#FFFF00">Disability</font> from blocking understanding of the exam.' },
  { start: 1287.850, end: 1290.610, text: 'And in some cases, there may also be a separate booth ...' },
  { start: 1291.429, end: 1293.010, text: '... or a separate room.' },
  { start: 1293.224, end: 1297.790, text: 'All of this is governed by a <font color="#FFFF00">Training Agreement</font>, which is a <font color="#FFFF00">Personalized Agreement</font>' },
  { start: 1298.089, end: 1304.710, text: 'drawn up by the Committee or by the department or by the' },
  { start: 1304.711, end: 1306.950, text: '<font color="#FFFF00">Disability</font> officer, and which is binding on the institution.' },
  { start: 1309.539, end: 1313.333, text: 'For the 3rd case, 3rd column, involving a female' },
  { start: 1313.334, end: 1317.090, text: 'or male student with a health problem.' },
  { start: 1318.529, end: 1320.543, text: 'they also have a (<font color="#FFFF00">RSE</font>) <font color="#FFFF00">Special Study Arrangement</font> for when they have' },
  { start: 1320.544, end: 1323.970, text: 'health problems, with occasional' },
  { start: 1323.970, end: 1330.630, text: 'attendance exemptions (for the disabled student it was all the time)' },
  { start: 1330.631, end: 1332.530, text: '...' },
  { start: 1332.990, end: 1339.130, text: 'if it\'s justified: they must have an appointment,' },
  { start: 1339.131, end: 1342.650, text: 'medical care, it can\'t be a blanket exemption.' },
  { start: 1342.749, end: 1345.810, text: 'Here, it has to be justified.' },
  { start: 1346.119, end: 1349.790, text: 'For exams, it\'s roughly the same as for disability,' },
  { start: 1349.850, end: 1354.110, text: 'with <font color="#FFFF00">Extra Time</font>, <font color="#FFFF00">Extended Time</font> as in the case of the' },
  { start: 1354.111, end: 1356.725, text: '<font color="#FFFF00">Disabled</font> student, with a decision from the' },
  { start: 1356.726, end: 1359.270, text: 'tutor or in any case from an Academic officer.' },
  { start: 1361.339, end: 1364.590, text: 'For the <font color="#FFFF00">Training Agreement</font>, it\'s local, it\'s with the university.' },
  { start: 1365.190, end: 1371.450, text: 'There\'s no specific requirement, it\'s a Health Agreement Protocol' },
  { start: 1371.724, end: 1373.870, text: 'between the Student and the University.' },
  { start: 1376.050, end: 1382.230, text: 'For the <font color="#FFFF00">Carer</font>, the 4th column, they can join a group' },
  { start: 1382.231, end: 1384.570, text: 'or choose a special group of classes ...' },
  { start: 1384.571, end: 1387.630, text: 'so as to adjust their Timetable.' },
  { start: 1388.050, end: 1393.770, text: 'it\'s to help them and to give them time to play their role as <font color="#FFFF00">Carer</font>.' },
  { start: 1394.350, end: 1396.999, text: 'There can also be a Special Leave' },
  { start: 1397.000, end: 1399.790, text: 'of Absence, or in the case of an exam.' },
  { start: 1400.439, end: 1405.770, text: 'You really need a good reason, a justification, in order to have' },
  { start: 1405.919, end: 1407.910, text: 'an Authorized Absence.' },
  { start: 1408.904, end: 1413.610, text: 'Of course, if they have an Authorization, they get a personalized retake.' },
  { start: 1415.050, end: 1420.190, text: 'To date, there\'s no <font color="#FFFF00">Training Agreement</font> for <font color="#FFFF00">Carer</font> students,' },
  { start: 1420.191, end: 1423.990, text: 'who represent, as I said, 12 to 15% of the population today.' },
  { start: 1426.629, end: 1432.130, text: 'No provision has been made for column #5, which is the case of' },
  { start: 1432.131, end: 1436.490, text: '<font color="#FFFF00">Precarity</font>, whether Financial, Digital Precarity, etc.' },
  { start: 1445.119, end: 1451.150, text: 'The last one is the Working Student, and by Working Student I mean...' },
  { start: 1451.274, end: 1454.210, text: 'a student who has an <font color="#FFFF00">Employment Contract</font> with a company.' },
  { start: 1454.869, end: 1461.030, text: 'This can be a fixed-term or permanent contract, or any other Project Contract.' },
  { start: 1461.031, end: 1465.590, text: 'So, in education, we sometimes refer to these contracts, etc.' },
  { start: 1467.374, end: 1470.815, text: 'This doesn\'t apply to contracts that are quite substantial,' },
  { start: 1470.816, end: 1473.230, text: 'it isn\'t a small one-hour-a-week job.' },
  { start: 1473.710, end: 1479.110, text: 'We\'re talking here about adjustment when the workload of the <font color="#FFFF00">Employment Contract</font>' },
  { start: 1479.559, end: 1485.770, text: 'is around 60 hours a month or 120 hours a term' },
  { start: 1486.044, end: 1488.833, text: 'So, that\'s the most favorable situation (60h/month or 120h/term)' },
  { start: 1488.834, end: 1490.970, text: 'to be taken into account for the student.' },
  { start: 1491.515, end: 1496.550, text: 'And in that case, if the student has an Employment Contract of 60 h/month,' },
  { start: 1496.950, end: 1498.190, text: 'or 120 h/term' },
  { start: 1499.204, end: 1502.731, text: 'The Timetable must be adjusted, compulsorily,' },
  { start: 1502.781, end: 1504.890, text: 'Work takes priority over Teaching' },
  { start: 1507.559, end: 1512.350, text: 'If this concerns exams or knowledge assessments,' },
  { start: 1512.899, end: 1516.390, text: 'there may be exemptions from certain continuous assessments' },
  { start: 1517.590, end: 1521.170, text: 'And also, of course, adjusted tests, for example remotely,' },
  { start: 1521.329, end: 1522.730, text: 'if necessary.' },
  { start: 1525.280, end: 1530.210, text: 'As for the Working Student status, there is a specific contract,' },
  { start: 1530.434, end: 1534.210, text: '<font color="#FFFF00">FISA</font> (Initial Training under Apprentice Status), this is the <font color="#FFFF00">Apprenticeship Contract</font>' },
  { start: 1534.419, end: 1536.350, text: 'The others are not concerned ...' },
  { start: 1536.590, end: 1542.910, text: 'meaning fixed-term and permanent contracts are not covered by a Plan' },
  { start: 1542.911, end: 1547.110, text: 'or a specific <font color="#FFFF00">Training Agreement</font>, this only applies to Apprenticeships,' },
  { start: 1547.369, end: 1549.290, text: 'in France and nowhere else.' },
  { start: 1551.740, end: 1557.880, text: 'Financial Aid ... Priority Access ..., I\'ll let you read what exists.' },
  { start: 1557.880, end: 1563.822, text: 'There are many provisions to know about, in order to' },
  { start: 1563.823, end: 1567.060, text: 'help students when they need it.' },
  { start: 1572.109, end: 1578.650, text: 'Let\'s look at the case of the <font color="#FFFF00">Disabled</font> student, because behind disability,' },
  { start: 1578.885, end: 1582.050, text: 'or at least the adjustment, there\'s a strict protocol.' },
  { start: 1582.294, end: 1586.790, text: 'It must be applied, in any case, to avoid legal disputes that increasingly arise,' },
  { start: 1586.791, end: 1589.750, text: 'particularly in Private Schools.' },
  { start: 1589.870, end: 1590.962, text: 'In public schools there are a bit fewer ...' },
  { start: 1590.963, end: 1593.590, text: 'but in private schools, we\'re seeing them appear' },
  { start: 1594.729, end: 1600.170, text: 'This organization is described in the Education Laws and Codes,' },
  { start: 1600.550, end: 1603.771, text: 'it sets out a chain of decisions that' },
  { start: 1603.772, end: 1606.890, text: 'starts with the student, who must declare themselves.' },
  { start: 1607.274, end: 1611.870, text: 'nothing can be done without the student\'s declaration, and it\'s then put into practice' },
  { start: 1612.230, end: 1613.230, text: 'by the teacher.' },
  { start: 1614.150, end: 1618.050, text: 'There\'s no direct application, it\'s strictly refused.' },
  { start: 1618.104, end: 1620.135, text: 'A student who goes to see a teacher and says' },
  { start: 1620.215, end: 1621.950, text: '"well, I have this problem ...' },
  { start: 1622.299, end: 1626.350, text: 'please adjust my test!" ... that\'s often at the time of the tests that this happens' },
  { start: 1628.169, end: 1634.250, text: 'That isn\'t possible. The teacher isn\'t in a position' },
  { start: 1634.251, end: 1637.986, text: 'to judge, they\'re not a doctor, they aren\'t trained' },
  { start: 1637.987, end: 1640.370, text: 'specifically to recognize a <font color="#FFFF00">disability</font>.' },
  { start: 1640.774, end: 1642.510, text: 'They don\'t have to do it.' },
  { start: 1643.249, end: 1646.430, text: 'And if they do, there could be a dispute with another student,' },
  { start: 1647.414, end: 1651.250, text: 'because that student could say, <i>"He was favored and I wasn\'t, because</i>' },
  { start: 1651.251, end: 1653.965, text: '<i>he said such and such, and I\'m at a disadvantage</i>' },
  { start: 1653.966, end: 1656.170, text: '<i>because I didn\'t get <font color="#FFFF00">Extra Time</font>"</i>, etc.' },
  { start: 1656.909, end: 1662.150, text: 'You really need to be serious and refuse this kind of approach in any case!' },
  { start: 1662.151, end: 1668.450, text: 'the teacher does not have to adapt their course to a student\'s request.' },
  { start: 1669.230, end: 1675.950, text: 'The student must report the situation to a Department, or a Disability' },
  { start: 1676.099, end: 1680.670, text: '<font color="#FFFF00">Officer</font> (which is compulsory in schools), who will assess the situation.' },
  { start: 1681.979, end: 1686.970, text: 'If they need help, they can call on the doctor appointed by the ...' },
  { start: 1686.971, end: 1693.650, text: '<font color="#FFFF00">Commission for the Rights and Independence of People with Disabilities (CDAPH)</font>' },
  { start: 1694.349, end: 1697.730, text: 'located at the local Disability Support Office' },
  { start: 1697.731, end: 1701.910, text: 'and who will help them assess the situation.' },
  { start: 1703.559, end: 1710.610, text: 'Once the link between the student and the officer has been made, and' },
  { start: 1710.859, end: 1716.010, text: 'once a <font color="#FFFF00">disability</font> is actually confirmed, and not a' },
  { start: 1716.011, end: 1721.570, text: 'linguistic gap, or a problem mastering the French language,' },
  { start: 1722.390, end: 1728.510, text: 'they\'ll start drawing up an assessment covering all needs, according to' },
  { start: 1728.511, end: 1733.190, text: 'the law, namely Organization, Course Delivery,' },
  { start: 1733.264, end: 1736.459, text: 'and Support. There isn\'t, a priori, at the' },
  { start: 1736.460, end: 1740.210, text: 'legal level, a specific chapter on assessments.' },
  { start: 1741.759, end: 1746.077, text: 'On these 3 chapters, Organization-Delivery-' },
  { start: 1746.078, end: 1748.770, text: 'Support, no medical opinion is needed.' },
  { start: 1749.350, end: 1754.970, text: 'Here, it\'s the Academic officer, or the <font color="#FFFF00">Disability</font> officer who are the' },
  { start: 1754.971, end: 1759.210, text: 'ones responsible for this Support plan.' },
  { start: 1760.259, end: 1763.510, text: 'On the other hand, in some cases, if it has never been done before.' },
  { start: 1763.970, end: 1767.274, text: 'It\'s worth knowing that <font color="#FFFF00">exam adjustments</font>' },
  { start: 1767.275, end: 1770.670, text: 'may require a <u>compulsory doctor\'s opinion.</u>' },
  { start: 1778.111, end: 1782.210, text: 'for example, or in other <font color="#FFFF00">invisible disability</font> cases, it\'s well known,' },
  { start: 1783.330, end: 1787.830, text: 'But it\'s a doctor who will state it, who will request it.' },
  { start: 1787.831, end: 1789.870, text: 'In any case, a medical opinion is required.' },
  { start: 1790.184, end: 1792.830, text: 'It can\'t be given any other way.' },
  { start: 1794.250, end: 1799.270, text: 'Once the needs assessment has been carried out, it applies to the institution,' },
  { start: 1799.271, end: 1803.750, text: 'and it\'s up to the institution, (which has hierarchical authority)' },
  { start: 1803.751, end: 1808.710, text: 'to enforce it for everyone, and especially for teachers, who will' },
  { start: 1808.711, end: 1815.110, text: 'have the person, the student, in their class, during the' },
  { start: 1815.334, end: 1818.790, text: 'training, or during knowledge assessments.' },
  { start: 1824.939, end: 1828.260, text: 'I said that the teacher isn\'t in a position to assess...' },
  { start: 1828.300, end: 1834.160, text: '... the need and, in any case, to give a medical opinion on the person.' },
  { start: 1835.280, end: 1837.460, text: 'That\'s true, but it doesn\'t prevent the training.' },
  { start: 1837.634, end: 1839.818, text: 'Not only doesn\'t it prevent it, but I' },
  { start: 1839.819, end: 1843.400, text: 'should point out that this training is <u>Compulsory.</u>' },
  { start: 1843.699, end: 1848.340, text: 'That means it falls under <u>Compulsory Training</u> that an employer must' },
  { start: 1848.341, end: 1853.400, text: 'give an employee, like, for example, Safety Training.' },
  { start: 1855.064, end: 1859.700, text: 'So this training is compulsory, it was introduced from the start in ...' },
  { start: 1859.701, end: 1863.140, text: '... the 2005 law and was then confirmed in' },
  { start: 1863.141, end: 1867.300, text: 'various laws, the latest being from 15 November 2014.' },
  { start: 1867.849, end: 1871.280, text: 'Known as the "School of Trust" law, which is a bit broader,' },
  { start: 1871.614, end: 1873.300, text: 'and much more <font color="#FFFF00">inclusive</font>.' },
  { start: 1874.135, end: 1878.180, text: 'It says that teachers, but also all supervisory staff ...' },
  { start: 1878.354, end: 1883.260, text: 'technical, service, etc, and reception staff must have, during their training,' },
  { start: 1883.260, end: 1888.500, text: 'if it\'s initial training, for example for teachers, but also during' },
  { start: 1888.501, end: 1891.240, text: 'the course of their work,' },
  { start: 1891.475, end: 1892.475, text: 'as part of <font color="#FFFF00">Continuing Education</font>,' },
  { start: 1892.774, end: 1896.660, text: 'specific training on welcoming/educating pupils and' },
  { start: 1896.661, end: 1901.200, text: 'students in a <font color="#FFFF00">disability</font> situation, and I don\'t know why this sentence...' },
  { start: 1901.420, end: 1902.420, text: 'is there, but it is.' },
  { start: 1902.780, end: 1906.560, text: '"<i>In particular, or notably those who present a</i>' },
  { start: 1906.561, end: 1910.240, text: 'behavioral disorder or a <i><font color="#FFFF00">neurodevelopmental disorder</font>.</i>' },
  { start: 1911.669, end: 1914.980, text: 'A small note in passing, in the case of Apprenticeships,' },
  { start: 1915.894, end: 1920.100, text: 'and I\'m thinking of BTS students who are often in the lab or doing practical work,' },
  { start: 1921.180, end: 1924.400, text: '<font color="#FFFF00">inclusion</font> doesn\'t only concern the <font color="#FFFF00">accessibility</font> of' },
  { start: 1924.974, end: 1927.580, text: 'classrooms, but it concerns the whole lab,' },
  { start: 1927.620, end: 1929.540, text: 'the pace of the work-study rhythm, the company.' },
  { start: 1930.980, end: 1938.400, text: 'And you need to be precise, especially on health and safety practices.' },
  { start: 1944.344, end: 1947.840, text: 'Consequently, to close' },
  { start: 1947.841, end: 1952.000, text: 'this chapter on the observations, here\'s a non-exhaustive list' },
  { start: 1952.460, end: 1957.860, text: 'of training that can be applied.' },
  { start: 1958.160, end: 1963.440, text: 'so, compulsory training, that can be applied to all' },
  { start: 1963.441, end: 1967.300, text: 'staff, supervisors, reception staff, and support staff.' },
  { start: 1968.674, end: 1973.318, text: 'The first is well known, it\'s the "<font color="#FFFF00">Cap Ecole Inclusive</font>" (Inclusive School) training' },
  { start: 1973.319, end: 1976.460, text: 'which has been developed for several years.' },
  { start: 1976.554, end: 1981.400, text: 'not only is there training, but also teaching resources' },
  { start: 1981.401, end: 1984.516, text: 'it\'s a whole platform that has been developed' },
  { start: 1984.517, end: 1987.340, text: 'around "Confiance" (Trust) elements.' },
  { start: 1988.990, end: 1993.760, text: 'So, it\'s more than <font color="#FFFF00">Disability</font>, it\'s <font color="#FFFF00">Inclusivity</font>' },
  { start: 1994.320, end: 1995.700, text: 'in general.' },
  { start: 1997.859, end: 2002.260, text: 'For "Paralysés de France", it\'s an association.' },
  { start: 2003.259, end: 2008.380, text: 'There\'s also training on the question of <font color="#FFFF00">accessibility</font>, <font color="#FFFF00">inclusion</font>,' },
  { start: 2008.585, end: 2013.580, text: 'it mainly concerns <font color="#FFFF00">physically disabled</font> people, who this association mainly deals with.' },
  { start: 2014.154, end: 2016.440, text: 'They come on site, they can intervene' },
  { start: 2016.519, end: 2021.480, text: 'in your institution and with the general administration.' },
  { start: 2023.769, end: 2030.140, text: 'The 3rd is a MOOC, quite original, produced by AFPA' },
  { start: 2030.141, end: 2034.100, text: 'called "<font color="#FFFF00">Disability</font>, keys to action towards employment"' },
  { start: 2034.734, end: 2039.740, text: 'It\'s generally well structured, on the topic of <font color="#FFFF00">disability</font>' },
  { start: 2040.699, end: 2044.100, text: 'for <font color="#FFFF00">inclusion</font>, in training and in employment.' },
  { start: 2044.101, end: 2050.060, text: 'So, very broad, it\'s a recognized distance-learning course, and it won' },
  { start: 2050.385, end: 2055.300, text: 'the "Open Educaton Night 2023" award' },
  { start: 2055.380, end: 2056.388, text: 'There\'s no spelling mistake' },
  { start: 2056.389, end: 2060.239, text: 'It really is spelled "EduCaton" here' },
  { start: 2060.739, end: 2064.300, text: 'Failing that, if you don\'t know which one to choose, you can go with this one' },
  { start: 2064.301, end: 2068.159, text: 'and note that the people have completed this MOOC.' },
  { start: 2071.110, end: 2077.159, text: 'The 4th are the platforms or all the training offered by the National' },
  { start: 2077.360, end: 2082.159, text: 'Union of Families and Friends of <font color="#FFFF00">People with Mental Illness and/or Psychological Disabilities</font>' },
  { start: 2083.280, end: 2089.290, text: 'This isn\'t aimed at disabled people, it\'s for professionals.' },
  { start: 2092.290, end: 2096.590, text: 'If we focus on <font color="#FFFF00">DYS</font>, there\'s the French Federation of <font color="#FFFF00">DYS</font>,' },
  { start: 2096.770, end: 2100.920, text: 'which offers training in the 6 areas' },
  { start: 2100.921, end: 2104.370, text: 'of <font color="#FFFF00">cognitive disorders</font> linked to <font color="#FFFF00">DYS</font>, for higher' },
  { start: 2104.495, end: 2110.090, text: 'education and for the professional field, very good.' },
  { start: 2110.370, end: 2113.170, text: 'A bit pricey for my taste, but of great quality.' },
  { start: 2114.230, end: 2120.410, text: 'Finally, let\'s not forget that you can also train in other areas, other' },
  { start: 2120.411, end: 2124.610, text: 'languages, in particular in <font color="#FFFF00">French Sign Language</font>.' },
  { start: 2125.740, end: 2128.930, text: 'there are associations and an online training platform' },
  { start: 2129.750, end: 2137.250, text: 'called "Signes de Sens", which allows people to learn sign' },
  { start: 2137.251, end: 2139.909, text: 'language, sorry, for the <font color="#FFFF00">inclusion</font> of hard-of-hearing people, in any case people who have hearing problems.' },


  { start: 2139.910, end: 2144.000, text: 'Thank you for your attention. Go to Chapter 2.' },

];

const SUBTITLES_ES_CH1 = [
{ start: 1.000, end: 12.120, text: 'Bienvenido al programa BRIDGE -<font color="#FFFF00"> Bridging Research and Inclusive Digital Education</font>' },
  { start: 12.130, end: 19.630, text: 'Vamos ahora a abordar la conferencia de hoy, que trata sobre' },
  { start: 19.631, end: 23.830, text: 'la integración de personas con una <font color="#FFFF00">discapacidad</font>' },
  { start: 24.220, end: 27.170, text: 'o, en todo caso, que tienen bloqueos durante la enseñanza.' },
  { start: 27.350, end: 31.570, text: 'Habrá una fuerte connotación de "<font color="#FFFF00">Discapacidad</font>" en esta presentación.' },
  { start: 32.155, end: 36.750, text: 'Pero esto trata esencialmente de la "<font color="#FFFF00">Enseñanza Inclusiva</font>"' },
  { start: 37.295, end: 40.530, text: 'Vamos a empezar con un primer capítulo de constataciones,' },
  { start: 40.531, end: 45.630, text: 'el volumen, quiénes son las personas afectadas por esta conferencia.' },
  { start: 63.885, end: 66.527, text: 'Esto es una mirada al volumen relativo a' },
  { start: 66.577, end: 69.160, text: 'las estudiantes y los estudiantes con <font color="#FFFF00">discapacidad</font>.' },
  { start: 70.019, end: 73.571, text: 'De hecho, para simplificar, esto representa' },
  { start: 73.572, end: 77.020, text: 'el 3% de la población estudiantil que hay en Francia.' },
  { start: 77.720, end: 84.740, text: 'Así que hoy estamos alrededor de, reconocidamente, 60.000 estudiantes.' },
  { start: 85.139, end: 89.080, text: 'Estas cifras son engañosas y, en particular, no son representativas' },
  { start: 89.081, end: 92.180, text: 'de la totalidad de las <font color="#FFFF00">discapacidades</font> que uno puede encontrar.' },
  { start: 92.720, end: 97.540, text: 'En todo caso, representativas de la población que tenemos en clase.' },
  { start: 98.740, end: 106.540, text: 'De este 3%, el 70% son <font color="#FFFF00">discapacidades invisibles</font>,' },
  { start: 106.949, end: 110.640, text: 'en cualquier caso, muy difíciles de detectar a primera vista,' },
  { start: 111.039, end: 116.040, text: 'porque pueden implicar <font color="#FFFF00">trastornos psíquicos</font>, enfermedades' },
  { start: 116.040, end: 121.700, text: 'invalidantes, <font color="#FFFF00">trastornos cognitivos</font>, siendo el <font color="#FFFF00">DYS</font> el más conocido,' },
  { start: 122.680, end: 127.960, text: 'o formas de <font color="#FFFF00">autismo</font>, que son perfectamente capaces de seguir una enseñanza.' },
  { start: 128.900, end: 131.940, text: 'Es decir, autismo de base. Aquí está alrededor del 5%.' },
  { start: 134.810, end: 137.864, text: 'Las <font color="#FFFF00">discapacidades invisibles</font> también incluyen' },
  { start: 137.865, end: 141.800, text: '<font color="#FFFF00">trastornos del habla</font>, que representan alrededor del 22%.' },
  { start: 141.801, end: 149.680, text: 'Los <font color="#FFFF00">trastornos cognitivos</font> (derecha y abajo) están alrededor del 6%.' },
  { start: 150.255, end: 156.020, text: 'En cambio, 1 de cada 3 estudiantes <font color="#FFFF00">con discapacidad</font> tiene' },
  { start: 156.021, end: 160.700, text: 'trastornos <font color="#FFFF00">visibles</font>, que son los <font color="#FFFF00">trastornos motores</font>, los <font color="#FFFF00">trastornos visuales</font> (problemas de vista...' },
  { start: 160.701, end: 165.740, text: 'hasta la ceguera total), y <font color="#FFFF00">problemas auditivos</font>, hasta la sordera total.' },
  { start: 165.984, end: 170.780, text: 'Aquí, la mayoría de las discapacidades visibles son' },
  { start: 170.781, end: 174.680, text: '<font color="#FFFF00">trastornos motores</font> (alrededor del 10%).' },
  { start: 176.280, end: 179.141, text: 'Como pueden ver,' },
  { start: 179.142, end: 181.660, text: '2/3 no son visibles, 1/3 son visibles.' },
  { start: 182.380, end: 188.420, text: 'Si observamos el reparto de estos estudiantes con dificultades,' },
  { start: 188.421, end: 195.300, text: 'en la educación superior, vemos que están sobre todo concentrados en' },
  { start: 195.301, end: 199.527, text: 'las universidades, que "captan" o acogen en todo caso' },
  { start: 199.528, end: 203.880, text: 'al menos 8 de cada 10 estudiantes con <font color="#FFFF00">discapacidad</font>.' },
  { start: 204.560, end: 209.620, text: 'Luego, vemos que el segundo nivel son los centros privados' },
  { start: 209.621, end: 214.140, text: 'de interés general, llamados comúnmente "EESPIG", los' },
  { start: 214.141, end: 219.040, text: 'Centros de Enseñanza Superior Privados de Interés General, que,' },
  { start: 219.041, end: 223.340, text: 'hoy en día, estas cifras son más altas, alrededor del 8 al 10%.' },
  { start: 223.440, end: 229.260, text: 'Las cifras que les presento aquí, a la derecha, a la izquierda, y,' },
  { start: 229.435, end: 232.420, text: 'de hecho, son antiguas, de 2024' },
  { start: 234.000, end: 240.120, text: 'En cuanto a las clases preparatorias y los institutos de la educación nacional,' },
  { start: 240.554, end: 244.680, text: 'estamos alrededor del 4 al 5% de estudiantes con <font color="#FFFF00">discapacidad</font>.' },
  { start: 245.040, end: 247.803, text: 'Y luego, en las demás escuelas públicas,' },
  { start: 247.804, end: 251.640, text: 'fuera de la universidad, estamos alrededor del 3 al 4%.' },
  { start: 252.340, end: 258.279, text: 'Así que, para simplificar, vemos que una pequeña parte de la <font color="#FFFF00">discapacidad</font>' },
  { start: 258.380, end: 263.300, text: 'y en todo caso, solo vemos el 1% de las personas con <font color="#FFFF00">discapacidad</font>.' },
  { start: 264.085, end: 268.840, text: 'Lo notable, (lo que anoté en medio del recuadro a la derecha)' },
  { start: 268.841, end: 272.520, text: 'es que si miramos los campos científicos,' },
  { start: 273.120, end: 277.280, text: 'pues bien, solo hay un 29%, un tercio para simplificar, de' },
  { start: 277.281, end: 279.480, text: 'personas con <font color="#FFFF00">discapacidad</font> que se orientan hacia campos científicos.' },
  { start: 280.740, end: 286.500, text: 'Por lo tanto, es totalmente legítimo que un profesor' },
  { start: 287.125, end: 288.125, text: 'les diga' },
  { start: 288.185, end: 290.860, text: '"Perdón, pero no tengo ningún estudiante con <font color="#FFFF00">discapacidad</font> en mi clase".' },
  { start: 291.600, end: 294.840, text: 'O bien realmente no lo hay, porque la población es bastante reducida ..' },
  { start: 295.480, end: 301.140, text: 'o bien lo hay, pero no será visible si no se lo dicen.' },
  { start: 305.460, end: 309.440, text: 'Entonces, estas cifras contradicen la impresión que uno puede tener' },
  { start: 309.441, end: 313.400, text: 'al observar a la población de estudiantes' },
  { start: 313.540, end: 314.620, text: 'que tenemos en las aulas.' },
  { start: 315.420, end: 321.000, text: 'Y en particular sobre la cuestión de los <font color="#FFFF00">DYS</font>, que son ...' },
  { start: 321.195, end: 325.140, text: 'los problemas, las <font color="#FFFF00">discapacidades</font>, ligados a un <font color="#FFFF00">trastorno cognitivo</font> duradero.' },
  { start: 326.000, end: 333.040, text: 'Recuerdo que el <font color="#FFFF00">DYS</font> es "médico", y no tiene relación con la categoría' },
  { start: 333.041, end: 336.132, text: 'socioprofesional de los padres ni del estudiante,' },
  { start: 336.133, end: 338.860, text: 'por lo tanto, es totalmente independiente del entorno social.' },
  { start: 339.645, end: 341.777, text: 'y también del origen lingüístico, el <font color="#FFFF00">DYS</font> aparece ...' },
  { start: 341.778, end: 344.660, text: 'en todas las poblaciones alrededor del mundo.' },
  { start: 346.025, end: 350.800, text: 'Sobre la población, mostraba cifras alrededor del 7%,' },
  { start: 351.410, end: 352.864, text: 'que es aproximadamente lo que tenemos.' },
  { start: 352.865, end: 357.820, text: 'Y si miramos las formas más severas del <font color="#FFFF00">DYS</font>, es alrededor del 3 al 5%.' },
  { start: 359.360, end: 363.140, text: 'El reconocimiento del <font color="#FFFF00">DYS</font> se hace de una forma muy clara' },
  { start: 363.640, end: 369.680, text: 'Es la diferencia, es la brecha, que se puede constatar entre el comportamiento' },
  { start: 369.855, end: 375.520, text: 'oral y relacional de un estudiante que comprende totalmente la clase oral,' },
  { start: 375.870, end: 380.880, text: 'que tiene un vocabulario rico, que tiene una excelente comprensión de los conceptos,' },
  { start: 381.305, end: 385.480, text: 'e incluso si son complejos, puede tener algunas situaciones,' },
  { start: 386.140, end: 387.399, text: 'algunas inversiones de vez en cuando.' },
  { start: 387.400, end: 389.360, text: 'pero eso sigue siendo menor.' },
  { start: 389.575, end: 392.931, text: 'En cambio, cuando se pasa a lo escrito y en particular' },
  { start: 392.932, end: 396.420, text: 'cuando tiene que comprender un enunciado o escribirlo...' },
  { start: 396.920, end: 403.220, text: 'Pues bien, la <font color="#FFFF00">discapacidad</font> se revela con faltas de ortografía' },
  { start: 403.221, end: 407.320, text: 'pero eso es un efecto inducido, un sesgo de la <font color="#FFFF00">dislexia</font>' },
  { start: 407.445, end: 410.320, text: 'pero hay también fusiones, lentitud, inversiones de palabras.' },
  { start: 411.830, end: 415.740, text: 'Y eso les hace las fuentes difíciles, en cualquier caso hay una verdadera' },
  { start: 415.741, end: 418.940, text: 'fatiga cognitiva ligada a esta dificultad con lo escrito.' },
  { start: 419.460, end: 425.080, text: 'Así que, esa es la brecha, entre lo que se ve de la persona y su producción escrita,' },
  { start: 425.360, end: 430.760, text: 'que es una característica del <font color="#FFFF00">DYS</font>. Esta característica tiene una solución,' },
  { start: 431.585, end: 434.820, text: '"médica", aunque el término no sea del todo apropiado.' },
  { start: 435.455, end: 438.045, text: 'Lo primero, y es cierto que fue eficaz,' },
  { start: 438.046, end: 440.300, text: 'es evitar todo lo que provoque fatiga' },
  { start: 440.450, end: 444.040, text: 'la "<font color="#FFFF00">Fatiga Cognitiva</font>", en pocas palabras, es dar más tiempo.' },
  { start: 444.820, end: 447.799, text: 'Y luego ciertas evaluaciones logopédicas en particular' },
  { start: 447.800, end: 450.800, text: 'son bastante eficaces para corregir este tipo de cosas.' },
  { start: 452.260, end: 455.290, text: 'Y además, tenemos una población de estudiantes' },
  { start: 455.291, end: 458.200, text: 'que parecerían tener el mismo problema, en particular al escribir' },
  { start: 459.870, end: 463.000, text: 'Pero cuando se observa bien, lo oral también es un problema.' },
  { start: 463.785, end: 466.720, text: 'En realidad es un déficit de aprendizaje del idioma.' },
  { start: 467.020, end: 469.896, text: 'Y en comparación con los casos de <font color="#FFFF00">DYS</font> que vimos' },
  { start: 469.897, end: 472.320, text: 'aquí en la tabla y en la columna de la izquierda.' },
  { start: 473.020, end: 475.720, text: 'Aquí, se trata de soluciones duraderas.' },
  { start: 476.450, end: 481.320, text: 'Es decir, el problema desaparecerá con el tiempo, mediante' },
  { start: 481.545, end: 487.100, text: 'la práctica, una exposición regular al idioma, a la cultura,' },
  { start: 487.101, end: 490.840, text: 'pero también extremadamente diversas en su forma.' },
  { start: 491.825, end: 494.405, text: 'Y podemos citar, por ejemplo, los cursos de <font color="#FFFF00">FLE</font> (francés lengua extranjera) que' },
  { start: 494.406, end: 498.140, text: 'existen hoy en todos los centros, y que ayudan mucho' },
  { start: 498.141, end: 502.040, text: 'Es un apoyo logístico que hay que implementar, y que permite una' },
  { start: 502.041, end: 505.920, text: 'progresión rápida y definitiva, y no tiene nada de "médico".' },
  { start: 506.840, end: 511.860, text: 'En cambio, es cierto que la población afectada es importante,' },
  { start: 511.861, end: 516.500, text: 'hoy se estima que las formas de "<font color="#FFFF00">analfabetismo funcional</font>", es decir la incapacidad de' },
  { start: 516.501, end: 522.919, text: 'escribir o comprender un texto, están alrededor del 7% de la población de 8 a 65 años' },
  { start: 522.920, end: 527.340, text: 'esas son las cifras nacionales, y si observamos a los estudiantes,' },
  { start: 527.520, end: 532.140, text: 'un indicador es el de los nuevos ingresantes tras el Bachillerato,' },
  { start: 532.989, end: 535.720, text: 'se llega a una población del 10 al 15%.' },
  { start: 536.419, end: 540.820, text: 'Aquí tenemos una verdadera dificultad, ya que estos estudiantes tienen' },
  { start: 540.845, end: 545.560, text: 'un vocabulario limitado en lo oral y en lo escrito, y también dificultades de' },
  { start: 547.504, end: 554.380, text: 'comprensión, pero esto no es <font color="#FFFF00">DYS</font>. El <font color="#FFFF00">DYS</font> cuenta con un apoyo "legal",' },
  { start: 554.500, end: 561.060, text: 'para ayudar, en todo caso para retirar la barrera de la <font color="#FFFF00">discapacidad</font>,' },
  { start: 561.209, end: 564.980, text: 'mientras que en el otro caso no hay ninguna disposición legal.' },
  { start: 572.809, end: 576.940, text: 'Podemos extender esta reflexión, que acabamos de aplicar entre los' },
  { start: 577.039, end: 581.200, text: '<font color="#FFFF00">DYS</font> y las personas con problemas de adquisición del idioma francés,' },
  { start: 581.729, end: 587.820, text: 'a otros tipos de <font color="#FFFF00">discapacidades</font>, o en todo caso, si no es una' },
  { start: 587.821, end: 591.840, text: '<font color="#FFFF00">discapacidad</font>, claramente son obstáculos para el aprendizaje.' },
  { start: 594.099, end: 597.380, text: 'Lo represento en forma de cebolla, con capas sucesivas.' },
  { start: 598.380, end: 601.820, text: 'El núcleo, del que no hemos hablado, son las <font color="#FFFF00">discapacidades</font> que serán conocidas,' },
  { start: 601.900, end: 607.120, text: 'con un 1/3 visible y 2/3 no visible,' },
  { start: 607.260, end: 608.139, text: 'pero declaradas.' },
  { start: 608.140, end: 612.380, text: 'Y la cifra que mencioné antes, alrededor de 60, 70 mil,' },
  { start: 612.554, end: 615.920, text: '64.000 aquí, es bastante clara.' },
  { start: 616.380, end: 621.060, text: 'Pero detrás, todavía hay <font color="#FFFF00">discapacidades invisibles</font> que no están declaradas.' },
  { start: 622.339, end: 627.380, text: 'Así que encontramos el <font color="#FFFF00">Autismo</font>, enfermedades crónicas de por vida,' },
  { start: 627.555, end: 630.580, text: 'que pueden entrar en la cuestión de <font color="#FFFF00">discapacidad</font>, los <font color="#FFFF00">DYS</font>, etc.' },
  { start: 634.600, end: 640.880, text: 'Pero detrás de todo eso, puede haber condiciones de salud que ponen al estudiante en una' },
  { start: 640.881, end: 643.800, text: 'situación difícil para su aprendizaje.' },
  { start: 644.549, end: 649.900, text: 'Es el dolor o las <font color="#FFFF00">enfermedades invalidantes</font>, los cánceres,' },
  { start: 650.100, end: 654.860, text: 'tenemos estudiantes en tratamiento, que están cansados, que tienen problemas' },
  { start: 654.861, end: 658.321, text: 'de sueño, y eso también puede implicar, necesitan' },
  { start: 658.322, end: 661.500, text: 'tiempo para poder cambiarse.' },
  { start: 662.099, end: 666.520, text: 'problemas de incontinencia ligados a una intervención quirúrgica, por ejemplo,' },
  { start: 666.720, end: 671.418, text: 'o tener que inyectarse un tratamiento,' },
  { start: 671.419, end: 675.520, text: 'a menudo se olvida el caso de los diabéticos.' },
  { start: 675.944, end: 681.580, text: 'En todo caso, tenemos una población de estudiantes con salud precaria,' },
  { start: 681.800, end: 688.900, text: 'ya sea de forma puntual, ya sea crónica y de corta duración,' },
  { start: 688.901, end: 692.660, text: 'ya sea a lo largo de toda la formación.' },
  { start: 694.015, end: 696.696, text: 'Más allá de la salud, también conviene' },
  { start: 696.697, end: 699.120, text: 'integrar las cuestiones relacionadas con la psicología.' },
  { start: 700.319, end: 705.720, text: 'Lo sabemos desde la llegada del COVID, hay otros problemas, obstáculos,' },
  { start: 706.029, end: 711.200, text: 'a la enseñanza, que son el estrés y la ansiedad, las angustias, las situaciones de' },
  { start: 711.201, end: 717.600, text: 'angustia y, sobre todo, lo que no hay que ignorar para los estudiantes que han' },
  { start: 717.601, end: 722.100, text: 'dejado a sus padres por otra región, cuestiones relacionadas con el aislamiento.' },
  { start: 724.149, end: 730.100, text: 'Hoy podemos considerar que esto afecta a 1 de cada 3 estudiantes.' },
  { start: 731.185, end: 736.260, text: 'Y por último, el último, que no hay que descuidar porque representa mucho' },
  { start: 736.261, end: 740.000, text: 'de los estudiantes, son incidentes puntuales ...' },
  { start: 740.001, end: 744.860, text: 'o duraderos en la vida personal del estudiante.' },
  { start: 745.939, end: 750.860, text: 'Por ejemplo, el duelo, cuando uno de los padres o un familiar' },
  { start: 750.861, end: 755.020, text: 'cercano fallece, el estudiante pierde su capacidad de aprender.' },
  { start: 756.060, end: 761.107, text: 'También podemos mencionar a los estudiantes que son padres,' },
  { start: 761.108, end: 765.220, text: 'veremos que es el mismo volumen que las personas con <font color="#FFFF00">discapacidad</font>.' },
  { start: 765.980, end: 771.180, text: 'Los estudiantes en <font color="#FFFF00">precariedad</font> digital, financiera o habitacional,' },
  { start: 771.181, end: 776.380, text: 'es decir, que no pueden alojarse en el lugar donde estudian.' },
  { start: 778.295, end: 783.040, text: 'Y eso conlleva tiempos de desplazamiento considerables para poder venir,' },
  { start: 783.041, end: 787.780, text: 'o el hecho de que tengan que encontrar un trabajo para pagar sus estudios,' },
  { start: 788.180, end: 792.200, text: 'y por lo tanto se convierten en estudiantes trabajadores.' },
  { start: 792.819, end: 795.637, text: 'El estatus propio de eso, que es el estatus' },
  { start: 795.638, end: 799.580, text: 'de "Aprendiz", no se aplica a ellos.' },
  { start: 799.680, end: 803.760, text: 'Sobre las cuestiones de precariedad, está el caso de los estudiantes' },
  { start: 803.934, end: 807.960, text: 'que no se alimentan de forma correcta o cotidiana.' },
  { start: 808.740, end: 814.240, text: 'Hay que tener en cuenta este tipo de obstáculos para el aprendizaje, que también son ...' },
  { start: 814.969, end: 819.274, text: 'poco visibles, o incluso invisibles para algunos,' },
  { start: 819.275, end: 823.980, text: 'no lo sabremos a menos que el estudiante nos lo diga.' },
  { start: 824.600, end: 828.680, text: 'Y eso representa, en promedio, 1 de cada 5 estudiantes.' },
  { start: 828.954, end: 834.660, text: 'Y eso puede variar según la categoría socioprofesional del estudiante.' },
  { start: 838.570, end: 844.670, text: 'Intentemos fijar los grandes volúmenes, la magnitud de estos diferentes casos.' },
  { start: 844.950, end: 849.990, text: 'He elegido 6, 5 más la <font color="#FFFF00">discapacidad</font>, que es el tema de interés de hoy,' },
  { start: 849.991, end: 855.810, text: 'en torno a la Parentalidad, la Salud,' },
  { start: 855.959, end: 862.710, text: 'los problemas de salud fuera de la <font color="#FFFF00">Discapacidad</font>, una categoría que sigo con atención,' },
  { start: 862.711, end: 866.190, text: 'la cuestión de los estudiantes que son <font color="#FFFF00">Cuidadores</font>,' },
  { start: 866.395, end: 871.950, text: 'de familiares u otros, la <font color="#FFFF00">Precariedad</font>, que es a la vez...' },
  { start: 871.951, end: 876.450, text: '... financiera u otra, y por último el caso particular de los estudiantes con un contrato' },
  { start: 876.451, end: 880.470, text: 'de trabajo, que por lo tanto tienen el estatus de Estudiantes-Trabajadores' },
  { start: 881.829, end: 886.090, text: 'La primera categoría, totalmente a la izquierda, es' },
  { start: 886.091, end: 891.330, text: 'los Estudiantes Padres, que tienen hijos, que deben lograr un' },
  { start: 891.331, end: 895.790, text: 'equilibrio entre su vida como padres, cuidando a sus hijos ...' },
  { start: 896.025, end: 897.025, text: '... y sus estudios.' },
  { start: 897.395, end: 900.810, text: 'Hoy se estima que ...' },
  { start: 900.811, end: 902.774, text: 'es aproximadamente el mismo volumen que' },
  { start: 902.775, end: 905.330, text: 'la <font color="#FFFF00">Discapacidad</font>, es decir, alrededor del 2%.' },
  { start: 906.619, end: 912.370, text: 'La <font color="#FFFF00">Discapacidad</font>, el 2º caso, del que ya hablamos, "visible" hoy, es decir' },
  { start: 913.504, end: 921.030, text: 'registrada en torno al 2,2%, con 64-68.000 estudiantes afectados, y 1/3 visible' },
  { start: 921.129, end: 923.750, text: 'y 2/3 no visible pero declarada' },
  { start: 925.419, end: 930.290, text: 'Los problemas de salud "recurrentes", que pueden ser cánceres, diabetes,' },
  { start: 930.291, end: 936.310, text: 'que pueden ser diversas enfermedades contraídas durante los estudios,' },
  { start: 936.359, end: 940.750, text: 'esto afecta de todas formas al 9% de los estudiantes, así que hay que prestar' },
  { start: 940.775, end: 946.950, text: 'atención a estos estudiantes que no muestran necesariamente que tienen un problema' },
  { start: 947.149, end: 952.210, text: 'de salud, pero que habrá que tener en cuenta en nuestro estudio.' },
  { start: 954.299, end: 960.490, text: 'Los <font color="#FFFF00">Cuidadores</font>, estudiantes de la 4ª categoría, que se encuentran a menudo' },
  { start: 960.589, end: 965.350, text: 'en categorías socioprofesionales más humildes, particularmente en el ámbito' },
  { start: 965.351, end: 968.063, text: 'agrícola, son estudiantes que dedican' },
  { start: 968.163, end: 972.990, text: 'gran parte de su tiempo a cuidar a un familiar.' },
  { start: 973.239, end: 978.310, text: 'Un padre, pero también puede ser un hermano, un hijo con <font color="#FFFF00">discapacidad</font>, etc.' },
  { start: 982.801, end: 985.250, text: 'durante años, no se veía.' },
  { start: 985.390, end: 990.150, text: 'Está en torno al 13-15% en nuestros centros.' },
  { start: 992.509, end: 997.370, text: 'El número 5, la precariedad financiera, es objeto de muchos debates,' },
  { start: 997.510, end: 1000.310, text: 'y suele ser defendida por los sindicatos estudiantiles.' },
  { start: 1000.659, end: 1008.190, text: 'Dificultades para cuadrar el presupuesto, y tener que recurrir a' },
  { start: 1008.191, end: 1011.936, text: 'ayuda financiera, pero también alimentaria, como el banco de' },
  { start: 1011.937, end: 1014.510, text: 'alimentos que pueden tener en sus centros.' },
  { start: 1015.009, end: 1018.310, text: 'Esto representa hoy a 1 de cada 3 estudiantes' },
  { start: 1019.045, end: 1023.870, text: 'Y por último, el último, un estatus particular, el de Trabajador,' },
  { start: 1023.989, end: 1027.670, text: 'es decir con un verdadero Contrato de Trabajo, no alguien' },
  { start: 1027.671, end: 1029.985, text: 'que hace trabajos esporádicos de vez en cuando, y hay' },
  { start: 1029.986, end: 1033.810, text: 'condiciones para establecer que se trata de un Estudiante-Trabajador.' },
  { start: 1033.909, end: 1040.230, text: 'Se suele decir que ronda el 10-15%, para la formación en prácticas' },
  { start: 1040.231, end: 1043.770, text: 'es un estatus reconocido en la enseñanza (<font color="#FFFF00">FISA</font>, formación dual).' },
  { start: 1044.750, end: 1050.290, text: 'Y hay alrededor de un 10% de estudiantes que son trabajadores no a tiempo completo' },
  { start: 1050.489, end: 1052.990, text: 'pero que trabajan de forma regular,' },
  { start: 1052.991, end: 1055.970, text: 'más de 60 horas al mes' },
  { start: 1056.590, end: 1062.150, text: 'y por último, un 10% de estudiantes que trabajan de forma puntual.' },
  { start: 1062.324, end: 1063.790, text: 'Durante las vacaciones, los fines de semana,' },
  { start: 1068.610, end: 1069.610, text: 'y sobre todo las vacaciones de verano.' },
  { start: 1076.490, end: 1084.230, text: 'Existen disposiciones para ayudar a estos estudiantes' },
  { start: 1084.304, end: 1088.110, text: 'que tienen una <font color="#FFFF00">discapacidad</font>, aunque no se llame oficialmente discapacidad,' },
  { start: 1088.230, end: 1092.087, text: 'en todo caso, un obstáculo para su aprendizaje, así que' },
  { start: 1092.088, end: 1095.190, text: 'retomé estos 6 casos que acabo de presentar:' },
  { start: 1096.299, end: 1100.750, text: 'Estudiante-Padre, estudiante con <font color="#FFFF00">Discapacidad</font>, estudiantes con un problema de salud,' },
  { start: 1101.790, end: 1107.390, text: 'Estudiante-<font color="#FFFF00">Cuidador</font>, el estudiante en precariedad financiera u otra.' },
  { start: 1107.730, end: 1113.270, text: 'Y por último, Estudiante-Trabajador. Y he analizado lo que existe' },
  { start: 1113.294, end: 1117.650, text: 'hoy a nivel legal, disponible para estos estudiantes.' },
  { start: 1118.049, end: 1122.710, text: 'Con 3 casos que voy a describir en detalle, los casos "Prioritarios",' },
  { start: 1122.910, end: 1130.210, text: 'que es un <font color="#FFFF00">Régimen Especial de Estudios</font> (<font color="#FFFF00">RSE</font>), o en su defecto ...' },
  { start: 1130.211, end: 1134.330, text: 'condiciones adaptadas para la organización del trabajo.' },
  { start: 1136.339, end: 1142.530, text: 'Luego, voy a ver si hay <font color="#FFFF00">Exámenes Adaptados</font> disponibles para' },
  { start: 1142.531, end: 1147.810, text: 'estas personas, y por último, si existe un <font color="#FFFF00">Contrato de Formación</font>' },
  { start: 1149.090, end: 1153.668, text: 'o plan específico, para ayudar a estos estudiantes' },
  { start: 1153.669, end: 1159.570, text: 'a superar estos obstáculos de formación.' },
  { start: 1160.419, end: 1165.270, text: 'He añadido dos casillas que no voy a detallar, que son' },
  { start: 1165.271, end: 1170.290, text: 'Ayudas Financieras y Acceso Prioritario a la vivienda, que pueden' },
  { start: 1170.589, end: 1173.990, text: 'aplicarse a estos estudiantes.' },
  { start: 1174.299, end: 1178.510, text: 'Por ejemplo, la comida del CROUS a 1€ se aplica hoy a todos.' },
  { start: 1179.949, end: 1183.990, text: 'Empecemos por el Estudiante-Padre y su régimen especial.' },
  { start: 1184.449, end: 1190.570, text: 'Efectivamente hay derechos para estos estudiantes: horarios adaptados,' },
  { start: 1190.571, end: 1196.270, text: 'en todo caso opciones prioritarias para organizar su tiempo,' },
  { start: 1196.271, end: 1199.730, text: 'de manera que puedan conciliar su vida familiar y sus estudios.' },
  { start: 1200.170, end: 1202.570, text: 'Es la ley de la "Primera Infancia" la que prevalece en este caso.' },
  { start: 1202.749, end: 1205.250, text: 'Hay que poder cuidar de su hijo.' },
  { start: 1206.529, end: 1213.370, text: 'Si observamos al padre, también tiene la posibilidad de adaptar los Exámenes' },
  { start: 1213.419, end: 1218.990, text: 'con aplazamientos de pruebas o recuperaciones dedicadas cuando' },
  { start: 1219.304, end: 1221.855, text: 'sea necesario, pero por lo general,' },
  { start: 1221.856, end: 1224.810, text: 'estos estudiantes están bien organizados para ello.' },
  { start: 1225.490, end: 1228.610, text: 'En cambio, no hay reconocimiento de su estatus mediante un ...' },
  { start: 1228.611, end: 1231.930, text: 'Plan de Formación o un <font color="#FFFF00">Contrato de Formación</font> específico.' },
  { start: 1234.429, end: 1238.330, text: 'El caso del estudiante con <font color="#FFFF00">Discapacidad</font>, la 2ª columna, es mucho más conocido' },
  { start: 1239.170, end: 1245.710, text: 'Efectivamente cuenta con un (<font color="#FFFF00">RSE</font>) <font color="#FFFF00">Régimen Especial de Estudios</font>, que implica una adaptación' },
  { start: 1245.884, end: 1251.890, text: 'precisa de su horario, organizada por la comisión o por el <font color="#FFFF00">responsable de discapacidad</font>.' },
  { start: 1253.070, end: 1258.450, text: 'Y también cuenta con una <font color="#FFFF00">dispensa de asistencia</font> si es necesario.' },
  { start: 1260.890, end: 1266.010, text: 'Para los exámenes o controles, puede disponer, según su' },
  { start: 1266.159, end: 1268.650, text: 'situación y las recomendaciones de la comisión,' },
  { start: 1269.979, end: 1273.990, text: 'de <font color="#FFFF00">Tiempo Adicional</font>, de <font color="#FFFF00">Ayuda Humana</font>, de <font color="#FFFF00">material adaptado</font>. Cuidado, un' },
  { start: 1273.991, end: 1277.949, text: '<font color="#FFFF00">material adaptado</font> sirve para ayudarle en el marco' },
  { start: 1277.950, end: 1280.770, text: 'de su <font color="#FFFF00">discapacidad</font>, no para hacérselo más fácil.' },
  { start: 1281.369, end: 1287.230, text: 'Se trata de evitar que la <font color="#FFFF00">Discapacidad</font> se interponga en la comprensión del examen.' },
  { start: 1287.850, end: 1290.610, text: 'Y en algunos casos, también puede haber un cubículo aislado ...' },
  { start: 1291.429, end: 1293.010, text: '... o una sala aislada.' },
  { start: 1293.224, end: 1297.790, text: 'Todo esto está regido por un <font color="#FFFF00">Contrato de Formación</font>, que es un <font color="#FFFF00">Contrato Personalizado</font>' },
  { start: 1298.089, end: 1304.710, text: 'elaborado por la Comisión, o por el servicio, o por el' },
  { start: 1304.711, end: 1306.950, text: 'responsable de <font color="#FFFF00">Discapacidad</font>, y que es vinculante para el centro.' },
  { start: 1309.539, end: 1313.333, text: 'Para el 3er caso, 3ª columna, en el marco de una estudiante' },
  { start: 1313.334, end: 1317.090, text: 'o un estudiante con un problema de salud.' },
  { start: 1318.529, end: 1320.543, text: 'también cuenta con un (<font color="#FFFF00">RSE</font>) <font color="#FFFF00">Régimen Especial de Estudios</font> en los momentos en que tiene problemas' },
  { start: 1320.544, end: 1323.970, text: 'de salud, con dispensas' },
  { start: 1323.970, end: 1330.630, text: 'puntuales (para la persona con discapacidad era permanente)' },
  { start: 1330.631, end: 1332.530, text: 'de asistencia ...' },
  { start: 1332.990, end: 1339.130, text: 'si está justificado: hay que tener una cita,' },
  { start: 1339.131, end: 1342.650, text: 'cuidados médicos, no puede ser algo general.' },
  { start: 1342.749, end: 1345.810, text: 'Aquí, tiene que estar justificado.' },
  { start: 1346.119, end: 1349.790, text: 'En cuanto a los exámenes, es más o menos lo mismo que con la discapacidad,' },
  { start: 1349.850, end: 1354.110, text: 'con <font color="#FFFF00">Tiempo Adicional</font>, <font color="#FFFF00">Tiempo Extra</font> como en el caso de la' },
  { start: 1354.111, end: 1356.725, text: 'estudiante con <font color="#FFFF00">Discapacidad</font>, con una decisión del' },
  { start: 1356.726, end: 1359.270, text: 'tutor o, en todo caso, de un responsable Pedagógico.' },
  { start: 1361.339, end: 1364.590, text: 'Para el <font color="#FFFF00">Contrato de Formación</font>, es local, es con la universidad.' },
  { start: 1365.190, end: 1371.450, text: 'No hay ninguna exigencia particular, es un Protocolo de acuerdo de Salud' },
  { start: 1371.724, end: 1373.870, text: 'entre la Estudiante y la Universidad.' },
  { start: 1376.050, end: 1382.230, text: 'En el caso del <font color="#FFFF00">Cuidador</font>, la 4ª columna, pueden inscribirse en un grupo' },
  { start: 1382.231, end: 1384.570, text: 'o elegir un grupo especial de clases ...' },
  { start: 1384.571, end: 1387.630, text: 'para poder ajustar su Horario.' },
  { start: 1388.050, end: 1393.770, text: 'es para ayudarles y darles tiempo para desempeñar su papel de <font color="#FFFF00">Cuidador</font>.' },
  { start: 1394.350, end: 1396.999, text: 'También puede haber una Autorización Especial' },
  { start: 1397.000, end: 1399.790, text: 'de Ausencia, o en el caso de un examen.' },
  { start: 1400.439, end: 1405.770, text: 'Realmente hay que tener una buena razón, una justificación, para disponer' },
  { start: 1405.919, end: 1407.910, text: 'de una Autorización de Ausencia.' },
  { start: 1408.904, end: 1413.610, text: 'Por supuesto, si tienen una Autorización, tienen una recuperación personalizada.' },
  { start: 1415.050, end: 1420.190, text: 'Hasta la fecha no hay <font color="#FFFF00">Contrato de Formación</font> para los estudiantes <font color="#FFFF00">Cuidadores</font>,' },
  { start: 1420.191, end: 1423.990, text: 'que representan, como he dicho, del 12 al 15% de la población hoy.' },
  { start: 1426.629, end: 1432.130, text: 'No se ha previsto ninguna disposición para la columna nº 5, que es el caso de la' },
  { start: 1432.131, end: 1436.490, text: '<font color="#FFFF00">Precariedad</font>, ya sea Financiera, Digital, etc.' },
  { start: 1445.119, end: 1451.150, text: 'El último es el Estudiante-Trabajador, y por Estudiante-Trabajador entiendo...' },
  { start: 1451.274, end: 1454.210, text: 'un estudiante que tiene un <font color="#FFFF00">Contrato de Trabajo</font> con una empresa.' },
  { start: 1454.869, end: 1461.030, text: 'Puede ser un contrato temporal, indefinido, o cualquier otro Contrato de Proyecto.' },
  { start: 1461.031, end: 1465.590, text: 'Así que, en la enseñanza, a veces se habla de estos contratos, etc.' },
  { start: 1467.374, end: 1470.815, text: 'Esto no se refiere a contratos que sean bastante voluminosos,' },
  { start: 1470.816, end: 1473.230, text: 'no es un pequeño trabajo de una hora a la semana.' },
  { start: 1473.710, end: 1479.110, text: 'Aquí hablamos de un ajuste cuando la carga de trabajo del <font color="#FFFF00">Contrato de Trabajo</font>' },
  { start: 1479.559, end: 1485.770, text: 'es del orden de 60 horas al mes o 120 horas por trimestre' },
  { start: 1486.044, end: 1488.833, text: 'Así que, esta es la situación más favorable (60h/mes o 120h/trimestre)' },
  { start: 1488.834, end: 1490.970, text: 'que hay que tener en cuenta para el estudiante.' },
  { start: 1491.515, end: 1496.550, text: 'Y en ese caso, si el estudiante tiene un Contrato de Trabajo de 60 h/mes,' },
  { start: 1496.950, end: 1498.190, text: 'o de 120 h/trimestre' },
  { start: 1499.204, end: 1502.731, text: 'El Horario debe ser ajustado, de forma obligatoria,' },
  { start: 1502.781, end: 1504.890, text: 'el Trabajo prevalece sobre la Enseñanza' },
  { start: 1507.559, end: 1512.350, text: 'Si esto afecta a los exámenes o a los controles de conocimientos,' },
  { start: 1512.899, end: 1516.390, text: 'puede haber dispensas en ciertas evaluaciones continuas' },
  { start: 1517.590, end: 1521.170, text: 'Y también, por supuesto, pruebas adaptadas, por ejemplo a distancia,' },
  { start: 1521.329, end: 1522.730, text: 'si es necesario.' },
  { start: 1525.280, end: 1530.210, text: 'En cuanto al estatus de Estudiante-Trabajador, existe un contrato' },
  { start: 1530.434, end: 1534.210, text: 'específico, <font color="#FFFF00">FISA</font> (Formación Inicial en régimen de Aprendiz), que es el <font color="#FFFF00">Contrato de Aprendizaje</font>' },
  { start: 1534.419, end: 1536.350, text: 'Los demás no están afectados ...' },
  { start: 1536.590, end: 1542.910, text: 'es decir, los contratos temporales e indefinidos no están cubiertos por un Plan' },
  { start: 1542.911, end: 1547.110, text: 'o un <font color="#FFFF00">Contrato de Formación</font> Específico, esto solo se aplica al Aprendizaje,' },
  { start: 1547.369, end: 1549.290, text: 'en Francia, y a nadie más.' },
  { start: 1551.740, end: 1557.880, text: 'Ayudas Financieras ... Acceso Prioritario ..., les dejo leer lo que existe.' },
  { start: 1557.880, end: 1563.822, text: 'Existen muchas disposiciones que hay que conocer para' },
  { start: 1563.823, end: 1567.060, text: 'ayudar a los estudiantes cuando lo necesitan.' },
  { start: 1572.109, end: 1578.650, text: 'Vamos a centrarnos en el caso del estudiante con <font color="#FFFF00">Discapacidad</font>, porque detrás de la discapacidad,' },
  { start: 1578.885, end: 1582.050, text: 'o al menos de la adaptación, hay un protocolo estricto.' },
  { start: 1582.294, end: 1586.790, text: 'Hay que aplicarlo, en todo caso, para evitar los litigios jurídicos que cada vez surgen más,' },
  { start: 1586.791, end: 1589.750, text: 'sobre todo en las escuelas privadas.' },
  { start: 1589.870, end: 1590.962, text: 'En las escuelas públicas hay un poco menos ...' },
  { start: 1590.963, end: 1593.590, text: 'pero en las escuelas privadas, se ven aparecer' },
  { start: 1594.729, end: 1600.170, text: 'Esta organización está descrita en las Leyes y los Códigos de Educación,' },
  { start: 1600.550, end: 1603.771, text: 'prevé una cadena de decisiones que' },
  { start: 1603.772, end: 1606.890, text: 'parte del estudiante, que debe declararse.' },
  { start: 1607.274, end: 1611.870, text: 'no se puede hacer nada sin la declaración del estudiante, y su puesta en práctica' },
  { start: 1612.230, end: 1613.230, text: 'por el profesor.' },
  { start: 1614.150, end: 1618.050, text: 'No hay aplicación directa, está estrictamente prohibida.' },
  { start: 1618.104, end: 1620.135, text: 'Un estudiante que va a ver a un profesor y le dice' },
  { start: 1620.215, end: 1621.950, text: '"bueno, tengo tal problema ...' },
  { start: 1622.299, end: 1626.350, text: '¡por favor adapte mi examen!" ...eso suele pasar justo en el momento de los exámenes' },
  { start: 1628.169, end: 1634.250, text: 'Eso no es posible. El profesor no está en condiciones' },
  { start: 1634.251, end: 1637.986, text: 'de juzgar, no es médico, no está formado' },
  { start: 1637.987, end: 1640.370, text: 'específicamente para reconocer una <font color="#FFFF00">discapacidad</font>.' },
  { start: 1640.774, end: 1642.510, text: 'No tiene que hacerlo.' },
  { start: 1643.249, end: 1646.430, text: 'Y si lo hace, puede haber un litigio con otro estudiante,' },
  { start: 1647.414, end: 1651.250, text: 'porque este puede decir, <i>"A él lo favorecieron y a mí no, porque</i>' },
  { start: 1651.251, end: 1653.965, text: '<i>dijo tal cosa, y yo estoy en desventaja</i>' },
  { start: 1653.966, end: 1656.170, text: '<i>porque no tuve <font color="#FFFF00">Tiempo Adicional</font>"</i>, etc.' },
  { start: 1656.909, end: 1662.150, text: 'Hay que ser realmente serios y rechazar este tipo de gestiones, ¡en cualquier caso!' },
  { start: 1662.151, end: 1668.450, text: 'el profesor no tiene que adaptar su clase a la petición del estudiante.' },
  { start: 1669.230, end: 1675.950, text: 'El estudiante debe informar de la situación a un Servicio, a un Departamento o a un' },
  { start: 1676.099, end: 1680.670, text: 'Referente de <font color="#FFFF00">Discapacidad</font> (obligatorio en los centros), que estudiará la situación.' },
  { start: 1681.979, end: 1686.970, text: 'Si necesita ayuda, puede recurrir al médico designado por la ...' },
  { start: 1686.971, end: 1693.650, text: '<font color="#FFFF00">Comisión de Derechos y Autonomía de las Personas con Discapacidad (CDAPH)</font>' },
  { start: 1694.349, end: 1697.730, text: 'que se encuentra en la oficina departamental de personas con <font color="#FFFF00">Discapacidad</font>' },
  { start: 1697.731, end: 1701.910, text: 'y que le ayudará a hacer un diagnóstico de la situación.' },
  { start: 1703.559, end: 1710.610, text: 'Una vez establecido el vínculo entre el estudiante y el referente, y' },
  { start: 1710.859, end: 1716.010, text: 'una vez que efectivamente se constata una <font color="#FFFF00">discapacidad</font>, y no un' },
  { start: 1716.011, end: 1721.570, text: 'defecto lingüístico, o un problema de dominio del idioma francés,' },
  { start: 1722.390, end: 1728.510, text: 'se empezará a elaborar un informe que evalúe todas las necesidades según' },
  { start: 1728.511, end: 1733.190, text: 'la ley, que son la Organización, el Desarrollo de las clases' },
  { start: 1733.264, end: 1736.459, text: 'y el Acompañamiento. No hay, a priori, a nivel' },
  { start: 1736.460, end: 1740.210, text: 'legal, un capítulo específico sobre los controles.' },
  { start: 1741.759, end: 1746.077, text: 'Sobre estos 3 capítulos, Organización-Desarrollo-' },
  { start: 1746.078, end: 1748.770, text: 'Acompañamiento, no se necesita opinión médica.' },
  { start: 1749.350, end: 1754.970, text: 'Aquí, es el responsable Pedagógico, o el referente de <font color="#FFFF00">Discapacidad</font>, quienes son' },
  { start: 1754.971, end: 1759.210, text: 'los responsables de este plan de Acompañamiento.' },
  { start: 1760.259, end: 1763.510, text: 'En cambio, en algunos casos, si nunca se ha hecho.' },
  { start: 1763.970, end: 1767.274, text: 'Hay que saber que la <font color="#FFFF00">adaptación de los exámenes</font>' },
  { start: 1767.275, end: 1770.670, text: 'puede requerir un <u>informe obligatorio de un médico.</u>' },
  { start: 1778.111, end: 1782.210, text: 'por ejemplo, o en otros casos de <font color="#FFFF00">discapacidad invisible</font>, es bien sabido,' },
  { start: 1783.330, end: 1787.830, text: 'Pero es un médico quien lo declarará, quien lo pedirá.' },
  { start: 1787.831, end: 1789.870, text: 'En todo caso, se necesita un informe médico.' },
  { start: 1790.184, end: 1792.830, text: 'No se puede dar de otra manera.' },
  { start: 1794.250, end: 1799.270, text: 'Una vez realizada la evaluación de necesidades, se aplica al centro,' },
  { start: 1799.271, end: 1803.750, text: 'y le corresponde al centro, (que tiene la autoridad jerárquica)' },
  { start: 1803.751, end: 1808.710, text: 'hacerlo cumplir a todos y, en particular, a los profesores, que van a' },
  { start: 1808.711, end: 1815.110, text: 'tener a la persona, al estudiante o a la estudiante, en su clase, durante la' },
  { start: 1815.334, end: 1818.790, text: 'formación, o durante el control de conocimientos.' },
  { start: 1824.939, end: 1828.260, text: 'Dije que el profesor no está en condiciones de evaluar...' },
  { start: 1828.300, end: 1834.160, text: '... la necesidad y, en todo caso, de dar un informe médico sobre la persona.' },
  { start: 1835.280, end: 1837.460, text: 'Es cierto, pero eso no impide la formación.' },
  { start: 1837.634, end: 1839.818, text: 'No solo no la impide, sino que' },
  { start: 1839.819, end: 1843.400, text: 'debo precisar que esta formación es <u>Obligatoria.</u>' },
  { start: 1843.699, end: 1848.340, text: 'Eso significa que entra dentro del ámbito de las <u>Formaciones Obligatorias</u> que debe' },
  { start: 1848.341, end: 1853.400, text: 'dar un empleador a su empleado, como por ejemplo las Formaciones de Seguridad.' },
  { start: 1855.064, end: 1859.700, text: 'Así que esta formación es obligatoria, se introdujo desde el principio en ...' },
  { start: 1859.701, end: 1863.140, text: '... la ley de 2005 y luego se confirmó en' },
  { start: 1863.141, end: 1867.300, text: 'diferentes leyes, la última del 15 de noviembre de 2014.' },
  { start: 1867.849, end: 1871.280, text: 'Llamada la ley de la "Escuela de la Confianza", que es un poco más amplia,' },
  { start: 1871.614, end: 1873.300, text: 'y mucho más <font color="#FFFF00">inclusiva</font>.' },
  { start: 1874.135, end: 1878.180, text: 'Dice que los profesores, pero también todo el personal de gestión ...' },
  { start: 1878.354, end: 1883.260, text: 'técnico, de servicio, etc, y de recepción, deben recibir, durante su formación,' },
  { start: 1883.260, end: 1888.500, text: 'si es una formación inicial, por ejemplo para los profesores, pero también durante' },
  { start: 1888.501, end: 1891.240, text: 'el desempeño de su trabajo,' },
  { start: 1891.475, end: 1892.475, text: 'como parte de la <font color="#FFFF00">Formación Continua</font>,' },
  { start: 1892.774, end: 1896.660, text: 'una formación específica sobre la acogida/educación de los alumnos y' },
  { start: 1896.661, end: 1901.200, text: 'estudiantes en situación de <font color="#FFFF00">discapacidad</font>, y no sé por qué esta frase...' },
  { start: 1901.420, end: 1902.420, text: 'está ahí, pero lo está.' },
  { start: 1902.780, end: 1906.560, text: '"<i>En particular, o especialmente aquellos que presentan un</i>' },
  { start: 1906.561, end: 1910.240, text: 'trastorno de conducta o un <i><font color="#FFFF00">trastorno del neurodesarrollo</font>.</i>' },
  { start: 1911.669, end: 1914.980, text: 'Una pequeña frase de paso, en el caso del Aprendizaje,' },
  { start: 1915.894, end: 1920.100, text: 'y pienso en los estudiantes de FP que suelen estar en el laboratorio o en la práctica,' },
  { start: 1921.180, end: 1924.400, text: 'la <font color="#FFFF00">inclusión</font> no solo concierne a la <font color="#FFFF00">accesibilidad</font> de' },
  { start: 1924.974, end: 1927.580, text: 'las aulas, sino que concierne a todo el laboratorio,' },
  { start: 1927.620, end: 1929.540, text: 'el ritmo de la alternancia, la empresa.' },
  { start: 1930.980, end: 1938.400, text: 'Y hay que ser preciso, en particular en cuanto a las prácticas de seguridad y salud.' },
  { start: 1944.344, end: 1947.840, text: 'En consecuencia, y para cerrar' },
  { start: 1947.841, end: 1952.000, text: 'este capítulo sobre las constataciones, les presento una lista no exhaustiva' },
  { start: 1952.460, end: 1957.860, text: 'de formaciones que se pueden aplicar.' },
  { start: 1958.160, end: 1963.440, text: 'así que, formaciones obligatorias, que se pueden aplicar a todo el' },
  { start: 1963.441, end: 1967.300, text: 'personal, de gestión, de recepción, y de acompañamiento.' },
  { start: 1968.674, end: 1973.318, text: 'La primera es muy conocida, es la formación "<font color="#FFFF00">Cap Ecole Inclusive</font>" (Escuela Inclusiva)' },
  { start: 1973.319, end: 1976.460, text: 'que se ha desarrollado desde hace varios años.' },
  { start: 1976.554, end: 1981.400, text: 'no solo hay formación, sino también recursos pedagógicos' },
  { start: 1981.401, end: 1984.516, text: 'es toda una plataforma que se ha desarrollado' },
  { start: 1984.517, end: 1987.340, text: 'en torno a los elementos de "Confianza".' },
  { start: 1988.990, end: 1993.760, text: 'Así que, es más que la <font color="#FFFF00">Discapacidad</font>, es la <font color="#FFFF00">Inclusividad</font>' },
  { start: 1994.320, end: 1995.700, text: 'en general.' },
  { start: 1997.859, end: 2002.260, text: 'Para "Paralysés de France", es una asociación.' },
  { start: 2003.259, end: 2008.380, text: 'También hay una formación sobre la cuestión de <font color="#FFFF00">accesibilidad</font>, la <font color="#FFFF00">inclusión</font>,' },
  { start: 2008.585, end: 2013.580, text: 'se trata sobre todo de personas con <font color="#FFFF00">discapacidad motora</font>, a quienes atiende esta asociación.' },
  { start: 2014.154, end: 2016.440, text: 'Intervienen en el lugar, pueden intervenir' },
  { start: 2016.519, end: 2021.480, text: 'en su centro y ante la administración general.' },
  { start: 2023.769, end: 2030.140, text: 'El 3º es un MOOC, bastante original, realizado por la AFPA,' },
  { start: 2030.141, end: 2034.100, text: 'llamado "<font color="#FFFF00">Discapacidad</font>, claves de acción hacia el empleo"' },
  { start: 2034.734, end: 2039.740, text: 'Está, de manera general, bien estructurado, sobre el tema de la <font color="#FFFF00">discapacidad</font>' },
  { start: 2040.699, end: 2044.100, text: 'para la <font color="#FFFF00">inclusión</font>, en la formación y en el empleo.' },
  { start: 2044.101, end: 2050.060, text: 'Así que, muy amplio, es una formación a distancia reconocida, y que ganó' },
  { start: 2050.385, end: 2055.300, text: 'el premio "Open Educaton Night 2023"' },
  { start: 2055.380, end: 2056.388, text: 'No hay ninguna falta de ortografía' },
  { start: 2056.389, end: 2060.239, text: 'Efectivamente se escribe "EduCaton" así' },
  { start: 2060.739, end: 2064.300, text: 'En su defecto, si no saben cuál elegir, pueden hacer esta' },
  { start: 2064.301, end: 2068.159, text: 'y notificar que las personas han completado este MOOC.' },
  { start: 2071.110, end: 2077.159, text: 'El 4º son las plataformas o todas las formaciones que ofrece la Unión' },
  { start: 2077.360, end: 2082.159, text: 'Nacional de Familiares y Amigos de <font color="#FFFF00">Personas con Enfermedad Mental y/o Discapacidad Psíquica</font>' },
  { start: 2083.280, end: 2089.290, text: 'Esto no está orientado a las personas con discapacidad, es para los profesionales.' },
  { start: 2092.290, end: 2096.590, text: 'Si nos centramos en los <font color="#FFFF00">DYS</font>, está la Federación Francesa de <font color="#FFFF00">DYS</font>,' },
  { start: 2096.770, end: 2100.920, text: 'que ofrece formaciones en los 6 ámbitos' },
  { start: 2100.921, end: 2104.370, text: 'de los <font color="#FFFF00">trastornos cognitivos</font> del <font color="#FFFF00">DYS</font>, para la educación' },
  { start: 2104.495, end: 2110.090, text: 'superior y para el ámbito profesional, muy bien.' },
  { start: 2110.370, end: 2113.170, text: 'Un poco caro para mi gusto, pero de gran calidad.' },
  { start: 2114.230, end: 2120.410, text: 'Por último, no olvidemos que también se puede uno formar en otras materias, otros' },
  { start: 2120.411, end: 2124.610, text: 'idiomas, y en particular en la <font color="#FFFF00">lengua de signos francesa</font>.' },
  { start: 2125.740, end: 2128.930, text: 'hay asociaciones y una plataforma de formación en línea' },
  { start: 2129.750, end: 2137.250, text: 'llamada "Signes de Sens", que permite aprender la lengua de' },
  { start: 2137.251, end: 2139.909, text: 'signos, perdón, para la <font color="#FFFF00">inclusión</font> de las personas con discapacidad auditiva, en todo caso de las personas que tienen problemas de audición.' },


  { start: 2139.910, end: 2144.000, text: 'Gracias por su atención. Vaya al capítulo 2.' },
];

const SUBTITLES_IT_CH1 = [
{ start: 1.000, end: 12.120, text: 'Benvenuti nel programma BRIDGE -<font color="#FFFF00"> Bridging Research and Inclusive Digital Education</font>' },
  { start: 12.130, end: 19.630, text: 'Ora affronteremo la conferenza di oggi, che riguarda il tema' },
  { start: 19.631, end: 23.830, text: 'dell\'integrazione delle persone con <font color="#FFFF00">disabilità</font>' },
  { start: 24.220, end: 27.170, text: 'o comunque che hanno blocchi durante l\'insegnamento.' },
  { start: 27.350, end: 31.570, text: 'Ci sarà una forte connotazione "<font color="#FFFF00">Disabilità</font>" in questa presentazione.' },
  { start: 32.155, end: 36.750, text: 'Ma si tratta essenzialmente di "<font color="#FFFF00">Insegnamento Inclusivo</font>"' },
  { start: 37.295, end: 40.530, text: 'Cominceremo con un primo capitolo di osservazioni,' },
  { start: 40.531, end: 45.630, text: 'il volume, chi sono le persone interessate da questa conferenza.' },
  { start: 63.885, end: 66.527, text: 'Questo è uno sguardo al volume relativo' },
  { start: 66.577, end: 69.160, text: 'alle studentesse e agli studenti con <font color="#FFFF00">disabilità</font>.' },
  { start: 70.019, end: 73.571, text: 'In realtà, per semplificare, questo rappresenta' },
  { start: 73.572, end: 77.020, text: 'il 3% della popolazione studentesca in Francia.' },
  { start: 77.720, end: 84.740, text: 'Quindi oggi siamo intorno, per riconoscimento ufficiale, a 60.000 studenti.' },
  { start: 85.139, end: 89.080, text: 'Questi numeri sono fuorvianti e, in particolare, non sono rappresentativi' },
  { start: 89.081, end: 92.180, text: 'dell\'intera gamma di <font color="#FFFF00">disabilità</font> che si possono incontrare.' },
  { start: 92.720, end: 97.540, text: 'In ogni caso, rappresentativi della popolazione che abbiamo in classe.' },
  { start: 98.740, end: 106.540, text: 'Di questo 3%, il 70% sono <font color="#FFFF00">disabilità invisibili</font>,' },
  { start: 106.949, end: 110.640, text: 'in ogni caso, molto difficili da individuare a prima vista,' },
  { start: 111.039, end: 116.040, text: 'perché possono riguardare <font color="#FFFF00">disturbi psichici</font>, malattie' },
  { start: 116.040, end: 121.700, text: 'invalidanti, <font color="#FFFF00">disturbi cognitivi</font>, con il <font color="#FFFF00">DSA</font> come il più noto,' },
  { start: 122.680, end: 127.960, text: 'o forme di <font color="#FFFF00">autismo</font>, perfettamente in grado di seguire l\'insegnamento.' },
  { start: 128.900, end: 131.940, text: 'Quindi, autismo di base. Qui siamo intorno al 5%.' },
  { start: 134.810, end: 137.864, text: 'Le <font color="#FFFF00">disabilità invisibili</font> riguardano anche' },
  { start: 137.865, end: 141.800, text: 'i <font color="#FFFF00">disturbi del linguaggio</font>, intorno al 22%.' },
  { start: 141.801, end: 149.680, text: 'I <font color="#FFFF00">disturbi cognitivi</font> (a destra e in basso) sono intorno al 6%.' },
  { start: 150.255, end: 156.020, text: 'Invece, 1 studente <font color="#FFFF00">disabile</font> su 3 ha' },
  { start: 156.021, end: 160.700, text: 'disturbi <font color="#FFFF00">visibili</font>, cioè <font color="#FFFF00">disturbi motori</font>, <font color="#FFFF00">disturbi visivi</font> (problemi di vista...' },
  { start: 160.701, end: 165.740, text: 'fino alla cecità totale), e <font color="#FFFF00">problemi uditivi</font>, fino alla sordità totale.' },
  { start: 165.984, end: 170.780, text: 'Qui, la maggior parte delle disabilità visibili riguarda' },
  { start: 170.781, end: 174.680, text: '<font color="#FFFF00">disturbi motori</font> (intorno al 10%).' },
  { start: 176.280, end: 179.141, text: 'Come potete vedere,' },
  { start: 179.142, end: 181.660, text: '2/3 non sono visibili, 1/3 sono visibili.' },
  { start: 182.380, end: 188.420, text: 'Se guardiamo la ripartizione di questi studenti in difficoltà,' },
  { start: 188.421, end: 195.300, text: 'nell\'istruzione superiore, vediamo che sono concentrati soprattutto' },
  { start: 195.301, end: 199.527, text: 'nelle università, che "catturano" o accolgono comunque' },
  { start: 199.528, end: 203.880, text: 'almeno 8 studenti <font color="#FFFF00">disabili</font> su 10.' },
  { start: 204.560, end: 209.620, text: 'Poi, vediamo che il secondo livello sono gli istituti privati' },
  { start: 209.621, end: 214.140, text: 'di interesse generale, chiamati comunemente "EESPIG", gli' },
  { start: 214.141, end: 219.040, text: 'Istituti di Istruzione Superiore Privati di Interesse Generale, che,' },
  { start: 219.041, end: 223.340, text: 'oggi, hanno numeri più alti, intorno all\'8-10%.' },
  { start: 223.440, end: 229.260, text: 'I numeri che vi presento qui, a destra, a sinistra, e,' },
  { start: 229.435, end: 232.420, text: 'in realtà, sono vecchi, del 2024' },
  { start: 234.000, end: 240.120, text: 'Per quanto riguarda le classi prepa e i licei della scuola pubblica,' },
  { start: 240.554, end: 244.680, text: 'siamo intorno al 4-5% di studenti <font color="#FFFF00">disabili</font>.' },
  { start: 245.040, end: 247.803, text: 'E poi, nelle altre scuole pubbliche,' },
  { start: 247.804, end: 251.640, text: 'al di fuori dell\'università, siamo intorno al 3-4%.' },
  { start: 252.340, end: 258.279, text: 'Quindi, per semplificare, vediamo che una piccola parte della <font color="#FFFF00">disabilità</font>' },
  { start: 258.380, end: 263.300, text: 'e comunque, vediamo solo l\'1% delle persone con <font color="#FFFF00">disabilità</font>.' },
  { start: 264.085, end: 268.840, text: 'Ciò che è notevole, (quello che ho annotato al centro del riquadro a destra)' },
  { start: 268.841, end: 272.520, text: 'è che se guardiamo i settori scientifici,' },
  { start: 273.120, end: 277.280, text: 'ebbene, c\'è solo il 29%, circa un terzo, delle' },
  { start: 277.281, end: 279.480, text: 'persone <font color="#FFFF00">disabili</font> che si orientano verso settori scientifici.' },
  { start: 280.740, end: 286.500, text: 'È quindi del tutto legittimo che un insegnante, un professore,' },
  { start: 287.125, end: 288.125, text: 'vi dica' },
  { start: 288.185, end: 290.860, text: '"Scusa, ma non ho nessuno studente <font color="#FFFF00">disabile</font> nella mia classe".' },
  { start: 291.600, end: 294.840, text: 'O davvero non ce ne sono, perché la popolazione è piuttosto ridotta ..' },
  { start: 295.480, end: 301.140, text: 'oppure ce ne sono, ma non sarà visibile se non gli viene detto.' },
  { start: 305.460, end: 309.440, text: 'Quindi, questi numeri contrastano con l\'impressione che si può avere' },
  { start: 309.441, end: 313.400, text: 'guardando la popolazione di studentesse e studenti' },
  { start: 313.540, end: 314.620, text: 'che abbiamo nelle aule.' },
  { start: 315.420, end: 321.000, text: 'E in particolare sulla questione dei <font color="#FFFF00">DSA</font>, che sono ...' },
  { start: 321.195, end: 325.140, text: 'i problemi, le <font color="#FFFF00">disabilità</font>, legate a un <font color="#FFFF00">disturbo cognitivo</font> persistente.' },
  { start: 326.000, end: 333.040, text: 'Ricordo che il <font color="#FFFF00">DSA</font> è "medico", e non ha alcuna relazione con la categoria' },
  { start: 333.041, end: 336.132, text: 'socio-professionale dei genitori né dello studente,' },
  { start: 336.133, end: 338.860, text: 'quindi è totalmente indipendente dall\'ambiente sociale.' },
  { start: 339.645, end: 341.777, text: 'e anche dall\'origine linguistica, il <font color="#FFFF00">DSA</font> compare ...' },
  { start: 341.778, end: 344.660, text: 'in tutte le popolazioni di tutto il mondo.' },
  { start: 346.025, end: 350.800, text: 'Sulla popolazione, mostravo numeri intorno al 7%,' },
  { start: 351.410, end: 352.864, text: 'è circa quello che abbiamo.' },
  { start: 352.865, end: 357.820, text: 'E se guardiamo le forme più gravi di <font color="#FFFF00">DSA</font>, è intorno al 3-5%.' },
  { start: 359.360, end: 363.140, text: 'Il riconoscimento del <font color="#FFFF00">DSA</font> avviene in modo molto chiaro' },
  { start: 363.640, end: 369.680, text: 'È la differenza, è il gap, che si può constatare tra il comportamento' },
  { start: 369.855, end: 375.520, text: 'orale e relazionale di uno studente che comprende totalmente la lezione orale,' },
  { start: 375.870, end: 380.880, text: 'che ha un vocabolario ricco, che ha un\'eccellente comprensione dei concetti,' },
  { start: 381.305, end: 385.480, text: 'e anche se sono complessi, può avere qualche situazione,' },
  { start: 386.140, end: 387.399, text: 'qualche inversione ogni tanto.' },
  { start: 387.400, end: 389.360, text: 'ma resta comunque minore.' },
  { start: 389.575, end: 392.931, text: 'Invece, quando si passa allo scritto e in particolare' },
  { start: 392.932, end: 396.420, text: 'quando deve comprendere un enunciato o scriverlo...' },
  { start: 396.920, end: 403.220, text: 'Ebbene, la <font color="#FFFF00">disabilità</font> si rivela con errori ortografici' },
  { start: 403.221, end: 407.320, text: 'ma è un effetto indotto, un effetto della <font color="#FFFF00">dislessia</font>' },
  { start: 407.445, end: 410.320, text: 'ma ci sono anche fusioni, lentezza, inversioni di parole.' },
  { start: 411.830, end: 415.740, text: 'E questo rende per loro le fonti difficili, comunque c\'è una vera' },
  { start: 415.741, end: 418.940, text: 'fatica cognitiva legata a questa difficoltà con lo scritto.' },
  { start: 419.460, end: 425.080, text: 'Quindi, è questo il gap, tra quello che si vede della persona e la sua resa scritta,' },
  { start: 425.360, end: 430.760, text: 'che è una caratteristica del <font color="#FFFF00">DSA</font>. Questa caratteristica ha una soluzione,' },
  { start: 431.585, end: 434.820, text: '"medica", anche se il termine non è del tutto appropriato.' },
  { start: 435.455, end: 438.045, text: 'La prima cosa, ed è vero che è stata efficace,' },
  { start: 438.046, end: 440.300, text: 'è evitare tutto ciò che provoca affaticamento' },
  { start: 440.450, end: 444.040, text: 'la "<font color="#FFFF00">Fatica Cognitiva</font>", in parole semplici, significa dare più tempo.' },
  { start: 444.820, end: 447.799, text: 'E poi alcune valutazioni logopediche in particolare' },
  { start: 447.800, end: 450.800, text: 'sono piuttosto efficaci nel correggere questo genere di cose.' },
  { start: 452.260, end: 455.290, text: 'E poi, abbiamo una popolazione di studentesse e studenti' },
  { start: 455.291, end: 458.200, text: 'che sembrerebbero avere lo stesso problema, in particolare nello scritto' },
  { start: 459.870, end: 463.000, text: 'Ma se si osserva bene, anche l\'orale è un problema.' },
  { start: 463.785, end: 466.720, text: 'È in realtà un deficit di apprendimento della lingua.' },
  { start: 467.020, end: 469.896, text: 'E rispetto ai casi di <font color="#FFFF00">DSA</font> che abbiamo visto' },
  { start: 469.897, end: 472.320, text: 'qui nella tabella e nella colonna di sinistra.' },
  { start: 473.020, end: 475.720, text: 'Qui, si tratta di soluzioni durature.' },
  { start: 476.450, end: 481.320, text: 'Cioè, il problema scomparirà nel tempo, con' },
  { start: 481.545, end: 487.100, text: 'la pratica, un\'esposizione regolare alla lingua, alla cultura,' },
  { start: 487.101, end: 490.840, text: 'ma anche estremamente diversificate nella forma.' },
  { start: 491.825, end: 494.405, text: 'E possiamo citare, ad esempio, i corsi di <font color="#FFFF00">FLE</font> (francese lingua straniera) che' },
  { start: 494.406, end: 498.140, text: 'esistono oggi in tutti gli istituti, e che aiutano molto' },
  { start: 498.141, end: 502.040, text: 'È un supporto logistico da mettere in atto, che permette una' },
  { start: 502.041, end: 505.920, text: 'progressione rapida e definitiva, e non è affatto "medica".' },
  { start: 506.840, end: 511.860, text: 'D\'altra parte, è vero che la popolazione interessata è importante,' },
  { start: 511.861, end: 516.500, text: 'oggi si stima che le forme di "<font color="#FFFF00">analfabetismo funzionale</font>", cioè l\'incapacità di' },
  { start: 516.501, end: 522.919, text: 'scrivere o comprendere un testo, riguardino circa il 7% della popolazione tra gli 8 e i 65 anni' },
  { start: 522.920, end: 527.340, text: 'questi sono i dati nazionali, e se guardiamo agli studenti,' },
  { start: 527.520, end: 532.140, text: 'un indicatore è quello dei nuovi immatricolati dopo il diploma,' },
  { start: 532.989, end: 535.720, text: 'si arriva a una popolazione del 10-15%.' },
  { start: 536.419, end: 540.820, text: 'Qui abbiamo una vera difficoltà, poiché questi studenti hanno' },
  { start: 540.845, end: 545.560, text: 'un vocabolario limitato nell\'orale e nello scritto, e anche difficoltà di' },
  { start: 547.504, end: 554.380, text: 'comprensione, ma non si tratta di <font color="#FFFF00">DSA</font>. Il <font color="#FFFF00">DSA</font> ha un sostegno "legale",' },
  { start: 554.500, end: 561.060, text: 'per aiutare, comunque per rimuovere la barriera della <font color="#FFFF00">disabilità</font>,' },
  { start: 561.209, end: 564.980, text: 'mentre nell\'altro caso non c\'è alcuna disposizione legale.' },
  { start: 572.809, end: 576.940, text: 'Possiamo estendere questo ragionamento, appena applicato ai' },
  { start: 577.039, end: 581.200, text: '<font color="#FFFF00">DSA</font>, alle persone con difficoltà di acquisizione della lingua francese,' },
  { start: 581.729, end: 587.820, text: 'ad altri tipi di <font color="#FFFF00">disabilità</font>, o comunque, se non è una' },
  { start: 587.821, end: 591.840, text: '<font color="#FFFF00">disabilità</font>, sono chiaramente ostacoli all\'apprendimento.' },
  { start: 594.099, end: 597.380, text: 'Lo rappresento come una cipolla, con strati successivi.' },
  { start: 598.380, end: 601.820, text: 'Il nucleo, di cui non abbiamo parlato, sono le <font color="#FFFF00">disabilità</font> che saranno note,' },
  { start: 601.900, end: 607.120, text: 'con 1/3 visibile e 2/3 non visibile,' },
  { start: 607.260, end: 608.139, text: 'ma dichiarate.' },
  { start: 608.140, end: 612.380, text: 'E il numero che ho indicato prima, intorno a 60, 70 mila,' },
  { start: 612.554, end: 615.920, text: '64.000 qui, è abbastanza chiaro.' },
  { start: 616.380, end: 621.060, text: 'Ma dietro, ci sono ancora <font color="#FFFF00">disabilità invisibili</font> non dichiarate.' },
  { start: 622.339, end: 627.380, text: 'Quindi troviamo l\'<font color="#FFFF00">Autismo</font>, malattie croniche per tutta la vita,' },
  { start: 627.555, end: 630.580, text: 'che possono rientrare nella questione della <font color="#FFFF00">disabilità</font>, i <font color="#FFFF00">DSA</font>, ecc.' },
  { start: 634.600, end: 640.880, text: 'Ma dietro tutto questo, possono esserci condizioni di salute che mettono lo studente in una' },
  { start: 640.881, end: 643.800, text: 'situazione difficile per il suo apprendimento.' },
  { start: 644.549, end: 649.900, text: 'È il dolore o le <font color="#FFFF00">malattie invalidanti</font>, i tumori,' },
  { start: 650.100, end: 654.860, text: 'abbiamo studenti in cura, che sono stanchi, che hanno problemi' },
  { start: 654.861, end: 658.321, text: 'di sonno, e questo può anche significare che hanno bisogno' },
  { start: 658.322, end: 661.500, text: 'di tempo per potersi cambiare.' },
  { start: 662.099, end: 666.520, text: 'problemi di incontinenza legati a un intervento chirurgico, per esempio,' },
  { start: 666.720, end: 671.418, text: 'o dover iniettarsi una terapia,' },
  { start: 671.419, end: 675.520, text: 'spesso si dimentica il caso dei diabetici.' },
  { start: 675.944, end: 681.580, text: 'In ogni caso, abbiamo una popolazione di studenti con salute precaria,' },
  { start: 681.800, end: 688.900, text: 'sia in modo occasionale, sia cronica e di breve durata,' },
  { start: 688.901, end: 692.660, text: 'sia per tutta la durata degli studi.' },
  { start: 694.015, end: 696.696, text: 'Oltre alla salute, è anche bene' },
  { start: 696.697, end: 699.120, text: 'integrare le questioni legate alla psicologia.' },
  { start: 700.319, end: 705.720, text: 'Lo sappiamo dall\'arrivo del COVID, ci sono altri problemi, ostacoli,' },
  { start: 706.029, end: 711.200, text: 'all\'insegnamento, che sono lo stress e l\'ansia, le angosce, le situazioni di' },
  { start: 711.201, end: 717.600, text: 'disagio, e soprattutto ciò che non va trascurato per gli studenti che hanno' },
  { start: 717.601, end: 722.100, text: 'lasciato i genitori per un\'altra regione, questioni legate all\'isolamento.' },
  { start: 724.149, end: 730.100, text: 'Oggi possiamo considerare che questo riguarda 1 studente su 3.' },
  { start: 731.185, end: 736.260, text: 'E infine l\'ultimo, da non trascurare perché rappresenta molti' },
  { start: 736.261, end: 740.000, text: 'studenti, sono incidenti occasionali ...' },
  { start: 740.001, end: 744.860, text: 'o duraturi nella vita personale dello studente.' },
  { start: 745.939, end: 750.860, text: 'Ad esempio, il lutto, quando uno dei genitori o un familiare' },
  { start: 750.861, end: 755.020, text: 'stretto muore, lo studente perde la capacità di apprendere.' },
  { start: 756.060, end: 761.107, text: 'Possiamo citare anche gli studenti che sono genitori,' },
  { start: 761.108, end: 765.220, text: 'vedremo che è lo stesso volume delle persone <font color="#FFFF00">disabili</font>.' },
  { start: 765.980, end: 771.180, text: 'Gli studenti in <font color="#FFFF00">precarietà</font> digitale, finanziaria o abitativa,' },
  { start: 771.181, end: 776.380, text: 'cioè che non possono alloggiare nel luogo dove studiano.' },
  { start: 778.295, end: 783.040, text: 'E ciò comporta tempi di spostamento considerevoli per poter venire,' },
  { start: 783.041, end: 787.780, text: 'oppure il fatto che devono trovare un lavoro per pagarsi gli studi,' },
  { start: 788.180, end: 792.200, text: 'e quindi diventano studenti lavoratori.' },
  { start: 792.819, end: 795.637, text: 'Lo status specifico per questo, che è lo status' },
  { start: 795.638, end: 799.580, text: 'di "Apprendista", non si applica a loro.' },
  { start: 799.680, end: 803.760, text: 'Sulle questioni di precarietà, c\'è il caso degli studenti' },
  { start: 803.934, end: 807.960, text: 'che non si nutrono in modo corretto o quotidiano.' },
  { start: 808.740, end: 814.240, text: 'Bisogna tenere conto di questo tipo di ostacoli all\'apprendimento, che sono anche ...' },
  { start: 814.969, end: 819.274, text: 'poco visibili, se non invisibili per alcuni,' },
  { start: 819.275, end: 823.980, text: 'non lo sapremo a meno che lo studente non ce lo dica.' },
  { start: 824.600, end: 828.680, text: 'E questo rappresenta, in media, 1 studentessa su 5.' },
  { start: 828.954, end: 834.660, text: 'E questo può variare a seconda della categoria socio-professionale dello studente.' },
  { start: 838.570, end: 844.670, text: 'Proviamo a fissare i grandi volumi, l\'entità di questi diversi casi.' },
  { start: 844.950, end: 849.990, text: 'Ne ho scelti 6, 5 più la <font color="#FFFF00">disabilità</font>, che è l\'argomento di interesse di oggi,' },
  { start: 849.991, end: 855.810, text: 'intorno alla Genitorialità, alla Salute,' },
  { start: 855.959, end: 862.710, text: 'i problemi di salute al di fuori della <font color="#FFFF00">Disabilità</font>, una categoria che seguo con attenzione,' },
  { start: 862.711, end: 866.190, text: 'la questione degli studenti che sono <font color="#FFFF00">Caregiver</font>,' },
  { start: 866.395, end: 871.950, text: 'per i familiari o altri, la <font color="#FFFF00">Precarietà</font>, che è al tempo stesso...' },
  { start: 871.951, end: 876.450, text: '... finanziaria o altro, e infine il caso particolare degli studenti con un contratto' },
  { start: 876.451, end: 880.470, text: 'di lavoro, che quindi hanno lo status di Studenti-Lavoratori' },
  { start: 881.829, end: 886.090, text: 'La prima categoria, completamente a sinistra, è' },
  { start: 886.091, end: 891.330, text: 'gli Studenti Genitori, che hanno figli, e devono trovare un' },
  { start: 891.331, end: 895.790, text: 'equilibrio tra la loro vita da genitori, occupandosi dei figli ...' },
  { start: 896.025, end: 897.025, text: '... e i loro studi.' },
  { start: 897.395, end: 900.810, text: 'Oggi si stima che ...' },
  { start: 900.811, end: 902.774, text: 'sia più o meno lo stesso volume di' },
  { start: 902.775, end: 905.330, text: '<font color="#FFFF00">Disabilità</font>, cioè intorno al 2%.' },
  { start: 906.619, end: 912.370, text: 'La <font color="#FFFF00">Disabilità</font>, il 2° caso, di cui abbiamo parlato, "visibile" oggi, cioè' },
  { start: 913.504, end: 921.030, text: 'registrata intorno al 2,2%, con 64-68.000 studenti coinvolti, e 1/3 visibile' },
  { start: 921.129, end: 923.750, text: 'e 2/3 non visibile ma dichiarata' },
  { start: 925.419, end: 930.290, text: 'I problemi di salute "ricorrenti", che possono essere tumori, diabete,' },
  { start: 930.291, end: 936.310, text: 'che possono essere varie malattie contratte durante gli studi,' },
  { start: 936.359, end: 940.750, text: 'riguardano comunque il 9% degli studenti, quindi bisogna fare' },
  { start: 940.775, end: 946.950, text: 'attenzione a questi studenti che non mostrano necessariamente di avere un problema' },
  { start: 947.149, end: 952.210, text: 'di salute, ma di cui bisognerà tener conto nel nostro studio.' },
  { start: 954.299, end: 960.490, text: 'I <font color="#FFFF00">Caregiver</font>, studenti della 4ª categoria, spesso presenti' },
  { start: 960.589, end: 965.350, text: 'nelle categorie socio-professionali più modeste, particolarmente nel settore' },
  { start: 965.351, end: 968.063, text: 'agricolo, sono studenti che dedicano' },
  { start: 968.163, end: 972.990, text: 'gran parte del loro tempo ad aiutare un familiare.' },
  { start: 973.239, end: 978.310, text: 'Un genitore, ma può essere anche un fratello, un figlio <font color="#FFFF00">disabile</font>, ecc.' },
  { start: 982.801, end: 985.250, text: 'per anni, non lo si vedeva.' },
  { start: 985.390, end: 990.150, text: 'È intorno al 13-15% nei nostri istituti.' },
  { start: 992.509, end: 997.370, text: 'Il numero 5, la precarietà finanziaria, è oggetto di molti dibattiti,' },
  { start: 997.510, end: 1000.310, text: 'ed è spesso portato avanti dai sindacati studenteschi.' },
  { start: 1000.659, end: 1008.190, text: 'Difficoltà a far quadrare il bilancio, e dover ricorrere a' },
  { start: 1008.191, end: 1011.936, text: 'aiuti finanziari, ma anche alimentari, come il banco' },
  { start: 1011.937, end: 1014.510, text: 'alimentare che si può avere nei propri istituti.' },
  { start: 1015.009, end: 1018.310, text: 'Questo rappresenta oggi 1 studente su 3' },
  { start: 1019.045, end: 1023.870, text: 'E infine l\'ultimo, uno status particolare, quello di Lavoratore,' },
  { start: 1023.989, end: 1027.670, text: 'cioè con un vero Contratto di Lavoro, non qualcuno' },
  { start: 1027.671, end: 1029.985, text: 'che fa lavoretti occasionali ogni tanto, e ci sono' },
  { start: 1029.986, end: 1033.810, text: 'condizioni per stabilire che si tratta di uno Studente-Lavoratore.' },
  { start: 1033.909, end: 1040.230, text: 'Si dice spesso che sia intorno al 10-15%, per l\'apprendistato' },
  { start: 1040.231, end: 1043.770, text: 'è uno status riconosciuto nell\'istruzione (<font color="#FFFF00">FISA</font>, formazione duale).' },
  { start: 1044.750, end: 1050.290, text: 'E c\'è circa il 10% di studenti che sono lavoratori non a tempo pieno' },
  { start: 1050.489, end: 1052.990, text: 'ma che lavorano in modo regolare,' },
  { start: 1052.991, end: 1055.970, text: 'più di 60 ore al mese' },
  { start: 1056.590, end: 1062.150, text: 'e infine, il 10% di studenti che lavorano in modo occasionale.' },
  { start: 1062.324, end: 1063.790, text: 'Durante le vacanze, nei fine settimana,' },
  { start: 1068.610, end: 1069.610, text: 'e soprattutto le vacanze estive.' },
  { start: 1076.490, end: 1084.230, text: 'Esistono disposizioni per aiutare questi studenti' },
  { start: 1084.304, end: 1088.110, text: 'che hanno una <font color="#FFFF00">disabilità</font>, anche se non è ufficialmente chiamata disabilità,' },
  { start: 1088.230, end: 1092.087, text: 'comunque, un ostacolo al loro apprendimento, quindi ho' },
  { start: 1092.088, end: 1095.190, text: 'ripreso questi 6 casi che ho appena presentato:' },
  { start: 1096.299, end: 1100.750, text: 'Studente-Genitore, studente con <font color="#FFFF00">Disabilità</font>, studenti con un problema di salute,' },
  { start: 1101.790, end: 1107.390, text: 'Studente-<font color="#FFFF00">Caregiver</font>, lo studente in precarietà finanziaria o altro.' },
  { start: 1107.730, end: 1113.270, text: 'E infine, Studente-Lavoratore. E ho esaminato cosa esiste' },
  { start: 1113.294, end: 1117.650, text: 'oggi a livello legale, a disposizione di questi studenti.' },
  { start: 1118.049, end: 1122.710, text: 'Con 3 casi che descriverò in dettaglio, i casi "Prioritari",' },
  { start: 1122.910, end: 1130.210, text: 'che è un <font color="#FFFF00">Regime Speciale di Studi</font> (<font color="#FFFF00">RSE</font>), o in mancanza di ciò ...' },
  { start: 1130.211, end: 1134.330, text: 'condizioni adattate per l\'organizzazione del lavoro.' },
  { start: 1136.339, end: 1142.530, text: 'Poi, vedrò se sono stati previsti <font color="#FFFF00">Esami Adattati</font> per' },
  { start: 1142.531, end: 1147.810, text: 'queste persone, e infine, se esiste un <font color="#FFFF00">Contratto di Formazione</font>' },
  { start: 1149.090, end: 1153.668, text: 'o un piano specifico, per aiutare questi studenti' },
  { start: 1153.669, end: 1159.570, text: 'a superare questi ostacoli formativi.' },
  { start: 1160.419, end: 1165.270, text: 'Ho aggiunto due caselle che non dettaglierò, che sono' },
  { start: 1165.271, end: 1170.290, text: 'Aiuti Finanziari e Accesso Prioritario all\'alloggio, che possono' },
  { start: 1170.589, end: 1173.990, text: 'applicarsi a questi studenti.' },
  { start: 1174.299, end: 1178.510, text: 'Ad esempio, il pasto del CROUS a 1€ oggi si applica a tutti.' },
  { start: 1179.949, end: 1183.990, text: 'Cominciamo con lo Studente-Genitore e il suo regime speciale.' },
  { start: 1184.449, end: 1190.570, text: 'Ci sono effettivamente diritti per questi studenti: orari adattati,' },
  { start: 1190.571, end: 1196.270, text: 'comunque scelte prioritarie per organizzare il proprio tempo,' },
  { start: 1196.271, end: 1199.730, text: 'in modo da conciliare la vita familiare e gli studi.' },
  { start: 1200.170, end: 1202.570, text: 'È la legge sulla "Prima Infanzia" a prevalere in questo caso.' },
  { start: 1202.749, end: 1205.250, text: 'Bisogna poter occuparsi del proprio figlio.' },
  { start: 1206.529, end: 1213.370, text: 'Se guardiamo al genitore, ha anche la possibilità di adattare gli Esami' },
  { start: 1213.419, end: 1218.990, text: 'con spostamenti delle prove o recuperi dedicati quando' },
  { start: 1219.304, end: 1221.855, text: 'necessario, ma in genere,' },
  { start: 1221.856, end: 1224.810, text: 'questi studenti sono ben organizzati per questo.' },
  { start: 1225.490, end: 1228.610, text: 'D\'altra parte, non c\'è riconoscimento del loro status tramite un ...' },
  { start: 1228.611, end: 1231.930, text: 'Piano di Formazione o un <font color="#FFFF00">Contratto di Formazione</font> specifico.' },
  { start: 1234.429, end: 1238.330, text: 'Il caso dello studente <font color="#FFFF00">Disabile</font>, la 2ª colonna, è molto più conosciuto' },
  { start: 1239.170, end: 1245.710, text: 'Ha effettivamente un (<font color="#FFFF00">RSE</font>) <font color="#FFFF00">Regime Speciale di Studi</font>, che comporta un adattamento' },
  { start: 1245.884, end: 1251.890, text: 'preciso del suo orario, organizzato dalla commissione o dal <font color="#FFFF00">referente disabilità</font>.' },
  { start: 1253.070, end: 1258.450, text: 'E dispone anche di un <font color="#FFFF00">esonero dalla frequenza</font> se necessario.' },
  { start: 1260.890, end: 1266.010, text: 'Per gli esami o le verifiche, può disporre, in base alla sua' },
  { start: 1266.159, end: 1268.650, text: 'situazione e alle raccomandazioni della commissione,' },
  { start: 1269.979, end: 1273.990, text: 'di <font color="#FFFF00">Tempo Aggiuntivo</font>, di <font color="#FFFF00">Assistenza Umana</font>, di <font color="#FFFF00">materiale adattato</font>. Attenzione, un' },
  { start: 1273.991, end: 1277.949, text: '<font color="#FFFF00">materiale adattato</font> serve ad aiutarlo nell\'ambito' },
  { start: 1277.950, end: 1280.770, text: 'della sua <font color="#FFFF00">disabilità</font>, non a rendergli le cose più facili.' },
  { start: 1281.369, end: 1287.230, text: 'Si tratta di evitare che la <font color="#FFFF00">Disabilità</font> ostacoli la comprensione dell\'esame.' },
  { start: 1287.850, end: 1290.610, text: 'E in alcuni casi, può anche esserci un box isolato ...' },
  { start: 1291.429, end: 1293.010, text: '... o una stanza isolata.' },
  { start: 1293.224, end: 1297.790, text: 'Tutto ciò è disciplinato da un <font color="#FFFF00">Contratto di Formazione</font>, che è un <font color="#FFFF00">Contratto Personalizzato</font>' },
  { start: 1298.089, end: 1304.710, text: 'elaborato dalla Commissione, o dal servizio, o dal' },
  { start: 1304.711, end: 1306.950, text: 'referente <font color="#FFFF00">Disabilità</font>, e che è vincolante per l\'istituto.' },
  { start: 1309.539, end: 1313.333, text: 'Per il 3° caso, 3ª colonna, nell\'ambito di una studentessa' },
  { start: 1313.334, end: 1317.090, text: 'o di uno studente con un problema di salute.' },
  { start: 1318.529, end: 1320.543, text: 'dispone anche di un (<font color="#FFFF00">RSE</font>) <font color="#FFFF00">Regime Speciale di Studi</font> nei momenti in cui ha problemi' },
  { start: 1320.544, end: 1323.970, text: 'di salute, con esoneri' },
  { start: 1323.970, end: 1330.630, text: 'occasionali (per la persona disabile era permanente)' },
  { start: 1330.631, end: 1332.530, text: 'dalla frequenza ...' },
  { start: 1332.990, end: 1339.130, text: 'se è giustificato: bisogna avere un appuntamento,' },
  { start: 1339.131, end: 1342.650, text: 'cure mediche, non può essere una cosa generale.' },
  { start: 1342.749, end: 1345.810, text: 'Qui, deve essere giustificato.' },
  { start: 1346.119, end: 1349.790, text: 'Per quanto riguarda gli esami, è più o meno la stessa cosa della disabilità,' },
  { start: 1349.850, end: 1354.110, text: 'con <font color="#FFFF00">Tempo Aggiuntivo</font>, <font color="#FFFF00">Tempo Extra</font> come nel caso della' },
  { start: 1354.111, end: 1356.725, text: 'studentessa <font color="#FFFF00">Disabile</font>, con una decisione del' },
  { start: 1356.726, end: 1359.270, text: 'tutor o comunque di un responsabile Pedagogico.' },
  { start: 1361.339, end: 1364.590, text: 'Per il <font color="#FFFF00">Contratto di Formazione</font>, è locale, è con l\'università.' },
  { start: 1365.190, end: 1371.450, text: 'Non c\'è alcuna esigenza particolare, è un Protocollo d\'intesa Sanitario' },
  { start: 1371.724, end: 1373.870, text: 'tra la Studentessa e l\'Università.' },
  { start: 1376.050, end: 1382.230, text: 'Nel caso del <font color="#FFFF00">Caregiver</font>, la 4ª colonna, possono iscriversi a un gruppo' },
  { start: 1382.231, end: 1384.570, text: 'o scegliere un gruppo speciale di lezioni ...' },
  { start: 1384.571, end: 1387.630, text: 'in modo da adattare il loro Orario.' },
  { start: 1388.050, end: 1393.770, text: 'serve ad aiutarli e a dare loro il tempo di svolgere il loro ruolo di <font color="#FFFF00">Caregiver</font>.' },
  { start: 1394.350, end: 1396.999, text: 'Può anche esserci un\'Autorizzazione Speciale' },
  { start: 1397.000, end: 1399.790, text: 'di Assenza, o nel caso di un esame.' },
  { start: 1400.439, end: 1405.770, text: 'Bisogna davvero avere una buona motivazione, una giustificazione, per ottenere' },
  { start: 1405.919, end: 1407.910, text: 'un\'Autorizzazione di Assenza.' },
  { start: 1408.904, end: 1413.610, text: 'Naturalmente, se hanno un\'Autorizzazione, hanno un recupero personalizzato.' },
  { start: 1415.050, end: 1420.190, text: 'Ad oggi non c\'è un <font color="#FFFF00">Contratto di Formazione</font> per gli studenti <font color="#FFFF00">Caregiver</font>,' },
  { start: 1420.191, end: 1423.990, text: 'che rappresentano, come ho detto, dal 12 al 15% della popolazione oggi.' },
  { start: 1426.629, end: 1432.130, text: 'Non è stata prevista alcuna disposizione per la colonna n°5, che è il caso della' },
  { start: 1432.131, end: 1436.490, text: '<font color="#FFFF00">Precarietà</font>, sia essa Finanziaria, Digitale, ecc.' },
  { start: 1445.119, end: 1451.150, text: 'L\'ultimo è lo Studente-Lavoratore, e per Studente-Lavoratore intendo...' },
  { start: 1451.274, end: 1454.210, text: 'uno studente che ha un <font color="#FFFF00">Contratto di Lavoro</font> con un\'azienda.' },
  { start: 1454.869, end: 1461.030, text: 'Può essere un contratto a tempo determinato, indeterminato, o qualsiasi altro Contratto di Progetto.' },
  { start: 1461.031, end: 1465.590, text: 'Quindi, nell\'istruzione, a volte si parla di questi contratti, ecc.' },
  { start: 1467.374, end: 1470.815, text: 'Questo non riguarda i contratti piuttosto consistenti,' },
  { start: 1470.816, end: 1473.230, text: 'non è un piccolo lavoro di un\'ora a settimana.' },
  { start: 1473.710, end: 1479.110, text: 'Qui parliamo di un adeguamento quando il carico di lavoro del <font color="#FFFF00">Contratto di Lavoro</font>' },
  { start: 1479.559, end: 1485.770, text: 'è dell\'ordine di 60 ore al mese o 120 ore a trimestre' },
  { start: 1486.044, end: 1488.833, text: 'Quindi, questa è la situazione più favorevole (60h/mese o 120h/trimestre)' },
  { start: 1488.834, end: 1490.970, text: 'da tenere in considerazione per lo studente.' },
  { start: 1491.515, end: 1496.550, text: 'E in questo caso, se lo studente ha un Contratto di Lavoro di 60 h/mese,' },
  { start: 1496.950, end: 1498.190, text: 'o di 120 h/trimestre' },
  { start: 1499.204, end: 1502.731, text: 'L\'Orario deve essere adeguato, obbligatoriamente,' },
  { start: 1502.781, end: 1504.890, text: 'il Lavoro prevale sull\'Insegnamento' },
  { start: 1507.559, end: 1512.350, text: 'Se questo riguarda gli esami o le verifiche delle conoscenze,' },
  { start: 1512.899, end: 1516.390, text: 'possono esserci esoneri in alcune valutazioni continue' },
  { start: 1517.590, end: 1521.170, text: 'E poi, naturalmente, prove adattate, ad esempio a distanza,' },
  { start: 1521.329, end: 1522.730, text: 'se necessario.' },
  { start: 1525.280, end: 1530.210, text: 'Per quanto riguarda lo status di Studente-Lavoratore, esiste un contratto' },
  { start: 1530.434, end: 1534.210, text: 'specifico, <font color="#FFFF00">FISA</font> (Formazione Iniziale in regime di Apprendistato), che è il <font color="#FFFF00">Contratto di Apprendistato</font>' },
  { start: 1534.419, end: 1536.350, text: 'Gli altri non sono interessati ...' },
  { start: 1536.590, end: 1542.910, text: 'cioè i contratti a tempo determinato e indeterminato non sono coperti da un Piano' },
  { start: 1542.911, end: 1547.110, text: 'o da un <font color="#FFFF00">Contratto di Formazione</font> Specifico, questo riguarda solo l\'Apprendistato,' },
  { start: 1547.369, end: 1549.290, text: 'in Francia, e nessun altro.' },
  { start: 1551.740, end: 1557.880, text: 'Aiuti Finanziari ... Accesso Prioritario ..., vi lascio leggere cosa esiste.' },
  { start: 1557.880, end: 1563.822, text: 'Esistono molte disposizioni da conoscere per' },
  { start: 1563.823, end: 1567.060, text: 'aiutare gli studenti quando ne hanno bisogno.' },
  { start: 1572.109, end: 1578.650, text: 'Ci concentreremo sul caso dello studente <font color="#FFFF00">Disabile</font>, perché dietro la disabilità,' },
  { start: 1578.885, end: 1582.050, text: 'o comunque l\'adattamento, c\'è un protocollo rigoroso.' },
  { start: 1582.294, end: 1586.790, text: 'Va applicato, in ogni caso, per evitare i contenziosi legali che si presentano sempre più' },
  { start: 1586.791, end: 1589.750, text: 'spesso, in particolare nelle scuole private.' },
  { start: 1589.870, end: 1590.962, text: 'Nelle scuole pubbliche ce ne sono un po\' meno ...' },
  { start: 1590.963, end: 1593.590, text: 'ma nelle scuole private, si vedono comparire' },
  { start: 1594.729, end: 1600.170, text: 'Questa organizzazione è descritta nelle Leggi e nei Codici dell\'Istruzione,' },
  { start: 1600.550, end: 1603.771, text: 'prevede una catena di decisioni che' },
  { start: 1603.772, end: 1606.890, text: 'parte dallo studente, che deve dichiararsi.' },
  { start: 1607.274, end: 1611.870, text: 'non si può fare nulla senza la dichiarazione dello studente, e la sua applicazione' },
  { start: 1612.230, end: 1613.230, text: 'da parte dell\'insegnante.' },
  { start: 1614.150, end: 1618.050, text: 'Non c\'è applicazione diretta, è rigorosamente vietata.' },
  { start: 1618.104, end: 1620.135, text: 'Uno studente che va da un insegnante e dice' },
  { start: 1620.215, end: 1621.950, text: '"beh, ho questo problema ...' },
  { start: 1622.299, end: 1626.350, text: 'per favore adatti la mia verifica!" ...è spesso proprio al momento delle verifiche che questo accade' },
  { start: 1628.169, end: 1634.250, text: 'Non è possibile. L\'insegnante non è in grado' },
  { start: 1634.251, end: 1637.986, text: 'di giudicare, non è un medico, non è formato' },
  { start: 1637.987, end: 1640.370, text: 'specificamente per riconoscere una <font color="#FFFF00">disabilità</font>.' },
  { start: 1640.774, end: 1642.510, text: 'Non deve farlo.' },
  { start: 1643.249, end: 1646.430, text: 'E se lo fa, può esserci un contenzioso con un altro studente,' },
  { start: 1647.414, end: 1651.250, text: 'perché quest\'ultimo può dire, <i>"Lui è stato favorito e io no, perché</i>' },
  { start: 1651.251, end: 1653.965, text: '<i>ha detto una certa cosa, e io sono svantaggiato</i>' },
  { start: 1653.966, end: 1656.170, text: '<i>perché non ho avuto <font color="#FFFF00">Tempo Aggiuntivo</font>"</i>, ecc.' },
  { start: 1656.909, end: 1662.150, text: 'Bisogna davvero essere seri e rifiutare questo tipo di richiesta, in ogni caso!' },
  { start: 1662.151, end: 1668.450, text: 'l\'insegnante non deve adattare la propria lezione su richiesta dello studente.' },
  { start: 1669.230, end: 1675.950, text: 'Lo studente deve segnalare la situazione a un Servizio, a un Dipartimento o a un' },
  { start: 1676.099, end: 1680.670, text: 'Referente <font color="#FFFF00">Disabilità</font> (obbligatorio nelle scuole), che studierà la situazione.' },
  { start: 1681.979, end: 1686.970, text: 'Se ha bisogno di aiuto, può rivolgersi al medico designato dalla ...' },
  { start: 1686.971, end: 1693.650, text: '<font color="#FFFF00">Commissione per i Diritti e l\'Autonomia delle Persone con Disabilità (CDAPH)</font>' },
  { start: 1694.349, end: 1697.730, text: 'che si trova presso l\'ufficio dipartimentale per le persone con <font color="#FFFF00">Disabilità</font>' },
  { start: 1697.731, end: 1701.910, text: 'e che lo aiuterà a fare una diagnosi della situazione.' },
  { start: 1703.559, end: 1710.610, text: 'Una volta stabilito il legame tra lo studente e il referente, e' },
  { start: 1710.859, end: 1716.010, text: 'una volta che si constata effettivamente una <font color="#FFFF00">disabilità</font>, e non un' },
  { start: 1716.011, end: 1721.570, text: 'deficit linguistico, o un problema di padronanza della lingua francese,' },
  { start: 1722.390, end: 1728.510, text: 'si inizierà a redigere un bilancio che valuti tutti i bisogni secondo' },
  { start: 1728.511, end: 1733.190, text: 'la legge, ossia l\'Organizzazione, lo Svolgimento delle lezioni' },
  { start: 1733.264, end: 1736.459, text: 'e l\'Accompagnamento. Non c\'è, a priori, a livello' },
  { start: 1736.460, end: 1740.210, text: 'legale, un capitolo specifico sulle verifiche.' },
  { start: 1741.759, end: 1746.077, text: 'Su questi 3 capitoli, Organizzazione-Svolgimento-' },
  { start: 1746.078, end: 1748.770, text: 'Accompagnamento, non serve un parere medico.' },
  { start: 1749.350, end: 1754.970, text: 'Qui, è il responsabile Pedagogico, o il referente <font color="#FFFF00">Disabilità</font>, ad essere' },
  { start: 1754.971, end: 1759.210, text: 'il responsabile di questo piano di Accompagnamento.' },
  { start: 1760.259, end: 1763.510, text: 'D\'altra parte, in alcuni casi, se non è mai stato fatto.' },
  { start: 1763.970, end: 1767.274, text: 'Bisogna sapere che l\'<font color="#FFFF00">adattamento degli esami</font>' },
  { start: 1767.275, end: 1770.670, text: 'può richiedere un <u>parere obbligatorio di un medico.</u>' },
  { start: 1778.111, end: 1782.210, text: 'per esempio, o in altri casi di <font color="#FFFF00">disabilità invisibile</font>, è risaputo,' },
  { start: 1783.330, end: 1787.830, text: 'Ma è un medico che lo dichiarerà, che lo richiederà.' },
  { start: 1787.831, end: 1789.870, text: 'In ogni caso, serve un parere medico.' },
  { start: 1790.184, end: 1792.830, text: 'Non può essere concesso altrimenti.' },
  { start: 1794.250, end: 1799.270, text: 'Una volta effettuata la valutazione dei bisogni, si applica all\'istituto,' },
  { start: 1799.271, end: 1803.750, text: 'e spetta all\'istituto, (che ha l\'autorità gerarchica)' },
  { start: 1803.751, end: 1808.710, text: 'farlo rispettare a tutti e, in particolare, agli insegnanti, che avranno' },
  { start: 1808.711, end: 1815.110, text: 'la persona, lo studente o la studentessa, nella loro classe, durante la' },
  { start: 1815.334, end: 1818.790, text: 'formazione, o durante la verifica delle conoscenze.' },
  { start: 1824.939, end: 1828.260, text: 'Ho detto che l\'insegnante non è in grado di valutare...' },
  { start: 1828.300, end: 1834.160, text: '... il bisogno e, in ogni caso, di dare un parere medico sulla persona.' },
  { start: 1835.280, end: 1837.460, text: 'È vero, ma questo non impedisce la formazione.' },
  { start: 1837.634, end: 1839.818, text: 'Non solo non la impedisce, ma' },
  { start: 1839.819, end: 1843.400, text: 'preciso che questa formazione è <u>Obbligatoria.</u>' },
  { start: 1843.699, end: 1848.340, text: 'Ciò significa che rientra nell\'ambito delle <u>Formazioni Obbligatorie</u> che un datore di lavoro deve' },
  { start: 1848.341, end: 1853.400, text: 'dare al proprio dipendente, come ad esempio le Formazioni sulla Sicurezza.' },
  { start: 1855.064, end: 1859.700, text: 'Quindi questa formazione è obbligatoria, è stata introdotta fin dall\'inizio nella ...' },
  { start: 1859.701, end: 1863.140, text: '... legge del 2005, ed è stata poi confermata nelle' },
  { start: 1863.141, end: 1867.300, text: 'varie leggi, l\'ultima del 15 novembre 2014.' },
  { start: 1867.849, end: 1871.280, text: 'Chiamata legge della "Scuola della Fiducia", che è un po\' più ampia,' },
  { start: 1871.614, end: 1873.300, text: 'e molto più <font color="#FFFF00">inclusiva</font>.' },
  { start: 1874.135, end: 1878.180, text: 'Dice che gli insegnanti, ma anche tutto il personale direttivo ...' },
  { start: 1878.354, end: 1883.260, text: 'tecnico, di servizio, ecc, e di accoglienza, devono ricevere, nel corso della loro formazione,' },
  { start: 1883.260, end: 1888.500, text: 'se è una formazione iniziale, ad esempio per gli insegnanti, ma anche durante' },
  { start: 1888.501, end: 1891.240, text: 'lo svolgimento del loro lavoro,' },
  { start: 1891.475, end: 1892.475, text: 'nell\'ambito della <font color="#FFFF00">Formazione Continua</font>,' },
  { start: 1892.774, end: 1896.660, text: 'una formazione specifica sull\'accoglienza/educazione degli alunni e' },
  { start: 1896.661, end: 1901.200, text: 'degli studenti in situazione di <font color="#FFFF00">disabilità</font>, e non so perché questa frase...' },
  { start: 1901.420, end: 1902.420, text: 'sia lì, ma c\'è.' },
  { start: 1902.780, end: 1906.560, text: '"<i>In particolare, o soprattutto quelli che presentano un</i>' },
  { start: 1906.561, end: 1910.240, text: 'disturbo del comportamento o un <i><font color="#FFFF00">disturbo del neurosviluppo</font>.</i>' },
  { start: 1911.669, end: 1914.980, text: 'Una piccola frase di passaggio, nel caso dell\'Apprendistato,' },
  { start: 1915.894, end: 1920.100, text: 'e penso agli studenti tecnici che sono spesso in laboratorio o in pratica,' },
  { start: 1921.180, end: 1924.400, text: 'l\'<font color="#FFFF00">inclusione</font> non riguarda solo l\'<font color="#FFFF00">accessibilità</font> delle' },
  { start: 1924.974, end: 1927.580, text: 'aule, ma riguarda l\'intero laboratorio,' },
  { start: 1927.620, end: 1929.540, text: 'il ritmo dell\'alternanza, l\'azienda.' },
  { start: 1930.980, end: 1938.400, text: 'E bisogna essere precisi, in particolare sulle pratiche di sicurezza e salute.' },
  { start: 1944.344, end: 1947.840, text: 'Di conseguenza, e per chiudere' },
  { start: 1947.841, end: 1952.000, text: 'questo capitolo sulle osservazioni, vi presento un elenco non esaustivo' },
  { start: 1952.460, end: 1957.860, text: 'di formazioni che si possono applicare.' },
  { start: 1958.160, end: 1963.440, text: 'quindi, formazioni obbligatorie, che si possono applicare a tutto il' },
  { start: 1963.441, end: 1967.300, text: 'personale, direttivo, di accoglienza, e di accompagnamento.' },
  { start: 1968.674, end: 1973.318, text: 'La prima è molto conosciuta, è la formazione "<font color="#FFFF00">Cap Ecole Inclusive</font>" (Scuola Inclusiva)' },
  { start: 1973.319, end: 1976.460, text: 'che è stata sviluppata da diversi anni.' },
  { start: 1976.554, end: 1981.400, text: 'non c\'è solo formazione, ma anche risorse pedagogiche' },
  { start: 1981.401, end: 1984.516, text: 'è un\'intera piattaforma che è stata sviluppata' },
  { start: 1984.517, end: 1987.340, text: 'attorno agli elementi di "Confiance" (Fiducia).' },
  { start: 1988.990, end: 1993.760, text: 'Quindi, è più della <font color="#FFFF00">Disabilità</font>, è l\'<font color="#FFFF00">Inclusività</font>' },
  { start: 1994.320, end: 1995.700, text: 'in generale.' },
  { start: 1997.859, end: 2002.260, text: 'Per "Paralysés de France", è un\'associazione.' },
  { start: 2003.259, end: 2008.380, text: 'C\'è anche una formazione sulla questione dell\'<font color="#FFFF00">accessibilità</font>, dell\'<font color="#FFFF00">inclusione</font>,' },
  { start: 2008.585, end: 2013.580, text: 'riguarda soprattutto le persone con <font color="#FFFF00">disabilità motoria</font>, seguite da questa associazione.' },
  { start: 2014.154, end: 2016.440, text: 'Intervengono sul posto, possono intervenire' },
  { start: 2016.519, end: 2021.480, text: 'nel vostro istituto e presso l\'amministrazione generale.' },
  { start: 2023.769, end: 2030.140, text: 'Il 3° è un MOOC, piuttosto originale, realizzato dall\'AFPA,' },
  { start: 2030.141, end: 2034.100, text: 'chiamato "<font color="#FFFF00">Disabilità</font>, chiavi d\'azione verso l\'occupazione"' },
  { start: 2034.734, end: 2039.740, text: 'È, in generale, ben strutturato, sul tema della <font color="#FFFF00">disabilità</font>' },
  { start: 2040.699, end: 2044.100, text: 'per l\'<font color="#FFFF00">inclusione</font>, nella formazione e nell\'occupazione.' },
  { start: 2044.101, end: 2050.060, text: 'Quindi, molto ampio, è una formazione a distanza riconosciuta, che ha vinto' },
  { start: 2050.385, end: 2055.300, text: 'il premio "Open Educaton Night 2023"' },
  { start: 2055.380, end: 2056.388, text: 'Non c\'è nessun errore di ortografia' },
  { start: 2056.389, end: 2060.239, text: 'Si scrive proprio "EduCaton" così' },
  { start: 2060.739, end: 2064.300, text: 'In mancanza di ciò, se non sapete quale scegliere, potete fare questa' },
  { start: 2064.301, end: 2068.159, text: 'e notificare che le persone hanno completato questo MOOC.' },
  { start: 2071.110, end: 2077.159, text: 'Il 4° sono le piattaforme o tutte le formazioni proposte dall\'Unione' },
  { start: 2077.360, end: 2082.159, text: 'Nazionale delle Famiglie e degli Amici di <font color="#FFFF00">Persone con Malattia Mentale e/o Disabilità Psichica</font>' },
  { start: 2083.280, end: 2089.290, text: 'Questo non è rivolto alle persone con disabilità, è per i professionisti.' },
  { start: 2092.290, end: 2096.590, text: 'Se ci concentriamo sui <font color="#FFFF00">DSA</font>, c\'è la Federazione Francese dei <font color="#FFFF00">DSA</font>,' },
  { start: 2096.770, end: 2100.920, text: 'che offre formazioni nei 6 ambiti' },
  { start: 2100.921, end: 2104.370, text: 'dei <font color="#FFFF00">disturbi cognitivi</font> dei <font color="#FFFF00">DSA</font>, per l\'istruzione' },
  { start: 2104.495, end: 2110.090, text: 'superiore e per l\'ambito professionale, molto bene.' },
  { start: 2110.370, end: 2113.170, text: 'Un po\' caro per i miei gusti, ma di grande qualità.' },
  { start: 2114.230, end: 2120.410, text: 'Infine non dimentichiamo che ci si può formare anche su altre tematiche, altre' },
  { start: 2120.411, end: 2124.610, text: 'lingue, e in particolare sulla <font color="#FFFF00">lingua dei segni francese</font>.' },
  { start: 2125.740, end: 2128.930, text: 'ci sono associazioni e una piattaforma di formazione online' },
  { start: 2129.750, end: 2137.250, text: 'chiamata "Signes de Sens", che permette di imparare la lingua dei' },
  { start: 2137.251, end: 2139.909, text: 'segni, scusate, per l\'<font color="#FFFF00">inclusione</font> delle persone con problemi di udito, comunque delle persone che hanno difficoltà uditive.' },

  { start: 2139.910, end: 2144.000, text: 'Grazie per la vostra attenzione. Andate al capitolo 2.' },
];


